window.EXPL={"관세사2017_34-19-1":{"f":"세관장은 납세신고를 받으면 수입신고서에 기재된 사항 등을 심사하되, 신고한 세액에 대하여는 수입신고를 수리한 후에 심사한다.","w":"세액심사는 수입신고를 수리한 뒤에 하는 것이 원칙이다. 관세채권 확보가 곤란하다고 재정경제부령으로 정한 물품만 수리 전에 심사한다(관세법 제38조제2항).","c":"상","v":1},"관세사2018_35-02-1":{"f":"신고납부에 따른 납세신고를 한 경우에는 납세신고 수리일부터 15일 이내이다.","w":"납세신고를 한 경우 관세 납부기한은 납세신고 수리일부터 15일 이내이다(관세법 제9조제1항제1호).","c":"상","v":1},"관세사2018_35-02-3":{"f":"수입신고전 즉시반출신고를 한 경우에는 수입신고일부터 15일 이내이다.","w":"수입신고전 즉시반출신고를 한 경우 납부기한은 수입신고일부터 15일 이내이다(관세법 제9조제1항제3호).","c":"상","v":1},"관세사2018_35-02-4":{"f":"납세의무자는 수입신고가 수리되기 전에 해당 세액을 납부할 수 있다.","w":"납세의무자는 납부기한 전이라도 수입신고가 수리되기 전에 해당 세액을 납부할 수 있다(관세법 제9조제2항).","c":"상","v":1},"관세사2018_35-02-5":{"f":"세관장은 납세실적 등을 고려하여 관세청장이 정하는 요건을 갖춘 성실납세자가 대통령령으로 정하는 바에 따라 신청을 할 때에는 납부기한이 동일한 달에 속하는 세액에 대하여는 그 기한이 속하는 달의 말일까지 한꺼번에 납부하게 할 수 있다.","w":"월별납부를 허용하는 주체는 세관장이고, 성실납세자 요건은 관세청장이 정한다. 한꺼번에 내는 기한은 납부기한이 속하는 달의 말일이다(관세법 제9조제3항).","c":"상","v":1},"관세사2018_35-03-2":{"f":"세관장은 담보를 관세에 충당하고 남은 금액이 있을 때에는 담보를 제공한 자에게 이를 돌려주어야 하며, 돌려줄 수 없는 경우에는 이를 공탁할 수 있다.","w":"담보를 관세에 충당하고 남은 금액을 돌려줄 수 없을 때에는 세관장이 공탁할 수 있다(관세법 제25조제2항).","c":"상","v":1},"관세사2018_35-05-5":{"f":"교부청구는 관세징수권의 소멸시효 중단사유에 해당된다.","w":"관세징수권 소멸시효의 중단사유는 납부고지, 경정처분, 납부독촉, 통고처분, 고발, 공소제기, 교부청구, 압류이다(관세법 제23조제1항).","c":"상","v":1},"관세사2018_35-08-1":{"f":"납세의무자는 납세신고한 세액을 납부하기 전에 그 세액이 과부족(過不足)하다는 것을 알게 되었을 때에는 납세신고한 세액을 정정할 수 있다.","w":"납부 전에 세액이 모자라거나 넘친다는 것을 알면 납세신고한 세액을 정정할 수 있다. 이때 납부기한은 당초 납부기한 그대로다(관세법 제38조제5항).","c":"상","v":1},"관세사2018_35-09-2":{"f":"세관장은 관세법 제38조의3 제2항 또는 제3항에 따른 경정의 청구를 받은 날부터 2개월 이내에 세액을 경정하거나 경정하여야 할 이유가 없다는 뜻을 그 청구를 한 자에게 통지하여야 한다.","w":"경정청구에 대한 세관장의 통지기한은 청구를 받은 날부터 2개월이다. 2개월 안에 통지가 없으면 그 다음 날부터 이의신청·심사청구·심판청구를 할 수 있다(관세법 제38조의3제4항·제5항).","c":"상","v":1},"관세사2018_35-10-4":{"f":"세관장이 징수하는 내국세를 포함한 체납된 관세가 100만원 미만인 경우에는 중가산금을 징수하지 않는다.","w":"출제 당시 체납 관세(내국세 포함)가 100만원 미만이면 매달 붙는 중가산금(1천분의 12)만 빠지고 100분의 3 가산금은 그대로 징수했다(구 관세법 제41조). 현행은 가산금이 납부지연가산세로 바뀌어, 150만원 미만이면 일수에 따라 붙는 부분만 적용하지 않는다(관세법 제42조제5항).","c":"상","v":1},"관세사2019_36-02-3":{"f":"관세체납정리위원회의 공무원이 아닌 위원의 임기는 2년으로 하되, 한 번만 연임할 수 있다.","w":"위원장은 세관장이 되고, 변호사·관세사·상공계 대표 등 민간 위원의 임기가 2년이며 한 번만 연임할 수 있다(관세법 시행령 제42조).","c":"상","v":1},"관세사2019_36-07-2":{"f":"세관장은 담보를 제공한 납세의무자가 그 납부기한까지 해당 관세를 납부하지 아니하면 재정경제부령으로 정하는 바에 따라 그 담보를 해당 관세에 충당할 수 있다.","w":"담보를 관세에 충당하는 주체는 세관장이다(관세법 제25조제1항).","c":"상","v":1},"관세사2020_37-05-1":{"f":"세관장은 납세담보의 제공을 받은 관세 및 체납처분비가 납부되었을 때에는 지체 없이 담보해제의 절차를 밟아야 한다.","w":"납세담보를 제공받은 관세와 강제징수비가 납부되면 세관장은 지체 없이 담보를 해제하는 절차를 밟는다. 10일 같은 기한은 없다(관세법 제26조의2).","c":"상","v":1},"관세사2020_37-07-3":{"f":"관세의 환급청구권은 그 권리를 행사할 수 있는 날부터 5년간 행사하지 아니하면 소멸시효가 완성된다.","w":"관세 환급청구권의 소멸시효는 권리를 행사할 수 있는 날부터 5년이다(관세법 제22조제2항).","c":"상","v":1},"관세사2020_37-10-1":{"f":"세관장은 납세의무자가 납부하여야 하는 세액이 1만원 미만인 경우에는 이를 징수하지 아니한다.","w":"세관장이 징수하지 않는 세액은 1만원 미만이다. 3만원은 징수한다(관세법 제40조, 시행령 제37조제1항).","c":"상","v":1},"관세사2020_37-10-3":{"f":"관세납부대행기관이 받는 납부대행수수료는 관세청장이 관세납부대행기관의 운영경비 등을 종합적으로 고려하여 승인하되, 해당 관세의 1천분의 10을 초과할 수 없다.","w":"납부대행수수료는 관세청장이 승인하며, 해당 납부세액의 1천분의 10을 넘을 수 없다(관세법 시행규칙 제8조의2제2항).","c":"상","v":1},"관세사2020_37-10-4":{"f":"납세의무자는 세액산출의 기초가 되는 과세가격 또는 품목분류 등에 오류가 있는 것을 알게 되었을 때에는 신고납부한 날부터 6개월 이내에 해당 세액을 보정하여 줄 것을 세관장에게 신청할 수 있다.","w":"보정기간은 신고납부한 날부터 6개월이고, 보정 신청은 할 수 있다는 권리이지 의무가 아니다(관세법 제38조의2제1항).","c":"상","v":1},"관세사2020_37-10-5":{"f":"납세의무자가 신고납부한 세액이 부족하다는 것을 알고, 이 부족한 세액에 대한 세액의 보정을 신청한 경우에는 해당 보정신청을 한 날의 다음 날까지 해당 관세를 납부하여야 한다.","w":"보정으로 부족세액을 내는 기한은 보정신청을 한 날의 다음 날까지이다(관세법 제38조의2제4항).","c":"상","v":1},"관세사2022_39-04-5":{"f":"관세의 담보를 제공하고자 하는 자가 담보액의 확정일부터 10일 이내에 담보를 제공하지 아니하는 경우 세관장은 관세법 제39조(부과고지)에 따른 납부고지를 할 수 있다.","w":"담보 제공 기한은 담보액 확정일부터 10일이고, 납부고지를 하는 사람은 세관장이다(관세법 시행령 제10조제9항).","c":"상","v":1},"관세사2022_39-05-1":{"f":"담보를 포괄하여 제공할 수 있는 요건, 그 담보의 종류 기타 필요한 사항은 관세청장이 정한다.","w":"포괄담보의 요건, 담보의 종류 등은 관세청장이 정한다(관세법 시행령 제11조제2항).","c":"상","v":1},"관세사2022_39-07-1":{"f":"납세의무자가 부족한 세액에 대한 세액의 보정을 신청한 경우에는 해당 보정신청을 한 날의 다음 날까지 해당 관세를 납부하여야 한다.","w":"보정신청을 한 날 당일이 아니라 그 다음 날까지 납부해야 한다(관세법 제38조의2제4항).","c":"상","v":1},"관세사2022_39-08-2":{"f":"관세체납정리위원회는 위원장 1인을 포함한 5인 이상 7인 이내의 위원으로 구성한다.","w":"관세체납정리위원회는 위원장 1인을 포함해 5인 이상 7인 이내로 구성한다(관세법 시행령 제42조제2항).","c":"상","v":1},"관세사2023_40-08-1":{"f":"압류는 관세징수권 소멸시효의 중단사유에 해당한다.","w":"압류는 시효가 흘러가는 것을 멈추는 정지사유가 아니라 이미 지난 시효기간을 없애는 중단사유다. 정지사유는 분할납부기간, 징수유예기간, 압류·매각의 유예기간, 사해행위 취소소송기간이다(관세법 제23조제1항·제3항).","c":"상","v":1},"관세사2023_40-08-2":{"f":"7억원의 관세(내국세를 포함한다)의 징수권에 대한 소멸시효는 10년이다.","w":"5억원 이상의 관세(내국세 포함)는 소멸시효가 10년이다. 5억원 미만은 5년이다(관세법 제22조제1항).","c":"상","v":1},"관세사2023_40-08-3":{"f":"관세징수권의 소멸시효는 관세징수권을 행사할 수 있는 날부터 기산한다.","w":"소멸시효는 징수권을 행사할 수 있는 날부터 기산한다. 신고납부 관세는 수입신고 수리일부터 15일이 지난 날의 다음 날이 그 날이다(관세법 제22조, 시행령 제7조).","c":"상","v":1},"관세사2023_40-08-4":{"f":"부과고지하는 관세의 경우 납부고지를 받은 날부터 15일이 경과한 날의 다음 날이 관세징수권 소멸시효의 기산일이다.","w":"부과고지 관세는 납부고지를 받은 날부터 15일이 지난 날의 다음 날부터 시효가 기산된다(관세법 시행령 제7조제1항제3호).","c":"상","v":1},"관세사2023_40-10-1":{"f":"금전은 담보로 제공할 수 있다.","w":"담보의 종류 중 첫째가 금전이다. 국채·지방채, 유가증권, 납세보증보험증권, 토지, 보험에 든 건물 등, 납세보증서도 담보가 된다(관세법 제24조제1항).","c":"상","v":1},"관세사2023_40-10-3":{"f":"담보물인 토지의 평가는 상속세 및 증여세법 제61조를 준용하여 평가한 가액으로 할 수 있다.","w":"토지와 건물은 「상속세 및 증여세법」 제61조를 준용해 평가한다(관세법 시행령 제9조제2항제1호).","c":"상","v":1},"관세사2023_40-10-4":{"f":"보험에 든 건물을 담보로 제공하려는 경우 그 보험기간은 담보를 필요로 하는 기간에 30일 이상을 더한 것이어야 한다.","w":"보험에 든 건물·선박 등을 담보로 제공할 때 보험기간은 담보가 필요한 기간에 30일 이상을 더해야 한다(관세법 시행령 제10조제7항). 필요한 기간만으로는 모자란다.","c":"상","v":1},"관세사2023_40-10-5":{"f":"담보물이 납세보증보험증권인 경우 그 보증인에게 담보한 관세에 상당하는 금액을 납부할 것을 즉시 통보하는 방법으로 관세충당한다.","w":"보증보험증권과 납세보증서는 매각하지 않고 보증인에게 관세 상당액을 납부하라고 즉시 통보한다. 국채·유가증권·토지·건물 등은 매각한다(관세법 시행규칙 제1조의3).","c":"상","v":1},"관세사2023_40-15-2":{"f":"세관장이 부과ㆍ징수하는 내국세는 감치의 대상이 되는 체납 관세에 포함된다.","w":"감치 대상이 되는 체납 관세에는 세관장이 부과·징수하는 내국세등도 들어간다(관세법 제116조의4제1항).","c":"상","v":1},"관세사2024_41-04-2":{"f":"담보물인 토지 또는 건물의 평가는 「상속세 및 증여세법」 제61조를 준용하여 평가한 가액에 따른다.","w":"감정평가법인등의 평가액으로 하는 것은 공장재단·광업재단·선박·항공기·건설기계이다(지방세법상 시가표준액도 가능). 토지와 건물은 상속세 및 증여세법 제61조를 준용한다(관세법 시행령 제9조제2항).","c":"상","v":1},"관세사2024_41-05-1":{"f":"부정환급을 이유로 관세를 징수하는 경우에는 환급한 날의 다음 날을 제척기간의 기산일로 한다.","w":"과다환급·부정환급으로 관세를 징수할 때 제척기간은 환급한 날의 다음 날부터 센다(관세법 시행령 제6조제4호).","c":"상","v":1},"관세사2024_41-05-2":{"f":"납부독촉을 하면 소멸시효가 중단된다.","w":"납부독촉으로 중단되는 것은 징수권의 소멸시효이다. 제척기간은 중단이나 정지가 없는 기간이다(관세법 제23조제1항제3호).","c":"상","v":1},"관세사2024_41-05-3":{"f":"사해행위 취소소송으로 인한 소멸시효 정지의 효력은 소송이 취하된 경우는 물론 각하된 경우에도 소멸된다.","w":"사해행위 취소소송 중 시효정지의 효력은 각하·기각·취하 어느 경우에든 없어진다(관세법 제23조제4항).","c":"상","v":1},"관세사2024_41-05-4":{"f":"압류를 한 경우에는 소멸시효가 중단된다.","w":"시효 중단사유는 압류이고, 가압류는 중단사유로 열거되어 있지 않다(관세법 제23조제1항제8호).","c":"상","v":1},"관세사2024_41-08-1":{"f":"세관장의 세액심사는 수입신고 수리 전에도 할 수 있다.","w":"세액심사는 수리 후가 원칙이다. 관세채권 확보가 곤란하거나 수리 후 심사가 부적당해 재정경제부령으로 정한 물품은 수리 전에 심사한다(관세법 제38조제2항).","c":"상","v":1},"관세사2025_42-03-5":{"f":"적법하게 납부한 후 법률의 개정으로 인하여 환급하는 경우에는 그 법률의 시행일이다.","w":"법률 개정으로 환급할 때 환급청구권을 행사할 수 있는 날은 개정일이 아니라 그 법률의 시행일이다(관세법 시행령 제7조제2항제5호).","c":"상","v":1},"관세사2025_42-09-2":{"f":"위원회의 위원장은 해당 세관의 세관장이 된다.","w":"관세체납정리위원회의 위원장은 해당 세관의 세관장이다. 공무원이 아닌 사람 중에서 세관장 추천으로 관세청장이 위촉하는 사람이 위원장이 되는 위원회는 세관 납세자보호위원회이다(관세법 시행령 제42조제3항, 관세법 제118조의4제5항).","c":"중","v":1},"관세사2026_43-07-2":{"f":"관세의 납부를 보증한 자는 관세법에 따라 계속하여 담보를 제공하여야 하는 사유가 있는 경우 관세청장이 정하는 바에 따라 일정 기간에 제공하여야 하는 담보를 포괄하여 미리 세관장에게 제공할 수 있다.","w":"납세의무자뿐 아니라 관세의 납부를 보증한 자도 포괄담보를 미리 제공할 수 있다(관세법 제24조제4항).","c":"상","v":1},"관세사2026_43-07-3":{"f":"세관장은 관세의 납세의무자가 아닌 자가 관세의 납부를 보증한 경우 그 담보로 관세에 충당하고 남은 금액이 있을 때에는 그 보증인에게 이를 직접 돌려주어야 한다.","w":"보증인이 납세의무자가 아닌 경우 남은 금액은 납세의무자가 아니라 담보를 낸 보증인에게 직접 돌려준다(관세법 제25조제3항).","c":"상","v":1},"관세사2026_43-07-4":{"f":"관세가 확정되지 아니한 경우 담보의 금액은 관세청장이 정하는 금액으로 한다.","w":"관세가 확정되지 않았을 때 담보 금액을 정하는 사람은 관세청장이다(관세법 시행령 제10조제8항).","c":"상","v":1},"관세사2026_43-07-5":{"f":"담보가 없는 경우 세관장은 관세의 강제징수를 할 때에는 공매에 드는 비용에 상당하는 강제징수비를 징수할 수 있다.","w":"강제징수를 할 때 재산의 압류·보관·운반·공매에 드는 비용 상당의 강제징수비를 징수할 수 있다(관세법 제26조제2항).","c":"상","v":1},"관세사2017_34-02-3":{"f":"매각된 물품의 질권자나 유치권자는 다른 법령에도 불구하고 그 물품을 매수인에게 인도하여야 한다.","w":"질권자나 유치권자는 매각된 물품을 매수인에게 인도해야 하고 인도를 거부할 수 없다. 대신 매각한 날부터 1개월 이내에 권리를 증명하는 서류를 내면 잔금에서 담보채권을 교부받는다(관세법 제208조제3항, 제211조).","c":"상","v":1},"관세사2017_34-04-1":{"f":"세관장은 특허보세구역의 운영인이 장치물품에 대한 관세를 납부할 자금능력이 없다고 인정되는 경우에는 관세청장이 정하는 바에 따라 6개월의 범위에서 해당 특허보세구역에의 물품반입을 정지시킬 수 있다.","w":"물품반입 정지 기간은 6개월의 범위이다(관세법 제178조제1항).","c":"상","v":1},"관세사2017_34-04-2":{"f":"세관장은 특허보세구역 운영인이 1년 이내에 3회 이상 물품반입등의 정지처분 (과징금 부과처분 포함)을 받은 경우 그 특허를 취소할 수 있다.","w":"1년 이내 3회 이상 정지처분을 받은 경우의 특허 취소는 재량이다. 반드시 취소해야 하는 경우는 거짓·부정한 방법으로 특허를 받은 경우, 제175조 결격사유에 해당하게 된 경우, 명의를 대여한 경우뿐이다(관세법 제178조제2항).","c":"상","v":1},"관세사2017_34-04-3":{"f":"세관장은 물품반입등의 정지처분이 그 이용자에게 심한 불편을 주거나 공익을 해칠 우려가 있는 경우에는 특허보세구역의 운영인에게 물품반입등의 정지처분을 갈음하여 해당 특허보세구역 운영에 따른 매출액의 100분의 3 이하의 과징금을 부과할 수 있다.","w":"과징금은 매출액의 100분의 3 이하이다. 상한이 3이지 하한이 아니다(관세법 제178조제3항).","c":"상","v":1},"관세사2017_34-04-4":{"f":"과징금 부과통지를 받은 특허보세구역 운영자는 납부통지일부터 20일 이내에 과징금을 관세청장이 지정하는 수납기관에 납부하여야 하며, 과징금은 이를 분할하여 납부할 수 없다.","w":"(2021 개정 전 기준 X. 현행은 분할납부 금지 규정이 없어 분할납부할 수 있다) 출제 당시 관세법 시행령 제285조의7제5항은 과징금을 분할납부할 수 없다고 정했으나 2021.9.24 삭제되었다. 지금은 행정기본법 제29조에 따라 한꺼번에 내기 어려운 사유가 있으면 납부기한을 연기하거나 분할납부하게 할 수 있고, 납부기한은 여전히 납부통지일부터 20일이다(관세법 시행령 제193조의3제4항, 제285조의7제2항).","c":"중","v":1,"old":1,"ow":"(2021 개정 전 기준 X. 현행은 분할납부 금지 규정이 없어 분할납부할 수 있다) 출제 당시 관세법 시행령 제285조의7제5항은 과징금을 분할납부할 수 없다고 정했으나 2021.9.24 삭제되었다. 지금은 행정기본법 제29조에 따라 한꺼번에 내기 어려운 사유가 있으면 납부기한을 연기하거나 분할납부하게 할 수 있고, 납부기한은 여전히 납부통지일부터 20일이다(관세법 시행령 제193조의3제4항, 제285조의7제2항)."},"관세사2017_34-05-1":{"f":"선용품을 외국무역선에 하역하거나 환적하려면 세관장의 허가를 받아야 한다.","w":"선박용품·항공기용품 등을 국제무역선에 하역하거나 환적할 때는 신고가 아니라 세관장의 허가를 받는다(관세법 제143조제1항). 허가 신청을 받은 세관장은 10일 이내에 통지해야 한다.","c":"상","v":1},"관세사2018_35-23-5":{"f":"승객예약자료를 열람할 수 있는 사람은 관세청장이 지정하는 세관공무원으로 한정한다.","w":"열람할 수 있는 사람은 관세청장이 지정하는 세관공무원으로 한정된다. 선장이나 항공사 직원은 열람할 수 없다(관세법 제137조의2제3항).","c":"상","v":1},"관세사2018_35-24-5":{"f":"관세통로는 육상국경으로부터 통관역에 이르는 철도와 육상국경으로부터 통관장에 이르는 육로 또는 수로 중에서 세관장이 지정한다.","w":"철도는 통관역으로, 육로·수로는 통관장으로 이어지고, 관세통로를 지정하는 사람은 세관장이다(관세법 제148조제2항). 통관역만 관세청장이 지정한다.","c":"상","v":1},"관세사2018_35-25-1":{"f":"세관장은 보세구역에 반입할 수 있는 물품의 종류를 제한할 수 있다.","w":"세관장은 보세구역에 반입할 수 있는 물품의 종류를 제한할 수 있다(관세법 제157조제3항).","c":"상","v":1},"관세사2018_35-26-1":{"f":"보세구역에 장치된 물품은 그 현상을 유지하기 위하여 필요한 보수작업과 그 성질을 변하지 아니하게 하는 범위에서 포장을 바꾸거나 구분ㆍ분할ㆍ합병을 하거나 그 밖의 비슷한 보수작업을 할 수 있다.","w":"보수작업은 현상을 유지하는 데 필요한 작업이거나 성질을 변하지 않게 하는 범위의 작업에 한한다. 성질을 변하게 하는 작업은 허용되지 않는다(관세법 제158조제1항).","c":"상","v":1},"관세사2018_35-26-3":{"f":"보수작업을 하려는 자는 세관장의 승인을 받아야 한다.","w":"보수작업은 세관장의 승인을 받아야 한다. 승인 신청을 받은 날부터 10일 이내에 승인 여부를 통지해야 한다(관세법 제158조제2항·제3항).","c":"상","v":1},"관세사2018_35-26-4":{"f":"보수작업으로 외국물품에 부가된 내국물품은 외국물품으로 본다.","w":"보수작업으로 외국물품에 붙인 내국물품은 외국물품으로 본다(관세법 제158조제5항).","c":"상","v":1},"관세사2018_35-26-5":{"f":"외국물품은 수입될 물품의 보수작업의 재료로 사용할 수 없다.","w":"외국물품은 수입될 물품의 보수작업 재료로 쓸 수 없다(관세법 제158조제6항).","c":"상","v":1},"관세사2023_40-17-1":{"f":"출입허가 수수료의 산정 금액이 1만원에 미달하는 경우에는 1만원으로 한다.","w":"국제항이 아닌 지역에 출입하는 허가수수료는 산정 금액이 1만원에 미달하면 1만원으로 하고 총액은 50만원을 넘지 못한다(관세법 시행규칙 제62조제1항).","c":"상","v":1},"관세사2023_40-29-5":{"f":"세관장은 화물관리인이 그 지정의 취소를 요청하여 지정을 취소하는 경우 청문을 하지 아니한다.","w":"화물관리인 본인이 지정 취소를 요청한 경우는 청문 대상이 아니다. 결격사유나 약정 위반 등으로 취소하는 경우에만 청문을 한다(관세법 시행령 제187조의2제2항).","c":"상","v":1},"관세사2024_41-18-1":{"f":"매각하는 장치기간경과물품의 질권자나 유치권자는 해당 물품을 매각한 날부터 1개월 이내에 그 권리를 증명하는 서류를 세관장에게 제출하여야 한다.","w":"권리를 증명하는 서류의 제출기한은 매각한 날부터 1개월이다(관세법 제211조제2항).","c":"상","v":1},"관세사2024_41-18-2":{"f":"경쟁입찰의 방법으로 매각하려는 경우 매각되지 아니하였을 때에는 5일 이상의 간격을 두어 다시 입찰에 부칠 수 있다.","w":"재입찰까지의 간격은 5일 이상이다. 예정가격은 최초 예정가격의 100분의 10 이내에서 입찰할 때마다 줄일 수 있다(관세법 제210조제2항).","c":"상","v":1},"관세사2024_41-18-3":{"f":"세관장은 매각대금을 그 매각비용, 관세, 각종 세금의 순으로 충당한다.","w":"매각대금의 충당 순서는 매각비용, 관세, 각종 세금이다. 비용이 먼저이고 남은 잔금은 화주에게 교부한다(관세법 제211조제1항).","c":"상","v":1},"관세사2024_41-18-4":{"f":"세관장은 장치기간경과물품을 매각할 때에는 매각 물건, 매각 수량, 매각 예정가격 등을 매각 시작 10일 전에 공고하여야 한다.","w":"매각 공고는 매각 시작 10일 전에 한다(관세법 제210조제7항).","c":"상","v":1},"관세사2024_41-20-2":{"f":"통관역은 국외와 연결되고 국경에 근접한 철도역 중에서 관세청장이 지정하고, 통관장은 관세통로에 접속한 장소 중에서 세관장이 지정한다.","w":"통관역은 관세청장이, 통관장은 세관장이 지정한다. 지정권자가 서로 바뀌어 있다(관세법 제148조제3항·제4항).","c":"상","v":1},"관세사2024_41-20-3":{"f":"세관장이 출항절차를 신속하게 진행하기 위하여 필요하다고 인정하여 출항허가 후 7일의 범위에서 따로 기간을 정하는 경우 국제무역선의 선장은 그 기간 내에 적재화물목록을 제출할 수 있다.","w":"출항허가 후 적재화물목록을 늦게 낼 수 있는 기간은 7일의 범위이고, 그 기간을 정하는 사람은 세관장이다(관세법 제136조제2항).","c":"상","v":1},"관세사2024_41-20-4":{"f":"국제무역선인 5천톤급 이상의 선박이 연간 50회 이상 입항하거나 입항할 것으로 예상되어야 국제항으로 지정될 수 있다.","w":"항구가 국제항이 되려면 5천톤급 이상 국제무역선이 연간 50회 이상 입항하거나 입항이 예상되어야 한다(관세법 시행령 제155조의2제1항제3호나목).","c":"상","v":1},"관세사2024_41-20-5":{"f":"국제무역선이 국제항의 바깥에서 물품을 하역하거나 환적하려는 경우 납부하여야 하는 항외하역에 관한 허가수수료는 하역 1일마다 4만원으로 한다.","w":"항외하역 허가수수료는 하역 1일마다 4만원이다. 수출물품은 1만원이다(관세법 시행규칙 제63조).","c":"상","v":1},"관세사2025_42-31-4":{"f":"국제항이 아닌 지역에 국제무역선이 출입시 납부하여야 하는 출입허가수수료 금액이 1만원에 미달하는 경우에는 1만원으로 한다.","w":"출입허가수수료는 1만원에 미달해도 징수하지 않는 것이 아니라 1만원으로 한다. 강제입항 등 일정 사유에는 수수료를 면제한다(관세법 시행규칙 제62조).","c":"상","v":1},"관세사2025_42-32-1":{"f":"보세창고의 설치ㆍ운영에 관한 수수료는 해당 보세창고의 연면적을 기준으로 분기당 정해진 금액으로 한다.","w":"특허수수료는 매출액이 아니라 특허보세구역의 연면적에 따라 분기당 금액이 정해진다. 매출액 기준 수수료율을 쓰는 곳은 보세판매장이다(관세법 시행규칙 제68조, 제68조의2).","c":"상","v":1},"관세사2025_42-32-2":{"f":"보세판매장 특허수수료는 연단위로 해당 연도분을 다음 연도 4월 30일까지 납부해야한다.","w":"보세판매장 특허수수료의 납부기한은 다음 연도 4월 30일이다. 1분기말이 아니다(관세법 시행규칙 제68조의2제4항).","c":"상","v":1},"관세사2025_42-32-4":{"f":"보세공장 특허수수료는 분기단위로 매분기말까지 다음 분기분을 납부하되, 운영인이 원하는 때에는 1년 단위로 일괄하여 미리 납부할 수 있다.","w":"특허수수료의 납부 단위는 반기가 아니라 분기이다. 분기말까지 다음 분기분을 내고, 보세공장은 일반 금액의 4분의 1이다(관세법 시행규칙 제68조제2항·제3항).","c":"상","v":1},"관세사2025_42-32-5":{"f":"목재만 장치하는 수면의 보세창고에 대하여 납부하여야 하는 특허수수료는 일반 보세 창고의 특허수수료 금액의 4분의 1로 한다.","w":"보세공장과 목재만 장치하는 수면의 보세창고는 특허수수료가 일반 금액의 4분의 1이다. 2분의 1이 아니다(관세법 시행규칙 제68조제2항).","c":"상","v":1},"관세사2025_42-33-1":{"f":"세관검사장은 통관하려는 물품을 검사하기 위한 장소로서 세관장이 지정하는 지정 보세구역이다.","w":"세관검사장은 세관장이 지정하는 지정보세구역이다. 지정보세구역은 세관장이 국가·지방자치단체·공항시설이나 항만시설 관리법인의 토지등 중에서 지정한다(관세법 제166조).","c":"상","v":1},"관세사2026_43-21-4":{"f":"특허보세구역의 승계신고를 받은 세관장은 이를 심사하여 신고일부터 5일 이내에 그 결과를 신고인에게 통보하여야 한다.","w":"통보기한은 신고일부터 5일 이내이다(관세법 시행령 제194조제2항).","c":"상","v":1},"관세사2018_35-21-3":{"f":"납세자가 폐업한 경우, 세관공무원은 관세조사를 종료하였을 때에도 그 조사 결과를 서면으로 통지하지 아니할 수 있다.","w":"관세조사 결과는 종료 후 20일 이내에 서면으로 통지하는 것이 원칙이고 유선 통지는 인정되지 않는다. 납세자가 폐업한 경우에는 통지 의무가 없다(관세법 제115조).","c":"상","v":1},"관세사2018_35-22-2":{"f":"심사청구서를 제출받은 세관장은 이를 받은 날부터 7일 내에 그 심사청구서에 의견서를 첨부하여 관세청장에게 보내야 한다.","w":"세관장이 심사청구서에 의견서를 붙여 관세청장에게 보내는 기한은 받은 날부터 7일이다(관세법 제122조제3항).","c":"상","v":1},"관세사2018_35-22-3":{"f":"관세청장은 세관장의 의견서를 받은 때에는 지체 없이 해당 의견서의 부본을 심사청구인에게 송부하여야 한다.","w":"관세청장은 세관장의 의견서를 받으면 지체 없이 부본(사본)을 심사청구인에게 보낸다. 10일이라는 기한도, 원본 송부도 규정에 없다(관세법 제122조제4항). 청구인은 반대 증거서류를 낼 수 있다.","c":"상","v":1},"관세사2018_35-22-4":{"f":"이의신청인, 심사청구인 또는 심판청구인은 신청 또는 청구의 대상이 대통령령으로 정하는 금액 미만인 경우에는 배우자, 4촌 이내의 혈족 또는 배우자의 4촌 이내의 혈족을 대리인으로 선임할 수 있다.","w":"청구 대상이 3천만원 미만인 소액사건에서는 배우자, 4촌 이내의 혈족 등을 대리인으로 선임할 수 있다(관세법 제126조제2항, 시행령 제149조의2).","c":"상","v":1},"관세사2018_35-22-5":{"f":"이의신청을 받은 세관장은 이의신청을 받은 날부터 7일 이내에 이의신청의 대상이 된 처분에 대한 의견서를 이의신청인에게 송부하여야 한다.","w":"세관장이 이의신청인에게 의견서를 보내는 기한은 이의신청을 받은 날부터 7일이다(관세법 제132조제5항).","c":"상","v":1},"관세사2019_36-19-2":{"f":"이의신청을 거친 후 심사청구를 하려는 경우에는 이의신청에 대한 결정을 통지받은 날부터 90일 이내에 하여야 한다.","w":"이의신청을 거친 경우 심사청구 기간은 처분을 안 날이 아니라 이의신청 결정을 통지받은 날부터 90일이다(관세법 제121조제2항).","c":"상","v":1},"관세사2019_36-19-3":{"f":"심사청구 또는 심판청구를 하면 해당 처분의 집행에 효력을 미치지 아니한다.","w":"이의신청·심사청구·심판청구는 원칙적으로 처분의 집행을 멈추지 않는다. 중대한 손해를 예방할 긴급한 필요가 있을 때 재결청이 집행정지를 결정할 수 있다(관세법 제125조).","c":"상","v":1},"관세사2019_36-19-4":{"f":"심사청구인 또는 심판청구인은 변호사 또는 관세사를 대리인으로 선임할 수 있다.","w":"대리인이 될 수 있는 사람은 변호사와 관세사이다. 세무사는 포함되지 않는다(관세법 제126조제1항).","c":"상","v":1},"관세사2019_36-19-5":{"f":"심사청구 또는 심판청구의 대상이 되는 것은 관세법령에 따른 처분으로서 위법 또는 부당한 처분에 한한다.","w":"불복 대상은 위법한 처분뿐 아니라 부당한 처분, 필요한 처분을 받지 못한 경우도 포함한다(관세법 제119조제1항).","c":"상","v":1},"관세사2019_36-31-1":{"f":"심판청구를 제기한 날과 같은 날에 심사청구를 제기한 경우에는 심사청구를 각하한다.","w":"심판청구를 제기한 뒤(같은 날 포함) 심사청구를 제기하면 기각이 아니라 각하한다. 기각은 청구가 이유 없을 때의 결정이다(관세법 제128조제1항제1호가목).","c":"상","v":1},"관세사2019_36-31-2":{"f":"심사청구가 이유 없다고 인정되는 경우에는 그 청구를 기각한다.","w":"이유 없는 청구는 기각이다. 각하는 청구기간이 지났거나 보정을 하지 않은 것처럼 청구 자체가 부적법한 경우의 결정이다(관세법 제128조제1항).","c":"상","v":1},"관세사2019_36-31-3":{"f":"심사청구의 재결청은 결정서를 받은 날부터 90일 이내에 행정소송을 제기할 수 있다는 뜻을 통지하여야 한다.","w":"결정서에 적는 불복기간은 결정서를 받은 날부터 90일이다(관세법 제129조제1항제2호).","c":"상","v":1},"관세사2019_36-31-5":{"f":"관세청장은 관세심사위원회의 심의를 거쳐 심사청구에 대한 결정을 하여야 하며, 관세심사위원회의 회의는 공개하지 아니함을 원칙으로 한다.","w":"관세심사위원회의 회의는 비공개가 원칙이고, 위원장이 필요하다고 인정할 때만 공개할 수 있다. 심사청구 결정은 위원회의 의결에 따른다(관세법 제127조).","c":"상","v":1},"관세사2022_39-18-2":{"f":"심사청구인의 주소 또는 거소가 불명하여 결정 등을 통지할 수 없어 그 요지를 당해 재결관서의 게시판에 공고를 한 때에는 그 공고가 있은 날부터 10일을 경과한 날에 결정 등의 통지를 받은 것으로 본다.","w":"결정 통지를 게시판에 공고한 경우 공고한 날부터 10일이 지난 날에 통지받은 것으로 본다(관세법 시행령 제151조제3항).","c":"상","v":1},"관세사2023_40-12-2":{"f":"심사청구인은 청구의 대상이 2천만원인 경우 배우자를 대리인으로 선임할 수 있다.","w":"가족을 대리인으로 선임할 수 있는 소액사건은 청구 대상이 3천만원 미만인 경우이다. 3천만원이면 미만이 아니어서 배우자를 선임할 수 없다(관세법 시행령 제149조의2).","c":"상","v":1},"관세사2024_41-12-1":{"f":"은행이 급부ㆍ지원 등의 대상자 선정 및 그 자격을 조사ㆍ심사하는데 필요한 과세정보를 요구하는 때에는 은행이 당사자의 동의를 받은 경우에 세관공무원은 과세정보를 제공할 수 있다.","w":"은행이 급부·지원 대상자 심사용 과세정보를 요구할 때는 당사자의 동의가 있어야 제공할 수 있다(관세법 제116조제1항제5호).","c":"상","v":1},"관세사2024_41-16-2":{"f":"관세청장은 심사청구의 내용이나 절차가 보정할 수 있다고 인정되는 경우에는 20일 이내의 기간을 정하여 해당 사항을 보정할 것을 요구할 수 있다.","w":"보정을 요구하는 기간은 20일 이내이다. 보정기간은 심사청구기간과 결정기간에 산입하지 않는다(관세법 제123조).","c":"상","v":1},"관세사2024_41-16-3":{"f":"심사청구인은 청구의 대상이 3천만원 미만인 경우에는 배우자를 대리인으로 선임할 수 있다.","w":"청구 대상이 3천만원 미만이면 배우자, 4촌 이내의 혈족 등을 대리인으로 선임할 수 있다(관세법 제126조제2항, 시행령 제149조의2).","c":"상","v":1},"관세사2024_41-16-4":{"f":"관세청장은 관세심사위원회의 의결에 따라 심사청구에 대한 결정을 하여야 한다.","w":"결정을 하는 사람은 관세심사위원회 위원장이 아니라 관세청장이며, 위원회의 의결에 따라 결정한다(관세법 제127조제1항).","c":"상","v":1},"관세사2024_41-16-5":{"f":"심사청구는 해당 처분을 한 것을 안 날부터 90일 이내에 제기하여야 한다.","w":"심사청구기간은 처분이 내려진 날이 아니라 처분을 한 것을 안 날(통지받은 날)부터 90일이다(관세법 제121조제1항).","c":"상","v":1},"관세사2026_43-18-1":{"f":"심판청구인은 관세사를 대리인으로 선임할 수 있고, 변호사도 대리인으로 선임할 수 있다.","w":"대리인이 될 수 있는 사람은 변호사와 관세사이다(관세법 제126조제1항).","c":"상","v":1},"관세사2026_43-18-2":{"f":"이의신청인은 신청의 대상이 3천만원 미만인 경우에는 배우자의 4촌 이내의 혈족을 대리인으로 선임할 수 있다.","w":"소액사건의 기준은 3천만원 미만이다. 5천만원 미만이 아니다(관세법 시행령 제149조의2).","c":"상","v":1},"관세사2026_43-18-3":{"f":"대리인의 권한은 서면으로 증명하여야 한다.","w":"대리인의 권한은 서면으로 증명해야 하고 구두로는 안 된다(관세법 제126조제3항).","c":"상","v":1},"관세사2026_43-18-4":{"f":"대리인은 본인을 위하여 청구에 관한 모든 행위를 할 수 있다. 다만, 청구의 취하는 특별한 위임을 받은 경우에만 할 수 있다.","w":"청구의 취하는 특별한 위임이 있어야 대리인이 할 수 있다(관세법 제126조제4항).","c":"상","v":1},"관세사2026_43-19-3":{"f":"세관공무원은 특정한 분야만을 조사할 필요가 있는 등 대통령령으로 정하는 경우를 제외하고는 신고납부세액과 관세법 및 다른 법령에서 정하는 수출입 관련 의무 이행과 관련하여 그 권한에 속하는 사항을 통합하여 조사하는 것을 원칙으로 한다.","w":"조세채권 확보를 위해 긴급히 조사할 필요가 있는 경우는 통합조사를 하는 경우가 아니라 통합조사 원칙의 예외 사유이다(관세법 제110조의2, 시행령 제135조의2).","c":"상","v":1},"관세사2017_34-06-1":{"f":"세관장은 해당 물품의 수입신고가 수리된 이후에 원산지증명서를 발급한 국가의 세관이나 그 밖에 발급권한이 있는 기관에 원산지증명서 및 원산지 증명서확인자료의 진위 여부, 정확성 등의 확인을 요청할 수 있다.","w":"발급기관에 대한 확인 요청은 수입신고 수리 이전이 아니라 수리된 이후에 한다. 세관장은 요청한 사실, 회신 내용, 결정 내용을 수입자에게 통보해야 한다(관세법 제233조제1항).","c":"상","v":1},"관세사2017_34-07-5":{"f":"판매를 위한 물품의 포장개선 또는 상표표시 등 상품성 향상을 위한 개수작업이나 재포장 또는 단순한 조립작업이 수행된 국가는 원산지로 인정하지 아니한다.","w":"상품성 향상을 위한 개수작업, 재포장, 단순 조립은 실질적 변형으로 보지 않아 그 작업이 수행된 국가를 원산지로 인정하지 않는다(관세법 시행규칙 제74조제4항).","c":"상","v":1},"관세사2017_34-08-4":{"f":"품목분류표상 포장용품과 내용품을 각각 별개의 품목번호로 하고 있는 경우에는 그 내용물품의 원산지를 포장용품의 원산지로 인정하지 아니한다.","w":"포장용품은 원칙적으로 내용물품의 원산지를 따른다. 품목분류표상 별개의 품목번호이면 이 예외가 적용되지 않아 포장용품은 자기 원산지를 따로 정한다(관세법 시행규칙 제75조제1항제3호).","c":"상","v":1},"관세사2017_34-09-3":{"f":"과세가격이 15만원 이하인 물품은 원산지증명서를 제출하지 않아도 된다.","w":"원산지증명서 제출 면제 기준은 과세가격 15만원 이하이다(관세법 시행령 제236조제2항제3호).","c":"상","v":1},"관세사2017_34-11-4":{"f":"세관장은 수입신고 전 즉시반출을 한 자가 정해진 기간 이내에 수입신고를 하지 아니하는 경우에는 해당 물품에 대한 관세의 100분의 20에 상당하는 금액을 가산세로 징수한다.","w":"즉시반출 후 10일 이내에 수입신고를 하지 않으면 관세를 부과·징수하면서 해당 관세의 100분의 20을 가산세로 징수하고, 즉시반출 지정을 취소할 수 있다(관세법 제253조제4항).","c":"상","v":1},"관세사2018_35-28-3":{"f":"관세청장은 관세법 제240조의6 제3항에 따라 다른 국가와 수출입신고자료 등을 교환하는 경우에는 이를 신고인 또는 그 대리인에게 통지하여야 한다.","w":"다른 국가와 수출입신고자료를 교환할 때에는 대통령령으로 정하는 바에 따라 신고인 또는 그 대리인에게 통지해야 한다(관세법 제240조의6제5항).","c":"상","v":1},"관세사2018_35-29-4":{"f":"수출입물품안전관리기관협의회는 위원장 1명을 포함하여 25명 이내의 위원으로 구성한다.","w":"수출입물품안전관리기관협의회는 위원장 1명을 포함해 25명 이내로 구성한다(관세법 시행령 제251조의3제2항).","c":"상","v":1},"관세사2018_35-31-1":{"f":"검사대상으로 결정되지 아니한 물품은 입항 전에 그 수입신고를 수리할 수 있다.","w":"입항전수입신고를 한 물품 중 검사대상으로 결정되지 않은 물품은 입항 전에 수리할 수 있다. 검사대상 물품은 관할 보세구역에 반입해야 한다(관세법 제244조제3항·제4항).","c":"상","v":1},"관세사2019_36-33-4":{"f":"세관장은 원산지증명서가 발급된 물품을 수입하는 국가의 권한 있는 기관으로부터 원산지증명서 및 원산지증명서확인자료의 진위 여부, 정확성 등의 확인을 요청받은 경우에는 수출물품의 생산자 또는 수출자를 대상으로 서면조사 또는 현지조사를 할 수 있다.","w":"확인 요청을 받으면 세관장은 서면조사 또는 현지조사를 할 수 있다. 의무가 아니라 재량이고, 조사 대상은 원산지증명서를 발급받은 자·발급한 자·수출물품의 생산자 또는 수출자이다(관세법 제233조제3항).","c":"상","v":1},"관세사2019_36-34-2":{"f":"관세청장은 관세의 부과와 징수, 과세 불복에 대한 심리, 형사소추 및 수출입신고의 검증을 위하여 수출입신고자료 등 대통령령으로 정하는 사항을 대한민국 정부가 다른 국가와 관세행정에 관한 협력 및 상호지원에 관하여 체결한 협정과 국제기구와 체결한 국제협약에 따라 다른 법률에 저촉되지 아니하는 범위에서 다른 국가와 교환할 수 있으며, 상호주의 원칙에 따라 상대국에 수출입신고자료 등을 제공하는 것을 제한할 수 있다.","w":"자료 교환은 의무가 아니라 할 수 있는 사항이며, 상호주의 원칙에 따라 상대국에 자료 제공을 제한할 수 있다(관세법 제240조의6제3항·제4항).","c":"상","v":1},"관세사2019_36-36-1":{"f":"수입신고를 한 물품을 세관장의 수리 전에 해당 물품이 장치된 장소로부터 반출하려는 자는 납부하여야 할 관세에 상당하는 담보를 제공하고 세관장의 승인을 받아야 한다.","w":"수입신고 수리 전 반출은 담보를 제공하고 세관장의 승인을 받아야 한다. 관세청장에게 신고하는 절차가 아니다(관세법 제252조).","c":"상","v":1},"관세사2019_36-36-2":{"f":"수입하려는 물품을 수입신고 전에 운송수단, 관세통로, 하역통로 또는 관세법에 따른 장치 장소로부터 즉시 반출하려는 자는 대통령령으로 정하는 바에 따라 세관장에게 즉시반출신고를 하여야 한다.","w":"수입신고 전에 즉시 반출하려면 세관장의 승인이 아니라 즉시반출신고를 한다. 반출 후 10일 이내에 수입신고를 해야 한다(관세법 제253조).","c":"상","v":1},"관세사2019_36-36-4":{"f":"관세청장은 전자문서로 거래되는 수출입물품에 대하여 대통령령으로 정하는 바에 따라 수출입신고ㆍ물품검사 등 통관에 필요한 사항을 따로 정할 수 있다.","w":"출제 당시 관세법 제254조제1항은 관세청장이 대통령령으로 정하는 바에 따라 전자상거래 수출입물품의 통관에 필요한 사항을 따로 정할 수 있게 했다. 지금은 대통령령으로 정하는 전자상거래물품에 대해 수출입신고·물품검사 등을 생략하거나 간소한 방법으로 적용할 수 있다고 정한다.","c":"중","v":1},"관세사2019_36-36-5":{"f":"세관장은 관세청장이 정하는 절차에 따라 별도로 정한 지정장치장에서 탁송품을 통관하여야 한다.","w":"탁송품은 세관장이 관세청장이 정하는 절차에 따라 별도로 정한 지정장치장에서 통관한다. 탁송품 운송업자의 보세창고·시설에서 통관하는 것은 감시·단속에 지장이 없을 때의 예외다(관세법 제254조의2제6항).","c":"상","v":1},"관세사2020_37-34-3":{"f":"위원회의 위원장은 관세청에서 원산지업무를 관장하는 고위공무원단에 속하는 공무원이 된다.","w":"(2022 개정 전 기준 X. 현행은 원산지확인위원회 규정이 삭제됨) 당시 관세법 시행령 제236조의4 제3항은 관세청에서 원산지업무를 관장하는 고위공무원단 소속 공무원을 위원장으로 정했다. 이 위원회 규정은 2022.2.15 시행령 개정으로 삭제되었다.","c":"중","v":1,"old":1,"ow":"(2022 개정 전 기준 X. 현행은 원산지확인위원회 규정이 삭제됨) 당시 관세법 시행령 제236조의4 제3항은 관세청에서 원산지업무를 관장하는 고위공무원단 소속 공무원을 위원장으로 정했다. 이 위원회 규정은 2022.2.15 시행령 개정으로 삭제되었다."},"관세사2022_39-02-1":{"f":"보세화물반출입에 관한 자료는 해당 신고에 대한 수리일부터 2년이다.","w":"보세화물반출입 자료의 보관기간은 수리일부터 2년이다. 수출물품·반송물품 가격결정 자료는 3년이다(관세법 시행령 제3조).","c":"상","v":1},"관세사2022_39-28-5":{"f":"우편물에 대한 관세의 납세의무는 해당 우편물이 반송되면 소멸한다.","w":"우편물이 반송되면 그 관세의 납세의무는 소멸한다(관세법 제261조).","c":"상","v":1},"관세사2023_40-23-1":{"f":"관세청장 또는 세관장은 관세법에 따른 세관공무원의 적법한 물품검사로 인하여 물품에 손실이 발생한 경우 그 손실을 입은 자에게 보상하여야 한다.","w":"손실보상의 주체는 관세청장 또는 세관장이다. 재정경제부장관이 아니다(관세법 제246조의2제1항).","c":"상","v":1},"관세사2023_40-25-1":{"f":"세관장은 신고를 각하한 때에는 즉시 그 신고인에게 각하사유 등을 기재한 통지서를 송부하여야 한다.","w":"신고를 각하하면 날짜를 따지지 않고 즉시 각하사유 등을 적은 통지서를 신고인에게 보낸다(관세법 시행령 제254조).","c":"상","v":1},"관세사2023_40-27-1":{"f":"수출입안전관리우수업체가 합병을 한 경우에는 합병일로부터 30일 이내에 관세청장에게 보고하여야 한다.","w":"양도·양수·분할·합병 등 변동사항은 발생한 날부터 30일 이내에 관세청장에게 보고한다(관세법 제255조의4제3항).","c":"상","v":1},"관세사2023_40-27-3":{"f":"관세청장은 수출입안전관리우수업체의 안전관리 기준 충족 여부를 주기적으로 확인하여야 한다.","w":"안전관리 기준 충족 여부를 주기적으로 확인하는 사람은 관세청장이다(관세법 제255조의4제1항).","c":"상","v":1},"관세사2023_40-27-4":{"f":"수출입안전관리우수업체는 안전관리기준의 충족 여부를 자율적으로 평가하여 그 결과를 관세청장에게 보고하여야 한다.","w":"기준 충족 여부를 평가하는 쪽은 업체 자신이다. 업체가 매년 자율평가하여 공인된 날이 속하는 달의 다음 달 15일까지 관세청장에게 보고한다(관세법 제255조의4제2항, 시행령 제259조의5제2항).","c":"상","v":1},"관세사2023_40-27-5":{"f":"수출입안전관리우수업체는 안전관리기준의 충족 여부를 평가하는 관리책임자를 지정해야 한다.","w":"관리책임자를 지정하는 주체는 수출입안전관리우수업체 자신이다(관세법 시행령 제259조의5제1항).","c":"상","v":1},"관세사2024_41-23-4":{"f":"위원장이 부득이한 사유로 직무를 수행하지 못하는 경우에는 위원장이 미리 지명한 사람이 직무를 대행한다.","w":"위원장이 부득이한 사유로 직무를 수행하지 못하면 관세청장이 아니라 위원장이 미리 지명한 사람이 직무를 대행한다(관세법 시행령 제236조의9제4항).","c":"상","v":1},"관세사2025_42-29-2":{"f":"통관우체국의 장은 수입하려는 우편물의 발송국으로부터 해당 우편물이 발송되기 전에 사전전자정보를 제공받은 경우에는 그 제공받은 정보를 해당 우편물이 발송국에서 출항하는 운송수단에 적재되기 전까지 세관장에게 제출하여야 한다.","w":"사전전자정보는 우편물이 발송국에서 출항하는 운송수단에 적재되기 전까지 제출해야 한다. 입항한 뒤에 내면 사전정보의 의미가 없다(관세법 제256조의2제1항).","c":"상","v":1},"관세사2026_43-26-1":{"f":"입항전수입신고가 된 물품은 우리나라에 도착한 것으로 본다.","w":"입항전수입신고를 한 물품은 우리나라에 도착한 것으로 본다(관세법 제244조제1항).","c":"상","v":1},"관세사2026_43-26-2":{"f":"입항전수입신고는 당해 물품을 적재한 항공기가 그 물품을 적재한 공항에서 출항하여 우리나라에 입항하기 1일전부터 할 수 있다.","w":"입항전수입신고 가능 시점은 선박은 입항 5일 전, 항공기는 입항 1일 전이다(관세법 시행령 제249조).","c":"상","v":1},"관세사2026_43-26-3":{"f":"물품의 검사 대상으로 결정되지 아니한 물품은 입항 전에 그 수입신고를 수리할 수 있다.","w":"입항전수입신고 물품 중 검사 대상이 아닌 것은 입항 전에 수리할 수 있다(관세법 제244조제4항).","c":"상","v":1},"관세사2026_43-26-5":{"f":"과세가격이 15만원 이하인 물품의 경우, 신고를 할 때 원산지증명서를 제출하지 아니할 수 있다.","w":"과세가격 15만원 이하 물품은 원산지증명서 제출이 면제된다(관세법 시행령 제236조제2항제3호).","c":"상","v":1},"관세사2026_43-28-3":{"f":"세관장이 우편물 통관에 대한 결정을 한 경우 세관장은 그 결정사항을 통관우체국의 장에게 통지하여야 한다.","w":"세관장은 우편물 통관에 대한 결정사항을 통관우체국의 장에게 통지하고, 통지를 받은 통관우체국의 장이 수취인이나 발송인에게 알린다(관세법 제259조).","c":"상","v":1},"관세사2017_34-12-1":{"f":"“국제무역선”이란 무역을 위하여 우리나라와 외국 간을 운항하는 선박을 말한다.","w":"관세법의 용어는 외국무역선이 아니라 국제무역선이며, 우리나라와 외국 간을 운항하는 선박이다. 외국에서만 운항하는 선박은 해당하지 않는다(관세법 제2조제6호).","c":"상","v":1},"관세사2017_34-12-2":{"f":"“반송”이란 국내에 도착한 외국물품이 수입통관절차를 거치지 아니하고 다시 외국으로 반출되는 것을 말한다.","w":"반송은 수입통관절차를 거치지 않고 다시 외국으로 내보내는 것이다. 수입통관을 마친 물품이 나가는 것은 수출이다(관세법 제2조제3호).","c":"상","v":1},"관세사2017_34-12-3":{"f":"세관공무원은 재량으로 직무를 수행할 때에는 과세의 형평과 이 법의 목적에 비추어 일반적으로 타당하다고 인정되는 한계를 엄수하여야 한다.","w":"세관공무원의 재량이 금지되는 것이 아니고, 재량으로 직무를 수행할 때 일반적으로 타당한 한계를 지켜야 한다(관세법 제7조).","c":"상","v":1},"관세사2017_34-12-5":{"f":"신의성실의무는 납세자와 세관공무원 모두에게 적용된다.","w":"납세자가 의무를 이행할 때에도, 세관공무원이 직무를 수행할 때에도 신의에 따라 성실해야 한다(관세법 제6조).","c":"상","v":1},"관세사2018_35-01-3":{"f":"“환적”(換積)이란 동일한 세관의 관할구역에서 입국 또는 입항하는 운송 수단에서 출국 또는 출항하는 운송수단으로 물품을 옮겨 싣는 것을 말한다.","w":"동일한 세관 관할구역 안에서 옮겨 싣는 것이 환적이다. 복합환적은 입항하는 운송수단의 물품을 다른 세관 관할구역으로 운송해 출항하는 운송수단에 옮겨 싣는 것이다(관세법 제2조제14호·제15호).","c":"상","v":1},"관세사2018_35-06-1":{"f":"관세는 수입신고를 하는 때의 물품의 성질과 그 수량에 따라 부과한다.","w":"관세는 수출이 아닌 수입물품에 부과하며, 과세물건은 수입신고를 하는 때의 물품의 성질과 수량을 기준으로 한다(관세법 제16조).","c":"상","v":1},"관세사2018_35-07-4":{"f":"수입물품을 수입신고 전에 양도한 경우에는 그 양수인이 납세의무자가 된다.","w":"수입신고 전에 양도하면 양수인이 납세의무자가 된다(관세법 제19조제1항제1호다목).","c":"상","v":1},"관세사2022_39-01-4":{"f":"반송이란 국내에 도착한 외국물품이 수입통관절차를 거치지 않고 다시 외국으로 반출되는 것을 말한다.","w":"수입통관절차를 거치지 않는다는 점이 수출과 구별되는 반송의 요건이다(관세법 제2조제3호).","c":"상","v":1},"관세사2022_39-03-3":{"f":"수입을 위탁받아 수입업체가 대행수입한 물품이 아닌 경우 대통령령으로 정하는 상업서류에 적힌 물품수신인은 납세의무자가 된다.","w":"대행수입한 물품이면 화주가 불분명할 때 수입을 위탁한 자가 납세의무자다. 상업서류(송품장, 선하증권·항공화물운송장)의 물품수신인은 대행수입이 아닌 경우의 납세의무자다(관세법 제19조제1항제1호, 시행령 제5조).","c":"상","v":1},"관세사2023_40-02-1":{"f":"납세의무자는 신고납부한 세액이 부족하다는 것을 알게 된 때에는 신고납부한 날부터 6개월 이내 해당 세액을 보정(補正)하여 줄 것을 세관장에게 신청할 수 있다.","w":"보정기간은 신고납부한 날부터 6개월이다(관세법 제38조의2제1항).","c":"상","v":1},"관세사2023_40-07-1":{"f":"천재지변을 이유로 납부기한을 연장받고자 하는 자가 세관장에게 제출하는 신청서의 기재사항에 연장 받고자하는 기간이 포함된다.","w":"신청서에는 납세의무자 인적사항, 연장받으려는 세액과 신고내용, 연장 사유와 기간을 적는다. 기간도 기재사항이다(관세법 시행령 제2조제3항).","c":"상","v":1},"관세사2024_41-02-1":{"f":"국내에 도착하여 수입통관절차를 거치지 않은 외국물품이 다시 외국으로 반출되는 것은 “반송”에 해당한다.","w":"수입통관절차를 거친 물품이 나가는 것은 수출이다. 반송은 수입통관절차를 거치지 않은 외국물품을 다시 반출하는 것이다(관세법 제2조제2호·제3호).","c":"상","v":1},"관세사2024_41-02-2":{"f":"지정장치장의 화물관리인 지정을 받은 자는 “운영인”에 해당하지 않는다.","w":"운영인은 특허보세구역의 설치·운영 특허를 받은 자와 종합보세사업장 설치·운영 신고를 한 자이다. 지정장치장의 화물관리인은 포함되지 않는다(관세법 제2조제16호).","c":"상","v":1},"관세사2024_41-02-3":{"f":"관세의 과세표준과 세액을 결정하기 위하여 서면으로 납세자의 장부ㆍ서류를 조사하는 것은 “관세조사”에 해당하고, 통합조사의 원칙에 따라 통합하여 조사하는 경우도 “관세조사”에 해당한다.","w":"관세조사 정의에 통합하여 조사하는 것도 포함된다. 방문 또는 서면으로 납세자의 장부·서류 등을 조사하는 것이 관세조사다(관세법 제2조제20호).","c":"상","v":1},"관세사2024_41-02-5":{"f":"상업서류, 견본품, 자가사용물품, 그 밖에 이와 유사한 물품으로서 국제무역선ㆍ국제무역기 또는 국경출입차량을 이용한 물품의 송달을 업으로 하는 자에게 위탁하여 우리나라에 반입하는 물품은 “탁송품”에 해당한다.","w":"탁송품은 국제무역선·국제무역기·국경출입차량을 이용한 물품의 송달업자에게 위탁하는 물품이다. 물품을 휴대하여 반출입하는 것을 업으로 하는 자에게 위탁하는 물품은 제외된다(관세법 제2조제18호).","c":"상","v":1},"관세사2026_43-01-4":{"f":"“탁송품”이란 상업서류, 견본품, 자가사용물품, 그 밖에 이와 유사한 물품으로서 국제무역선ㆍ국제무역기 또는 국경출입차량을 이용한 물품의 송달을 업으로 하는 자(물품을 휴대하여 반출입하는 것을 업으로 하는 자는 제외한다)에게 위탁하여 우리나라에 반입하거나 외국으로 반출하는 물품을 말한다.","w":"탁송품에서 물품을 휴대하여 반출입하는 것을 업으로 하는 자에게 위탁한 물품은 제외된다. 반출만이 아니라 우리나라에 반입하는 물품도 포함한다(관세법 제2조제18호).","c":"상","v":1},"관세사2026_43-06-3":{"f":"수입을 위탁받아 수입업체가 대행수입한 물품인 경우 그 물품을 수입신고하는 때의 화주가 불분명하면 그 물품의 수입을 위탁한 자가 납세의무자가 된다.","w":"대행수입에서 화주가 불분명할 때 납세의무자는 수입을 맡은 수입업체가 아니라 수입을 위탁한 자다(관세법 제19조제1항제1호가목).","c":"상","v":1},"관세사2017_34-16-1":{"f":"동종ㆍ동질물품의 거래가격을 기초로 과세가격을 결정하는 것은 물론 유사 물품의 거래가격을 기초로 과세가격을 결정하는 것도 허용된다.","w":"거래가격 방법으로 결정할 수 없으면 동종·동질물품 거래가격, 유사물품 거래가격, 국내판매가격, 산정가격, 합리적 기준 순으로 결정한다. 유사물품 방법도 허용된다(관세법 제31조~제35조).","c":"상","v":1},"관세사2017_34-16-2":{"f":"세관장은 납세의무자가 서면으로 요청하면 과세가격을 결정하는 데에 사용한 방법과 과세가격 및 그 산출근거를 그 납세의무자에게 서면으로 통보하여야 한다.","w":"과세가격 결정 방법과 산출근거는 납세의무자가 서면으로 요청한 경우에 서면으로 통보한다. 요청이 없어도 통보하는 것은 아니다(관세법 제36조).","c":"상","v":1},"관세사2017_34-16-3":{"f":"거래관행상 거래가 성립된 때부터 일정기간이 지난 후에 가격이 정하여지는 물품으로서 수입신고일 현재 그 가격이 정하여지지 아니한 경우에는 잠정가격으로 가격신고를 할 수 있다.","w":"이 경우는 가격신고를 생략하는 것이 아니라 잠정가격으로 신고하고, 세관장이 지정한 기간(2년 범위) 안에 확정가격을 신고한다(관세법 제28조, 시행령 제16조).","c":"상","v":1},"관세사2017_34-16-5":{"f":"수입물품의 과세가격은 우리나라에 수출하기 위하여 판매되는 물품에 대하여 구매자가 실제로 지급하였거나 지급하여야 할 가격에 일정한 금액을 더하여 조정한 거래가격으로 한다.","w":"거래가격은 실제 지급가격에 수수료·중개료, 용기·포장비, 무상공급 물품·용역, 로열티, 전매수익, 수입항까지의 운임·보험료 등을 더해 조정한다. 빼는 것이 아니다(관세법 제30조제1항).","c":"상","v":1},"관세사2020_37-04-3":{"f":"세관장은 장기간 반복하여 수입되는 물품에 대한 과세가격 결정에 있어 정하는 가산율 또는 공제율을 납세의무자의 요청이 있는 경우에 한하여 적용할 수 있다.","w":"가산율·공제율의 적용은 납세의무자의 요청이 있을 때에만 가능하다(관세법 시행령 제30조제2항).","c":"상","v":1},"관세사2023_40-09-1":{"f":"구매자가 부담하는 중개료는 과세가격에 포함된다.","w":"구매자가 부담하는 수수료와 중개료는 과세가격에 더한다. 다만 구매수수료는 제외한다(관세법 제30조제1항제1호).","c":"상","v":1},"관세사2023_40-09-2":{"f":"세관장은 과세가격을 결정하는 데에 사용한 방법과 과세가격 및 그 산출근거를 납세의무자가 서면으로 요청하면 서면으로 통보하여야 한다.","w":"통보는 납세의무자의 서면 요청이 있을 때 서면으로 하며 구두 통보는 인정되지 않는다(관세법 제36조).","c":"상","v":1},"관세사2023_40-09-3":{"f":"과세가격의 신고는 세관장에게 한다.","w":"가격신고는 수입신고를 할 때 세관장에게 한다(관세법 제27조제1항).","c":"상","v":1},"관세사2023_40-09-5":{"f":"납세의무자가 동일한 공급자로부터 계속하여 수입하고 있음에도 불구하고 신고한 가격에 현저한 변동이 있는 경우는 과세가격으로 인정하기 곤란한 경우에 해당한다.","w":"동일 공급자로부터 계속 수입하는데 신고가격에 현저한 변동이 있으면 과세가격으로 인정하기 곤란한 경우다. 이때 세관장은 신고가격이 사실과 같음을 증명하는 자료를 요구할 수 있다(관세법 제30조제4항, 시행령 제24조제1항제2호).","c":"상","v":1},"관세사2018_35-27-4":{"f":"세관장은 보세운송의 신고를 하거나 승인을 받으려는 물품에 대하여 관세의 담보를 제공하게 할 수 있다.","w":"세관장은 보세운송 신고·승인 대상 물품에 관세 담보를 제공하게 할 수 있다(관세법 제218조).","c":"상","v":1},"관세사2019_36-29-1":{"f":"세관장은 종합보세사업장의 운영인이 다른 사람에게 자신의 성명ㆍ상호를 사용하여 종합보세사업장을 운영하게 한 경우 그 종합보세사업장의 폐쇄를 명하여야 한다.","w":"명의를 빌려준 경우는 6개월 이내 기능 중지가 아니라 사업장 폐쇄 명령 사유다. 설비 유지의무 위반, 물량 감소, 1년간 반입·반출 실적 없음일 때 6개월 범위의 기능 중지를 한다(관세법 제204조).","c":"상","v":1},"관세사2019_36-29-2":{"f":"세관장의 허가를 받고 내국물품만을 원료로 하여 제조ㆍ가공 등을 하는 경우 세관장은 그 원료의 종합보세구역에의 반입ㆍ반출 등에 관한 신고를 생략하게 할 수 없다.","w":"허가받아 내국물품만을 원료로 쓰는 제조·가공의 원료는 반출입 신고 생략 대상에서 제외되므로 신고해야 한다(관세법 시행규칙 제70조제1호).","c":"상","v":1},"관세사2019_36-29-4":{"f":"판매인은 종합보세구역에서 관세가 포함된 가격으로 물품을 판매한 후 외국인관광객이 구매한 날부터 3개월 이내에 물품을 국외로 반출한 사실이 확인된 경우 관세를 환급받을 수 있다.","w":"환급 요건은 구매한 날부터 3개월 이내에 국외 반출이 확인되는 것이다(관세법 시행령 제216조의5제1항제1호).","c":"상","v":1},"관세사2019_36-29-5":{"f":"종합보세구역에 대해서는 관세법 제176조의2에 따른 특허보세구역의 특례가 준용되지 아니한다.","w":"종합보세구역에는 제175조, 제177조제2항, 제178조제1항·제3항 등만 준용된다. 보세판매장 특허의 특례를 정한 제176조의2는 준용 대상이 아니다(관세법 제205조).","c":"상","v":1},"관세사2022_39-21-1":{"f":"보세공장에서는 세관장의 허가를 받지 아니하고는 내국물품만을 원료로 하거나 재료로 하여 제조ㆍ가공하거나 그 밖에 이와 비슷한 작업을 할 수 없다.","w":"내국물품만을 원료로 하는 작업은 승인이 아니라 세관장의 허가를 받아야 한다. 허가 신청을 받은 세관장은 10일 이내에 통지해야 한다(관세법 제185조제2항·제3항).","c":"상","v":1},"관세사2022_39-21-2":{"f":"세관장은 보세공장 외 작업 허가의 신청을 받은 날부터 10일 이내에 허가 여부를 신청인에게 통지하여야 한다.","w":"허가 여부 통지기한은 신청을 받은 날부터 10일이다. 기한 내 통지하지 않으면 다음 날 허가한 것으로 본다(관세법 제187조제2항·제3항).","c":"상","v":1},"관세사2022_39-21-3":{"f":"보세건설장 운영인은 보세건설장에 반입한 외국물품에 대하여 사용 전에 수입신고를 하고 세관공무원의 검사를 받아야 한다.","w":"보세건설장에 외국물품을 반입하면 건설공사가 끝난 때가 아니라 사용 전에 수입신고를 하고 검사를 받는다. 세관공무원이 검사가 필요 없다고 인정하면 검사는 생략한다(관세법 제192조).","c":"상","v":1},"관세사2022_39-21-5":{"f":"보세공장 외 작업허가를 받은 자는 허가받은 기간이 끝나는 날부터 5일 이내에 세관 장에게 보세공장 외 작업완료 결과를 통보해야 한다.","w":"(2025 개정 전 기준 X. 현행은 허가받은 기간이 끝나는 날부터 10일 이내에 통보하므로 맞는 문장이다) 출제 당시 관세법 시행령 제203조제5항은 작업완료 결과 통보기한을 5일 이내로 정했고, 2025.11.28 개정으로 10일이 되었다.","c":"중","v":1,"old":1,"ow":"지금 관세법 시행령 제203조제5항은 보세공장 외 작업 완료 통보 기간을 10일로 정하고 있어, 현행 기준으로는 맞는 문장이다."},"관세사2022_39-22-5":{"f":"관세청장은 종합보세구역에 반입ㆍ반출되는 물량이 감소하여 종합보세구역을 존속시킬 필요가 없다고 인정될 때에는 종합보세구역의 지정을 취소할 수 있다.","w":"종합보세구역 지정과 취소의 주체는 세관장이 아니라 관세청장이다(관세법 제197조, 제204조제1항).","c":"상","v":1},"관세사2026_43-24-1":{"f":"화주 명의로도 보세운송의 신고를 할 수 있다.","w":"보세운송 신고인은 화주, 관세사등, 보세운송업자이다(관세법 제214조).","c":"상","v":1},"관세사2026_43-24-2":{"f":"수출신고가 수리된 물품은 관세청장이 따로 정하는 것을 제외하고는 보세운송절차를 생략한다.","w":"수출신고 수리 물품의 보세운송절차 생략에서 예외를 정하는 사람은 세관장이 아니라 관세청장이다(관세법 제213조제4항).","c":"상","v":1},"관세사2026_43-24-3":{"f":"세관장은 보세운송의 승인을 받으려는 물품에 대하여 관세의 담보를 제공하게 할 수 있다.","w":"담보를 제공하게 하는 사람은 관세청장이 아니라 세관장이다(관세법 제218조).","c":"상","v":1},"관세사2026_43-24-5":{"f":"보세운송업자 등록의 유효기간을 갱신하려는 자는 등록갱신신청서를 기간만료 1개월 전까지 관할지세관장에게 제출하여야 한다.","w":"등록갱신신청서의 제출 시한은 기간만료 1개월 전까지이다(관세법 시행령 제231조제4항).","c":"중","v":1},"관세사2017_34-18-1":{"f":"관세환급금은 납세의무자가 환급을 청구하지 아니하더라도 세관장이 확인한 것은 환급하여야 한다.","w":"환급은 청구가 있을 때만 하는 것이 아니다. 세관장이 확인한 관세환급금은 납세의무자가 청구하지 않아도 환급해야 한다(관세법 제46조제1항).","c":"상","v":1},"관세사2017_34-18-2":{"f":"납세의무자의 관세환급금에 관한 권리는 대통령령으로 정하는 바에 따라 제3자에게 양도할 수 있다.","w":"관세환급금에 관한 권리는 일신전속권이 아니어서 양도할 수 있다. 양도하려면 양도인·양수인의 주소와 성명, 환급사유, 환급금액을 적은 문서를 세관장에게 제출한다(관세법 제46조제3항, 시행령 제53조).","c":"상","v":1},"관세사2017_34-18-3":{"f":"세관장은 납세의무자가 관세의 과오납금의 환급을 청구한 때에는 지체 없이 이를 관세환급금으로 결정하고 30일 이내에 환급하여야 한다.","w":"결정은 지체 없이 하고, 30일 이내에 환급해야 한다. 30일은 결정 기한이 아니라 환급 기한이다(관세법 제46조제1항).","c":"상","v":1},"관세사2017_34-18-5":{"f":"세관장은 관세환급금의 환급에 있어서 그 환급액이 과다한 것을 알게 되었을 때에는 해당 관세환급금을 지급받은 자로부터 과다지급된 금액을 징수하여야 하며, 이에 과다환급을 한 날의 다음 날부터 징수결정일까지의 기간에 대하여 대통령령으로 정하는 이율에 따라 계산한 금액을 더하여야 한다.","w":"과다환급액을 징수할 때는 가산금을 더한다. 더할 수 없는 것이 아니라 더하여야 한다(관세법 제47조).","c":"상","v":1},"관세사2017_34-32-1":{"f":"수입신고가 수리된 개인의 자가사용물품이 수입한 상태 그대로 수입신고 수리일부터 6개월 이내에 보세구역에 반입하였다가 다시 수출하는 경우에는 수입할 때 납부한 관세를 환급한다.","w":"자가사용물품 환급은 수입신고 수리일부터 6개월 이내에 보세구역에 반입했다가 수출하는 경우이다. 1년은 계약 내용과 다른 물품의 환급 기간이다(관세법 제106조의2제1항제1호).","c":"상","v":1},"관세사2017_34-32-2":{"f":"수입신고가 수리된 개인의 자가사용물품이 수입한 상태 그대로 수출되는 경우로서 수입신고 수리일부터 6개월 이내에 관세청장이 정하는 바에 따라 세관장의 확인을 받고 다시 수출하는 경우에는 수입할 때 납부한 관세를 환급한다.","w":"6개월의 기산점은 수입신고일이 아니라 수입신고 수리일이다(관세법 제106조의2제1항제2호).","c":"상","v":1},"관세사2017_34-32-3":{"f":"자가사용물품은 해당 물품이 국내에서 사용된 사실이 없다고 세관장이 인정하고 수입신고 당시의 성질 또는 형태가 변경되지 아니한 상태로 수출되어야 수입할 때 납부한 관세를 환급한다.","w":"수입한 상태 그대로 수출된 것으로 보려면 성질·형태가 변경되지 않았을 것과 국내에서 사용된 사실이 없다고 세관장이 인정할 것, 두 요건을 모두 갖춰야 한다(관세법 시행령 제124조의2제1항).","c":"상","v":1},"관세사2017_34-32-5":{"f":"자가사용물품을 수입한 상태 그대로 전부 수출하는 경우에는 이미 납부한 관세의 전액을 환급한다.","w":"전부를 수출하면 이미 납부한 관세의 전액을 환급하고, 일부를 수출하면 그 일부 물품에 해당하는 관세액을 환급한다. 내국세와 행정비용을 빼지 않는다(관세법 시행령 제124조의2제3항).","c":"상","v":1},"관세사2017_34-35-1":{"f":"관세의 면제 한도는 여행자 1명의 휴대품 또는 별송품으로서 각 물품의 과세가격 합계 기준으로 미화 800달러 이하로 한다.","w":"여행자 휴대품의 기본면세범위는 출제 당시 미화 600달러였고 2022년 9월부터 800달러다. 어느 기준으로도 400달러는 아니며, 술·담배·향수는 따로 별도면세범위를 둔다(관세법 시행규칙 제48조제2항·제3항).","c":"상","v":1},"관세사2017_34-35-2":{"f":"19세 미만인 사람이 반입하는 술ㆍ담배는 관세를 면제하지 아니한다.","w":"기준 연령은 20세가 아니라 19세 미만이다. 19세가 되는 해의 1월 1일을 맞이한 사람은 제외한다(관세법 시행규칙 제48조제3항).","c":"상","v":1},"관세사2017_34-35-4":{"f":"술은 용량 2리터 이하이고 가격이 미화 400달러 이하인 경우 관세를 면제한다.","w":"현행 면세범위는 병 수가 아니라 술 2리터 이하, 미화 400달러 이하이다. 증류주 1병·포도주 2병 같은 병 단위 기준은 지금 규정에 없다(관세법 시행규칙 제48조제3항).","c":"상","v":1},"관세사2017_34-35-5":{"f":"궐련의 경우 200개비까지 관세를 면제하며, 전자담배 니코틴용액의 경우에도 20밀리리터까지 관세 면제 대상이다.","w":"전자담배 니코틴용액도 20밀리리터까지 면세 대상이다. 궐련형 전자담배 200개비, 엽궐련 50개비, 그 밖의 담배 250그램도 면세 범위다(관세법 시행규칙 제48조제3항).","c":"상","v":1},"관세사2019_36-03-2":{"f":"세관장은 관세환급금을 환급하는 경우에 환급받을 자가 세관에 납부하여야 하는 관세와 그 밖의 세금, 가산세 또는 강제징수비가 있을 때에는 환급하여야 하는 금액에서 이를 충당할 수 있다.","w":"환급받을 자가 낼 관세나 세금이 있으면 환급금에서 충당할 수 있다. 충당하면 권리자에게 통보해야 한다(관세법 제46조제2항, 시행령 제52조).","c":"상","v":1},"관세사2019_36-03-3":{"f":"한국은행은 세관장이 환급금지급계정에 이체된 금액으로부터 당해 회계연도의 환급 통지서 발행금액중 다음 회계연도 1월 15일까지 지급하지 못한 환급금을 세관환급금 지급미필이월계정에 이월하여 정리하여야 한다.","w":"이월 기준일은 다음 회계연도 1월 15일이다. 이월 대상은 세관장의 환급금지급계정에 이체된 금액 중 환급통지서를 발행하고도 그 날까지 지급하지 못한 환급금이며, 이월하여 정리하는 주체는 한국은행이다(관세법 시행령 제55조제1항).","c":"상","v":1},"관세사2019_36-03-4":{"f":"세관장은 납세의무자가 환급세액의 환급을 청구할 때에는 대통령령으로 정하는 바에 따라 지체 없이 이를 관세환급금으로 결정하고 30일 이내에 환급하여야 한다.","w":"환급 기한은 60일이 아니라 30일이고, 세부 사항은 재정경제부령이 아니라 대통령령에 위임되어 있다(관세법 제46조제1항).","c":"상","v":1},"관세사2019_36-03-5":{"f":"세관장은 관세환급금의 과다환급액을 징수할 때에는 과다환급을 한 날의 다음 날부터 징수결정을 하는 날까지의 기간에 대하여 대통령령으로 정하는 이율에 따라 계산한 금액을 과다환급액에 더하여야 한다.","w":"가산 기간은 과다환급을 한 날의 다음 날부터 징수결정일까지이고, 이율은 한국은행이 아니라 대통령령으로 정한다(관세법 제47조제2항).","c":"상","v":1},"관세사2019_36-13-2":{"f":"정부나 지방자치단체가 수입하는 물품으로서 재정경제부령으로 정하는 물품이 수입될 때에는 세관장은 재정경제부령으로 정하는 바에 따라 5년을 넘지 아니하는 기간을 정하여 관세의 분할납부를 승인할 수 있다.","w":"정부·지방자치단체 수입물품의 분할납부 승인은 세관장이 하고, 기간은 5년을 넘지 못한다(관세법 제107조제2항제2호).","c":"상","v":1},"관세사2020_37-01-2":{"f":"세관장은 매월 관세환급금결정액보고서를 작성하여 재정경제부장관에게 제출하여야 한다.","w":"보고서는 분기별이 아니라 매월 작성하고, 제출처는 관세청장이 아니라 재정경제부장관이다(관세법 시행령 제51조제3항).","c":"상","v":1},"관세사2020_37-01-3":{"f":"관세환급금을 환급받을 자가 환급통지서발행일부터 1년 내에 환급금을 지급받지 못한 때에는 세관장에게 다시 환급절차를 밟을 것을 요구할 수 있다.","w":"1년 내에 지급받지 못한 때 다시 환급절차를 요구할 수 있다. 의무가 아니며 기간도 6개월이 아니라 1년이다(관세법 시행령 제55조제3항).","c":"상","v":1},"관세사2020_37-01-4":{"f":"한국은행은 세관장이 환급금지급계정에 이체된 금액으로부터 당해 회계연도의 환급 통지서 발행금액중 다음 회계연도 1월 15일까지 지급하지 못한 환급금을 세관환급금지급미필이월계정에 이월하여 정리하여야 한다.","w":"이월 기준일은 다음 회계연도 1월 15일이다(관세법 시행령 제55조제1항).","c":"상","v":1},"관세사2020_37-01-5":{"f":"세관장은 관세환급금의 과다환급액을 징수할 때에는 과다환급을 한 날의 다음 날부터 징수결정을 하는 날까지의 기간에 대하여 대통령령으로 정하는 이율에 따라 계산한 금액을 과다환급액에 더하여야 한다.","w":"가산은 과다환급을 한 날이 아니라 그 다음 날부터 센다(관세법 제47조제2항).","c":"상","v":1},"관세사2020_37-13-1":{"f":"세관장은 천재지변으로 관세납부 등을 정하여진 기한까지 할 수 없다고 인정될 때에는 1년을 넘지 아니하는 기간을 정하여 대통령령으로 정하는 바에 따라 관세를 분할하여 납부하게 할 수 있다.","w":"천재지변 등으로 인한 분할납부는 1년 범위이고 세부 사항은 대통령령으로 정한다. 5년은 시설기계류 등 제107조제2항 승인물품의 분할납부 기간이다(관세법 제107조제1항).","c":"상","v":1},"관세사2020_37-13-2":{"f":"지방자치단체가 수입하는 물품으로서 재정경제부령으로 정하는 물품이 수입될 때에는 세관장은 재정경제부령으로 정하는 바에 따라 5년을 넘지 아니하는 기간을 정하여 관세의 분할납부를 승인할 수 있다.","w":"지방자치단체 수입물품의 분할납부 승인 기간은 5년 이내이고, 세부 사항은 재정경제부령으로 정한다(관세법 제107조제2항제2호).","c":"상","v":1},"관세사2020_37-13-4":{"f":"관세의 분할납부를 승인받은 물품을 동일한 용도로 사용하려는 자에게 양도한 경우에는 그 양수인이 관세를 납부하여야 한다.","w":"같은 용도로 쓸 사람에게 양도하면 양수인이 납부하고, 다른 용도로 쓸 사람에게 양도하면 양도인이 납부한다(관세법 제107조제5항).","c":"상","v":1},"관세사2020_37-13-5":{"f":"분할납부를 승인받은 자는 대통령령으로 정하는 바에 따라 해당 조건의 이행 여부를 확인하는 데에 필요한 서류를 세관장에게 제출하여야 한다.","w":"사후관리 서류는 관세청장이 아니라 세관장에게 제출한다(관세법 제108조제2항).","c":"상","v":1},"관세사2022_39-17-2":{"f":"세관장은 천재지변으로 관세법에 따른 신고, 신청, 청구를 정하여진 기한까지 할 수 없다고 인정될 때에는 1년을 넘지 아니하는 기간을 정하여 대통령령으로 정하는 바에 따라 관세를 분할하여 납부하게 할 수 있다.","w":"천재지변으로 인한 분할납부는 2년이 아니라 1년을 넘지 못한다(관세법 제107조제1항).","c":"상","v":1},"관세사2022_39-17-3":{"f":"관세의 분할납부를 승인받은 자가 파산선고를 받은 경우에는 그 파산관재인이 관세를 납부하여야 한다.","w":"파산선고를 받으면 파산관재인이 납부한다. 청산인은 승인받은 법인이 해산한 경우의 납부자이다(관세법 제107조제7항·제8항).","c":"상","v":1},"관세사2022_39-17-4":{"f":"분할납부의 승인을 받은 자는 해당 물품을 수입신고 수리일부터 1개월 이내에 설치 또는 사용할 장소에 반입하여야 한다.","w":"반입 기한은 수입신고 수리일부터 1개월이다(관세법 시행령 제129조제1항).","c":"상","v":1},"관세사2022_39-17-5":{"f":"분할납부의 승인을 받은 자가 물품의 반입 지연사유로 인하여 세관장에게 반입 기한의 연장을 신청한 경우 세관장은 수입신고 수리일부터 3개월의 범위에서 해당 기한을 연장할 수 있다.","w":"연장은 수입신고 수리일부터 3개월의 범위까지 가능하다(관세법 시행령 제129조제3항).","c":"상","v":1},"관세사2023_40-01-5":{"f":"세관장은 매월 관세환급금결정액보고서를 작성하여 재정경제부장관에게 제출하여야 한다.","w":"보고서는 분기별이 아니라 매월 작성한다(관세법 시행령 제51조제3항).","c":"상","v":1},"관세사2024_41-07-3":{"f":"한국은행은 환급금지급계정에 이체된 금액으로부터 당해 회계연도의 환급통지서 발행금액중 다음 회계연도 1월 15일까지 지급하지 못한 환급금을 세관환급금지급미필이월계정에 이월하여 정리하여야 한다.","w":"미지급 환급금을 이월계정에 이월하여 정리하는 주체는 세관장이 아니라 한국은행이다(관세법 시행령 제55조제1항).","c":"상","v":1},"관세사2025_42-10-4":{"f":"세관장은 관세환급금을 결정한 때에는 즉시 환급금 해당액을 환급받을 자에게 지급할 것을 내용으로 하는 지급지시서를 한국은행에 송부하여야 한다.","w":"지급지시서는 분기별로 모아 보내지 않고 환급금을 결정한 때 즉시 한국은행에 송부한다(관세법 시행령 제54조제1항).","c":"상","v":1},"관세사2017_34-24-1":{"f":"수입자ㆍ수출자 및 생산자는 협정에 따른 원산지의 확인, 협정관세의 적용 등에 필요한 것으로서 원산지증빙서류 등 대통령령으로 정하는 서류를 5년의 범위에서 대통령령으로 정하는 기간(협정에서 정한 기간이 5년을 초과하는 경우에는 그 기간) 동안 보관하여야 한다.","w":"원산지증빙서류의 보관기간은 5년의 범위에서 대통령령으로 정하는 기간이다. 협정이 5년을 넘는 기간을 정했으면 그 기간을 따른다(FTA관세특례법 제15조).","c":"상","v":1},"관세사2018_35-36-2":{"f":"해당 물품이 둘 이상의 국가에 걸쳐 생산ㆍ가공 또는 제조된 경우, 해당 물품에 대하여 일정 수준 이상의 부가가치를 창출한 국가를 그 물품의 원산지로 한다.","w":"둘 이상의 국가에 걸친 경우 공정을 수행한 모든 국가가 원산지가 되는 것이 아니다. 협정이 정한 바에 따라 품목번호가 일정 단위 이상 바뀌는 최종 가공국, 일정 수준 이상 부가가치를 창출한 국가, 주요 공정을 수행한 국가가 원산지이다(FTA관세특례법 제7조제1항제2호).","c":"상","v":1},"관세사2019_36-37-2":{"f":"체약상대국이란 우리나라와 자유무역협정을 체결한 국가를 말하며 국가연합ㆍ경제공동체 또는 독립된 관세영역을 포함한다.","w":"체약상대국에는 국가연합, 경제공동체, 독립된 관세영역도 포함된다(FTA관세특례법 제2조제1항제2호).","c":"상","v":1},"관세사2019_36-38-1":{"f":"수출실적이 있는 물품 또는 새롭게 수출하려는 물품이 원산지 결정기준을 충족하는 물품(품목번호 6단위를 기준으로 한다)임을 증명할 수 있는 전산처리시스템을 보유하고 있거나 그 밖의 방법으로 증명할 능력이 있을 것","w":"원산지인증수출자 요건의 품목번호 기준은 10단위가 아니라 6단위이다(FTA관세특례법 시행령 제7조제1호가목).","c":"상","v":1},"관세사2019_36-38-2":{"f":"원산지인증수출자 인증신청일 이전 최근 2년간 서면조사 또는 현지조사를 거부한 사실이 없을 것","w":"확인 기간은 3년이 아니라 인증신청일 이전 최근 2년간이다(FTA관세특례법 시행령 제7조제1호나목).","c":"상","v":1},"관세사2019_36-38-4":{"f":"원산지인증수출자 인증신청일 이전 최근 2년간 속임수 또는 부정한 방법으로 원산지 증명서를 발급신청하거나 작성ㆍ발급한 사실이 없을 것","w":"확인 기간은 최근 2년간이다(FTA관세특례법 시행령 제7조제1호마목).","c":"상","v":1},"관세사2019_36-38-5":{"f":"원산지인증수출자 인증신청일 이전 최근 2년간 서류의 보관의무를 위반한 사실이 없을 것","w":"확인 기간은 최근 2년간이다(FTA관세특례법 시행령 제7조제1호라목).","c":"상","v":1},"관세사2020_37-36-1":{"f":"\"협정관세\"란 협정에 따라 체약상대국을 원산지로 하는 수입물품에 대하여 관세를 철폐하거나 세율을 연차적으로 인하하여 부과하여야 할 관세를 말한다.","w":"협정관세는 세율을 연차적으로 인하하는 것이다. 일시적으로 인상하거나 인하하는 개념이 아니다(FTA관세특례법 제2조제1항제6호).","c":"상","v":1},"관세사2020_37-38-3":{"f":"수입신고의 수리 전까지 협정관세의 적용신청을 하지 못한 수입자는 해당 물품의 수입신고 수리일부터 1년 이내에 협정관세의 적용을 신청할 수 있다.","w":"사후적용 신청기간은 수입신고 수리일부터 1년이다. 2년이 아니고, 기산점도 수입신고일이 아니라 수리일이다(FTA관세특례법 제9조제1항).","c":"상","v":1},"관세사2025_42-37-1":{"f":"협정관세의 연도별 세율은 협정에서 정하는 바에 따라 대통령령으로 정하고, 협정관세의 적용기간, 적용수량 등도 대통령령으로 정한다.","w":"협정관세의 연도별 세율, 적용기간, 적용수량 등은 모두 협정에서 정하는 바에 따라 대통령령으로 정한다(FTA관세특례법 제4조제1항).","c":"상","v":1},"관세사2025_42-38-5":{"f":"수입자가 수입신고한 물품이 관세법 제87조에 따라 품목분류가 변경되어 부족세액이 발생하여 수정신고하는 경우 수정신고를 한 날부터 45일 이내에 협정관세의 사후적용을 신청할 수 있다.","w":"품목분류 변경으로 수정신고한 경우 협정관세 사후적용은 수정신고를 한 날부터 45일 이내에 신청한다. 6개월이 아니다(FTA관세특례법 제9조제2항, 시행령 제5조제3항).","c":"상","v":1},"관세사2026_43-35-5":{"f":"칠레와의 협정에 따른 원산지증명서의 유효기간은 서명일부터 2년으로 한다.","w":"칠레와의 협정은 서명일부터 2년이다. 다른 협정은 원칙적으로 발급일 또는 서명일부터 1년이다(FTA관세특례법 시행령 제6조제2항).","c":"상","v":1},"관세사2017_34-27-3":{"f":"관세청장은 세관의 조사ㆍ감시 등 관세행정과 관련한 정보 제공 및 관계 자료 조사를 위하여 명예세관원을 위촉할 수 있으며, 필요한 경우 그 활동에 대하여 활동 경비를 지급할 수 있다.","w":"명예세관원을 위촉하는 사람은 관세청장이고, 필요한 경우 활동경비 등을 지급할 수 있다(관세법 제268조, 시행규칙 제80조의2제3항).","c":"상","v":1},"관세사2017_34-30-2":{"f":"관세범에 관한 사건에 대하여는 관세청장이나 세관장의 고발이 없으면 검사는 공소를 제기할 수 없다.","w":"관세범 사건은 관세청장이나 세관장의 고발이 있어야 공소를 제기할 수 있다. 검사가 따로 세관장에게 통보하고 기소하는 절차는 없다(관세법 제284조제1항).","c":"상","v":1},"관세사2018_35-33-2":{"f":"과세자료제출기관의 장이 세관장으로부터 과세자료의 추가 또는 보완을 요구받은 경우에는 그 요구를 받은 날부터 15일 이내에 그 요구에 따라야 한다.","w":"추가·보완 요구에 응해야 하는 기한은 요구를 받은 날부터 15일이다(관세법 시행령 제263조의2제2항).","c":"상","v":1},"관세사2019_36-24-1":{"f":"관세청장이나 세관장은 관세범을 조사한 결과 범죄의 확증을 얻었을 때에는 벌금에 상당하는 금액, 몰수에 해당하는 물품 또는 추징금에 해당하는 금액을 납부할 것을 통고할 수 있다.","w":"통고처분의 대상은 벌금에 상당하는 금액, 몰수에 해당하는 물품, 추징금에 해당하는 금액이다. 과징금은 포함되지 않는다(관세법 제311조제1항).","c":"상","v":1},"관세사2019_36-24-3":{"f":"검사가 관세범에 관한 사건을 인지한 경우에도 관세청장이나 세관장의 고발이 없으면 공소를 제기할 수 없다.","w":"검사가 사건을 인지한 경우에도 관세청장이나 세관장의 고발이 없으면 공소를 제기할 수 없다(관세법 제284조제1항).","c":"상","v":1},"관세사2019_36-24-4":{"f":"관세범에 관한 서류에 서명날인하는 경우 본인이 서명할 수 없을 때에는 다른 사람에게 대리서명하게 할 수 있다.","w":"본인이 서명할 수 없으면 다른 사람이 대리서명하고 도장을 찍는다. 도장이 없으면 손도장을 찍고, 대리서명자가 그 사유를 적고 서명날인한다(관세법 제287조).","c":"상","v":1},"관세사2019_36-24-5":{"f":"해 진 후에도 이미 시작한 검증ㆍ수색 또는 압수는 계속할 수 있다.","w":"해 진 후부터 해 뜨기 전까지 검증·수색·압수를 시작하지 못하지만, 이미 시작한 것은 계속할 수 있다. 현행범은 야간 제한이 없다(관세법 제306조).","c":"상","v":1},"관세사2020_37-23-1":{"f":"관세범에 관한 조사ㆍ처분은 세관공무원이 한다.","w":"관세범의 조사·처분은 검찰공무원이 아니라 세관공무원이 한다(관세법 제283조제2항).","c":"상","v":1},"관세사2020_37-23-2":{"f":"관세범에 관한 사건에 대하여는 관세청장이나 세관장의 고발이 없으면 검사는 공소를 제기할 수 없다.","w":"고발이 공소제기의 요건이다(관세법 제284조제1항).","c":"상","v":1},"관세사2020_37-23-3":{"f":"「관세법」제284조의2의제1항에 따라 서울세관에 관세범칙조사심의위원회를 둔다.","w":"심의위원회를 두는 세관은 인천공항세관, 서울세관, 부산세관, 인천세관, 대구세관, 광주세관, 평택세관이다. 제주세관은 포함되지 않는다(관세법 시행령 제266조의2제1항).","c":"상","v":1},"관세사2020_37-23-4":{"f":"관세범에 관한 서류는 인편이나 등기우편으로 송달하여야 한다.","w":"관세범에 관한 서류는 인편이나 등기우편으로 송달하고 수령증을 받는다. 일반우편은 쓰지 않는다(관세법 제288조·제289조).","c":"상","v":1},"관세사2022_39-30-3":{"f":"관세법 제270조의2(가격조작죄)의 죄를 저지를 목적으로 그 예비를 한 자는 처벌하지 아니한다.","w":"예비죄 처벌 규정이 적용되는 것은 전자문서 위조·변조죄(제268조의2), 밀수출입죄(제269조), 관세포탈죄(제270조)이다. 가격조작죄의 예비는 처벌 대상이 아니다(관세법 제271조제3항).","c":"상","v":1},"관세사2022_39-32-2":{"f":"현행범인에 대한 조사로서 긴급히 처리할 필요가 있을 때에는 그 주요 내용을 적은 서면으로 조서를 대신할 수 있다.","w":"조서를 서면으로 대신할 수 있는 경우는 현행범인에 대한 조사로서 긴급히 처리할 필요가 있을 때이다. 현행범이 아닌 관세범에는 적용되지 않는다(관세법 제293조).","c":"상","v":1},"관세사2023_40-32-4":{"f":"관세범칙조사심의위원회의 위원장은 관세청의 3급부터 5급까지에 해당하는 공무원 중 관세청장이 지정하는 사람이 된다.","w":"위원장은 관세청 차장이 아니라 관세청 3급부터 5급까지 공무원 중 관세청장이 지정한 사람이다(관세법 시행령 제266조의2제3항).","c":"상","v":1},"관세사2023_40-33-1":{"f":"부정한 방법으로 관세를 감면받거나 관세를 감면받은 물품에 대한 관세의 징수를 면탈한 자는 3년 이하의 징역에 처하거나 감면받거나 면탈한 관세액의 5배 이하에 상당하는 벌금에 처한다.","w":"형량은 3년 이하의 징역 또는 감면·면탈한 관세액의 5배 이하의 벌금이다(관세법 제270조제4항).","c":"상","v":1},"관세사2023_40-33-2":{"f":"부정한 방법으로 관세를 환급받은 자는 3년 이하의 징역 또는 환급받은 세액의 5배 이하에 상당하는 벌금에 처한다.","w":"부정환급의 형량은 3년 이하의 징역 또는 환급받은 세액의 5배 이하 벌금이다. 세관장은 부정하게 환급받은 세액을 즉시 징수한다(관세법 제270조제5항).","c":"상","v":1},"관세사2023_40-33-4":{"f":"관세법 제269조(밀수출입죄)의 죄를 저지를 목적으로 그 예비를 한 자는 본죄의 2분의 1을 감경하여 처벌한다.","w":"예비는 본죄와 같이 처벌하지 않고 본죄의 2분의 1을 감경하여 처벌한다(관세법 제271조제3항). 미수범은 본죄에 준하여 처벌한다.","c":"상","v":1},"관세사2023_40-33-5":{"f":"관세청장 또는 세관장은 세관공무원에게 금품을 공여한 자에 대해서는 그 금품 상당액의 2배 이상 5배 내의 과태료를 부과ㆍ징수한다.","w":"금품 공여자에게는 금품 상당액의 2배 이상 5배 내의 과태료를 부과한다. 형사처벌을 받으면 과태료를 부과하지 않는다(관세법 제277조의2제5항).","c":"상","v":1},"관세사2024_41-26-4":{"f":"과세자료 비밀유지의무를 위반한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처하며, 이에 따른 징역과 벌금은 병과할 수 있다.","w":"과세자료 비밀유지의무 위반은 3년 이하의 징역 또는 1천만원 이하의 벌금이고 징역과 벌금을 병과할 수 있다(관세법 제264조의9).","c":"상","v":1},"관세사2025_42-21-1":{"f":"관세범에 대한 조사·처분은 세관공무원이 하여야 한다.","w":"관세범의 조사·처분은 경찰공무원이 아니라 세관공무원이 한다(관세법 제283조제2항).","c":"상","v":1},"관세사2025_42-21-2":{"f":"세관공무원은 범죄사실을 증명하기에 충분한 물품을 피의자가 신변에 은닉하였다고 인정될 때 이를 내보이도록 요구하고, 따르지 아니하면 조사 대상자의 신변을 수색할 수 있다.","w":"신변수색은 범죄사실을 증명하기에 충분한 물품을 피의자가 은닉했다고 인정되는 경우에 먼저 내보이도록 요구하고, 따르지 않을 때 할 수 있다(관세법 제301조제1항).","c":"상","v":1},"관세사2025_42-21-3":{"f":"세관공무원은 관세범 조사에 의하여 발견한 물품이 범죄의 사실을 증명하기에 충분하거나 몰수하여야 하는 것으로 인정될 때 이를 압수할 수 있다.","w":"발견한 모든 물품을 압수하는 것이 아니라 범죄사실을 증명하기에 충분하거나 몰수할 물품이라고 인정될 때 압수할 수 있다(관세법 제303조제1항).","c":"상","v":1},"관세사2025_42-21-5":{"f":"사법경찰관리의 직무를 행하는 세관공무원이 법령에 의하여 피의자를 구속하는 때에는 세관관서ㆍ국가경찰관서 또는 교도관서에 유치하여야 한다.","w":"시·군·읍·면사무소는 압수물품을 보관시킬 수 있는 곳이고 피의자 유치 장소가 아니다. 피의자는 세관관서, 국가경찰관서, 교도관서에 유치한다(관세법 시행령 제267조, 관세법 제303조제2항).","c":"상","v":1},"관세사2025_42-26-2":{"f":"세관장은 관세법 제241조제1항 및 제2항을 위반하여 수입하는 「마약류 관리에 관한 법률」에 따른 마약류의 위치정보를 수집할 수 있다.","w":"(2025 개정 전 기준 X. 현행은 2025.12.23 개정으로 수집 대상이 원료물질과 임시마약류를 포함한 마약류등으로 넓어져 맞는 문장이다) 출제 당시 관세법 제266조의2제1항의 위치정보 수집 대상은 「마약류 관리에 관한 법률」에 따른 마약류뿐이었다.","c":"상","v":1,"old":1,"ow":"(2025 개정 전 기준 X. 현행은 2025.12.23 개정으로 수집 대상이 원료물질과 임시마약류를 포함한 마약류등으로 넓어져 맞는 문장이다) 출제 당시 관세법 제266조의2제1항의 위치정보 수집 대상은 「마약류 관리에 관한 법률」에 따른 마약류뿐이었다."},"관세사2025_42-26-3":{"f":"관세청장은 관세법 제241조제1항 및 제2항을 위반하여 수입하는 「마약류 관리에 관한 법률」에 따른 마약류의 위치정보를 수집할 수 있다.","w":"(2025 개정 전 기준 X. 현행은 2025.12.23 개정으로 수집 대상이 원료물질과 임시마약류를 포함한 마약류등으로 넓어져 맞는 문장이다) 출제 당시 관세법 제266조의2제1항의 위치정보 수집 대상은 「마약류 관리에 관한 법률」에 따른 마약류뿐이었고 임시마약류는 들어 있지 않았다.","c":"상","v":1,"old":1,"ow":"(2025 개정 전 기준 X. 현행은 2025.12.23 개정으로 수집 대상이 원료물질과 임시마약류를 포함한 마약류등으로 넓어져 맞는 문장이다) 출제 당시 관세법 제266조의2제1항의 위치정보 수집 대상은 「마약류 관리에 관한 법률」에 따른 마약류뿐이었고 임시마약류는 들어 있지 않았다."},"관세사2025_42-26-4":{"f":"수집된 위치정보의 저장ㆍ보호ㆍ이용 및 파기 등에 관한 사항은 「위치정보의 보호 및 이용 등에 관한 법률」을 따른다.","w":"수집된 위치정보의 저장·보호·이용·파기는 개인정보 보호법이 아니라 위치정보의 보호 및 이용 등에 관한 법률을 따른다(관세법 제266조의2제2항).","c":"상","v":1},"관세사2025_42-26-5":{"f":"위치정보 수집대상 물품의 구체적인 범위와 방법, 절차 등에 관하여 필요한 사항은 관세청장이 정한다.","w":"수집대상 물품의 범위, 방법, 절차는 재정경제부령이 아니라 관세청장이 정한다(관세법 제266조의2제3항).","c":"상","v":1},"관세사2017_34-34-5":{"f":"양허의 철회에 대한 보상으로 우리나라가 새로 양허한 품목에 대하여는 그 양허의 효력이 발생한 날부터 관세법에 따른 세율을 적용하지 아니한다.","w":"보상으로 새로 양허한 품목은 양허의 효력이 발생한 날부터 관세법의 세율이 아니라 양허한 세율이 적용된다. 반대로 양허를 철회한 품목은 철회의 효력이 발생한 날부터 관세법의 세율을 적용한다(관세법 제80조).","c":"상","v":1},"관세사2017_34-36-2":{"f":"관세품목분류위원회의 위원장은 관세청의 3급 공무원 또는 고위공무원단에 속하는 일반직공무원으로서 관세청장이 지정하는 자가 된다.","w":"위원장은 관세청 차장이 아니라 관세청의 3급 공무원 또는 고위공무원단 일반직공무원 중 관세청장이 지정하는 사람이다(관세법 시행령 제100조제2항).","c":"상","v":1},"관세사2017_34-39-2":{"f":"수입신고를 하여야 하는 우편물, 관세가 감면되는 물품에 대하여는 간이세율을 적용하지 아니한다.","w":"간이세율을 적용하는 물품은 휴대품, 수입신고를 하지 않는 우편물, 탁송품, 별송품이다. 탁송품은 적용 대상이므로 적용 제외 물품에 들어가지 않는다(관세법 제81조제1항, 시행령 제96조제2항).","c":"상","v":1},"관세사2018_35-13-4":{"f":"농림축수산물이 아닌 특정물품의 수입을 억제할 필요가 있는 경우에는 일정한 수량을 초과하여 수입되는 분에 대하여 100분의 40의 범위의 율을 기본세율에 더하여 관세를 부과할 수 있다.","w":"수입을 억제하는 할당관세는 기본세율에 100분의 40의 범위의 율을 더한다. 100분의 50이 아니다. 농림축수산물은 국내외 가격차에 상당하는 율을 더한 범위까지 가능하다(관세법 제71조제2항).","c":"상","v":1},"관세사2019_36-12-2":{"f":"일반특혜관세를 부과할 때 해당 특혜대상물품의 수입이 국내산업에 미치는 영향 등을 고려하여 그 물품에 적용되는 세율에 차등을 둘 수 있다.","w":"일반특혜관세에서는 세율에 차등을 두거나 특혜대상물품의 수입수량 등을 한정할 수 있다(관세법 제76조제2항).","c":"상","v":1},"관세사2019_36-15-1":{"f":"재정경제부장관은 긴급관세 또는 잠정긴급관세의 부과 여부를 결정하기 위하여 필요하다고 인정되는 경우에는 관계 행정기관의 장 및 이해관계인 등에게 관련 자료의 제출 등 필요한 협조를 요청할 수 있다.","w":"긴급관세 부과 여부를 결정하는 주체는 관세청장이 아니라 재정경제부장관이다(관세법 제65조제7항).","c":"상","v":1},"관세사2019_36-15-2":{"f":"재정경제부장관은 긴급관세를 부과하는 경우에는 이해당사국과 긴급관세부과의 부정적 효과에 대한 적절한 무역보상방법에 관하여 협의를 할 수 있다.","w":"협의의 주체는 재정경제부장관이고, 의무가 아니라 할 수 있다는 임의 규정이다(관세법 제65조제3항).","c":"상","v":1},"관세사2019_36-15-4":{"f":"긴급관세의 부과기간은 4년을 초과할 수 없으며, 잠정긴급관세는 200일을 초과하여 부과할 수 없다.","w":"긴급관세는 4년, 잠정긴급관세는 200일까지이다. 재심사로 연장해도 총 적용기간은 8년을 넘지 못한다(관세법 제65조제5항).","c":"상","v":1},"관세사2019_36-15-5":{"f":"긴급관세 또는 잠정긴급관세를 부과하여야 하는 대상 물품은 재정경제부령으로 정한다.","w":"긴급관세의 대상 물품, 세율, 적용기간 등은 대통령령이 아니라 재정경제부령으로 정한다(관세법 제65조제6항).","c":"상","v":1},"관세사2020_37-16-4":{"f":"관세청장은 회의의 원활한 운영을 위하여 품목분류와 관련된 기술적인 사항 등에 대한 의견을 듣기 위하여 관련 학계ㆍ연구기관 또는 협회 등에서 활동하는 자를 기술자문위원으로 위촉할 수 있다.","w":"기술자문위원은 위원장이 아니라 관세청장이 위촉하며 의무가 아니라 할 수 있는 사항이다(관세법 시행령 제100조제8항).","c":"상","v":1},"관세사2020_37-19-5":{"f":"조약에 따라 우리나라가 양허한 품목에 대하여 그 양허를 철회한 경우에는 해당 조약에 따라 철회의 효력이 발생한 날부터 「관세법」에 따른 세율을 적용한다.","w":"관세법의 세율은 철회의 효력이 발생한 날부터 적용된다. 다음 날부터가 아니다(관세법 제80조제1항).","c":"상","v":1},"관세사2020_37-20-1":{"f":"품목분류의 사전심사의 신청을 받은 관세청장은 신청을 받은 날부터 30일 이내에 해당 물품에 적용될 품목분류를 심사하여 이를 신청인에게 통지하여야 하며, 제출자료의 미비 등으로 품목분류를 심사하기 곤란한 경우에는 신청을 반려할 수 있다.","w":"사전심사 통지기한은 신청을 받은 날부터 30일이다. 보정기간, 위원회 심의, 분석에 걸리는 기간은 제외한다(관세법 시행령 제106조제4항).","c":"상","v":1},"관세사2020_37-20-2":{"f":"관세청장은 법원의 판결로 품목분류 변경이 필요한 경우에는 판결이 확정된 날부터 3개월 이내에 이를 관세품목분류위원회의 심의에 부쳐야 한다.","w":"기산일은 판결이 확정된 날이고 다음 날이 아니다(관세법 시행령 제107조제2항).","c":"상","v":1},"관세사2020_37-20-3":{"f":"재정경제부장관은 대통령령으로 정하는 바에 따라 품목분류를 적용하는 데에 필요한 기준을 정할 수 있다.","w":"품목분류 적용기준을 정하는 사람은 재정경제부장관이다. 관세품목분류위원회는 심의기구이고 기준을 정하지 않는다(관세법 제85조제1항).","c":"상","v":1},"관세사2020_37-20-4":{"f":"관세청장은 「관세법」제86조제2항에 따라 품목분류를 심사하여 신청인에게 통지하는 경우에는 통관예정세관장에게도 그 내용을 통지하여야 한다.","w":"신청인에게 통지할 때 통관예정세관장에게도 통지하고 설명자료를 함께 보낸다. 관할 세무서장에게 통지하는 규정은 없다(관세법 시행령 제106조제5항).","c":"상","v":1},"관세사2022_39-16-5":{"f":"잠정세율의 적용을 받는 물품과 관련이 있는 관계부처의 장은 그 물품의 전부 또는 일부에 대하여 잠정세율의 적용정지를 재정경제부장관에게 요청할 수 있다.","w":"관계부처의 장은 적용정지를 요청할 수 있을 뿐이고 직접 정지할 수 없다. 잠정세율의 적용정지는 대통령령에서 정한 절차에 따른다(관세법 제50조제4항, 시행령 제57조).","c":"상","v":1},"관세사2024_41-31-5":{"f":"덤핑방지조치는 재정경제부령으로 그 적용시한을 따로 정하는 경우를 제외하고는 해당 덤핑방지조치의 시행일부터 5년이 지나면 그 효력을 잃는다.","w":"덤핑방지조치의 효력은 시행일부터 5년이다(관세법 제56조제3항).","c":"상","v":1},"관세사2025_42-11-1":{"f":"위원회는 위원장 1명과 30명 이상 40명 이하의 위원으로 구성된다.","w":"관세품목분류위원회는 위원장 1명과 30명 이상 40명 이하의 위원으로 구성한다(관세법 시행령 제100조제1항).","c":"상","v":1},"관세사2025_42-11-2":{"f":"위원회의 위원장은 관세청의 3급 공무원 또는 고위공무원단에 속하는 일반직공무원으로서 관세청장이 지정하는 사람이다.","w":"위원장은 호선하지 않는다. 관세청장이 지정한다(관세법 시행령 제100조제2항).","c":"상","v":1},"관세사2025_42-11-3":{"f":"위원회의 위원 중 시민단체에서 추천한 위원과 상품학에 관한 지식이 풍부한 위원은 한 번만 연임할 수 있다.","w":"시민단체 추천 위원과 상품학 지식이 풍부한 위원은 임기가 2년이고 한 번만 연임할 수 있다. 관세청 소속 공무원 등 공무원 위원에게는 이 임기 규정이 없다(관세법 시행령 제100조제3항).","c":"상","v":1},"관세사2025_42-11-4":{"f":"위원회의 회의는 구성원 과반수의 출석과 출석위원 과반수의 찬성으로 의결한다.","w":"회의는 위원장과 위원장이 지정하는 14명 이상 16명 이하 위원으로 구성하고, 구성원 과반수 출석에 출석위원 과반수 찬성으로 의결한다(관세법 시행령 제101조).","c":"상","v":1},"관세사2026_43-13-1":{"f":"긴급관세의 부과 또는 수입수량제한등의 조치 여부를 결정한 때에는 잠정긴급관세의 부과를 중단한다.","w":"긴급관세 부과 또는 수입수량제한 조치 여부를 결정하면 잠정긴급관세 부과는 중단한다. 유지하지 않는다(관세법 제66조제2항).","c":"상","v":1},"관세사2026_43-13-3":{"f":"긴급관세의 부과기간은 4년을 초과할 수 없다.","w":"긴급관세의 부과기간은 4년이다(관세법 제65조제5항).","c":"상","v":1},"관세사2026_43-13-4":{"f":"잠정긴급관세는 200일을 초과하여 부과할 수 없다.","w":"잠정긴급관세의 부과기간은 200일이다(관세법 제65조제5항).","c":"상","v":1},"관세사2026_43-13-5":{"f":"긴급관세에 대한 재심사의 결과에 따라 부과기간을 연장하는 경우에는 잠정긴급관세의 부과기간, 긴급관세의 부과기간, 수입수량제한 등의 적용기간 및 그 연장기간을 포함한 총 적용기간은 8년을 초과할 수 없다.","w":"재심사로 연장해도 모든 기간을 합친 총 적용기간은 8년을 넘지 못한다(관세법 제65조제5항).","c":"상","v":1},"관세사2023_40-05-5":{"f":"관세법에 따라 잠정가격을 신고한 후 확정된 가격을 신고한 경우 관세부과 제척기간의 기산일은 확정된 가격을 신고한 날의 다음날이다.","w":"잠정가격을 신고한 후 확정가격을 신고한 경우 기산일은 확정된 가격을 신고한 날의 다음 날이다. 기간 안에 확정가격을 신고하지 않으면 그 기간 만료일의 다음 날이다(관세법 시행령 제6조 제5호).","c":"상","v":1},"관세사2017_34-01":{"w":"명단 공개 대상은 체납발생일부터 1년이 지난 체납관세등이 일정액 이상인 체납자이다(법 제116조의2 제1항 제1호, 출제 당시 3억원, 현행 2억원). 5번은 금액 요건을 갖췄고 20%만 납부해 제외 사유(체납액 납부비율 100분의 50 이상, 영 제141조의5 제1항 제1호)에 해당하지 않으므로 공개할 수 있다.\n1번 불복청구 진행 중, 3번 회생계획인가에 따른 징수유예 기간 중, 2번·4번 관세정보위원회가 공개할 실익이 없거나 공개가 부적절하다고 인정한 경우는 공개하지 않는다(법 제116조의2 제1항 제1호 단서, 영 제141조의5 제1항).","c":"상","v":1},"관세사2017_34-13":{"w":"관세 납부의무 소멸 사유(법 제20조): 납부·충당, 부과의 취소, 부과제척기간 만료, 징수권 소멸시효 완성이다.\n3번은 부정한 방법으로 포탈한 관세의 부과제척기간이 5년이 아니라 10년이어서 5년이 지난 것만으로는 소멸하지 않는다.\n4번 5억원 이상 관세 소멸시효 10년, 5번 5억원 미만 5년은 맞다.","c":"상","v":1},"관세사2017_34-14":{"w":"관세징수권 소멸시효의 중단 사유는 납부고지, 경정처분, 납부독촉(출제 당시 납부최고), 통고처분, 고발, 「특정범죄 가중처벌 등에 관한 법률」 제16조에 따른 공소제기, 교부청구, 압류이다(법 제23조 제1항).\n사해행위 취소소송은 중단 사유가 아니라 그 소송기간 중 시효가 진행하지 않는 정지 사유이다(같은 조 제3항). 5번이다.","c":"상","v":1},"관세사2017_34-15":{"w":"담보 중 세관장이 인정하는 것에 한해 제공할 수 있는 것은 유가증권이다(법 제24조 제1항).\n국채·지방채, 납세보증보험증권, 보험에 가입된 등기 건물·등록 선박은 담보 종류로 법에 직접 정해져 있어 세관장 인정이 필요 없다.","c":"중","v":1},"관세사2017_34-20":{"w":"체납자료를 제공하지 않는 경우는 체납 관세에 대한 이의신청·심사청구·심판청구·행정소송이 계류 중인 경우(법 제44조 제1항 단서), 재해·도난으로 재산에 심한 손실을 입은 경우, 사업에 현저한 손실을 입은 경우, 사업이 중대한 위기에 처한 경우, 압류 또는 매각이 유예된 경우이다(영 제41조 제1항).\n체납처분 절차가 진행 중이라는 사정은 제외 사유에 없다. 2번이다.","c":"상","v":1},"관세사2017_34-21":{"w":"(2019 개정 전 기준) 출제 당시 법 제41조는 납부기한까지 완납하지 않으면 체납된 관세의 100분의 3에 상당하는 가산금을 징수하도록 했다. 징수금액의 최저한은 1만원이다(법 제40조, 영 제37조). 그래서 ㄱ 3, ㄴ 가산금, ㄷ 1만원인 1번이 정답이었다.\n지금은 가산금이 폐지되고 납부지연가산세로 바뀌어 납부고지서에 따른 납부기한까지 완납하지 않은 세액의 100분의 3을 가산세로 징수한다(법 제42조 제1항 제2호 나목). 현행 기준으로는 2번이 맞다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 법 제41조는 납부기한까지 완납하지 않으면 체납된 관세의 100분의 3에 상당하는 가산금을 징수하도록 했다. 징수금액의 최저한은 1만원이다(법 제40조, 영 제37조). 그래서 ㄱ 3, ㄴ 가산금, ㄷ 1만원인 1번이 정답이었다.\n지금은 가산금이 폐지되고 납부지연가산세로 바뀌어 납부고지서에 따른 납부기한까지 완납하지 않은 세액의 100분의 3을 가산세로 징수한다(법 제42조 제1항 제2호 나목). 현행 기준으로는 2번이 맞다."},"관세사2018_35-04":{"w":"납세담보의 종류: 금전, 국채·지방채, 세관장이 인정하는 유가증권, 납세보증보험증권, 토지, 보험에 가입된 등기·등록 대상 건물·공장재단·광업재단·선박·항공기·건설기계, 세관장이 인정하는 보증인의 납세보증서이다(법 제24조).\n납세의무자가 스스로 발행한 보험증명서는 담보 종류에 없다.","c":"상","v":1},"관세사2019_36-06":{"w":"납부기한 연장 신청서 기재사항은 납세의무자의 성명·주소·상호, 연장받으려는 세액과 해당 물품의 신고일자·신고번호·품명·규격·수량·가격, 연장받으려는 사유와 기간이다(영 제2조 제3항).\n납세실적과 재산내역은 기재사항이 아니다. 1번이다.","c":"상","v":1},"관세사2019_36-08":{"w":"(2019 개정 전 기준) 출제 당시 법 제41조는 체납된 관세를 내지 않으면 납부기한이 지난 날부터 1개월이 지날 때마다 체납 관세의 1만분의 75에 상당하는 중가산금을 가산금에 더하고 더하는 기간은 60개월을 넘지 못하게 했다. 그래서 4번이 정답이었다.\n지금은 가산금·중가산금이 폐지되고 납부지연가산세(미납세액 × 기간 × 대통령령으로 정하는 이자율, 고지서상 납부기한 다음 날부터 5년 한도)로 바뀌었다(법 제42조 제1항 제2호, 제4항).","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 법 제41조는 체납된 관세를 내지 않으면 납부기한이 지난 날부터 1개월이 지날 때마다 체납 관세의 1만분의 75에 상당하는 중가산금을 가산금에 더하고 더하는 기간은 60개월을 넘지 못하게 했다. 그래서 4번이 정답이었다.\n지금은 가산금·중가산금이 폐지되고 납부지연가산세(미납세액 × 기간 × 대통령령으로 정하는 이자율, 고지서상 납부기한 다음 날부터 5년 한도)로 바뀌었다(법 제42조 제1항 제2호, 제4항)."},"관세사2019_36-09":{"w":"납부의무 소멸 사유(법 제20조): 납부·충당, 부과취소, 제척기간 만료, 소멸시효 완성이다.\n납세의무자의 국적이 변경된 때는 소멸 사유가 아니다.","c":"상","v":1},"관세사2020_37-02":{"w":"납부기한 연장의 취소 사유는 관세를 지정한 납부기한 내에 납부하지 않은 때(ㄱ), 재산상황의 호전 등으로 연장할 필요가 없게 된 때(ㄹ), 파산선고·법인 해산 등으로 관세 전액을 징수하기 곤란한 때(ㄴ, ㄷ)이다(영 제2조 제6항).\nㄱ~ㄹ 모두 해당해 5번이다.","c":"상","v":1},"관세사2020_37-03":{"w":"수입신고수리 전 세액심사 대상은 감면받으려는 물품, 법 제107조에 따라 분할납부하려는 물품, 관세 체납자가 신고하는 물품(체납액 10만원 미만이거나 체납기간 7일 이내에 수입신고하는 경우는 제외), 불성실신고인이 신고하는 물품, 가격변동이 큰 물품 등 관세청장이 정하는 물품이다(규칙 제8조 제1항).\n3번은 체납액 10만원·체납기간 10일이라 대상이다. 4번은 5만원 체납이고 체납기간 7일 이내라 제외된다. 4번이다.","c":"상","v":1},"관세사2024_41-06":{"w":"납세보증보험증권(ㄱ)과 세관장이 인정하는 보증인의 납세보증서(ㄹ)는 세관장이 요청하면 특정인이 납부하여야 하는 금액을 일정 기일 이후에는 언제든지 세관장에게 지급한다는 내용의 것이어야 한다(법 제24조 제2항).\n유가증권(ㄴ)과 국채·지방채(ㄷ)에는 이 요건이 없다. ㄱ, ㄹ이므로 2번이다.","c":"상","v":1},"관세사2025_42-02":{"w":"월별납부 승인의 유효기간은 승인일부터 그 후 2년이 되는 날이 속하는 달의 마지막 날까지이다.\nㄱ 승인일, ㄴ 2년으로 4번이다.","c":"중","v":1},"관세사2025_42-04":{"w":"담보물 평가 기준: 공장재단·광업재단·선박·항공기·건설기계는 감정평가법인등의 평가액 또는 지방세법에 따른 시가표준액이다. ㄱ 평가액, ㄴ 시가표준액으로 1번이다.","c":"중","v":1},"관세사2025_42-08":{"w":"부과고지 대상물품은 여행자·승무원의 휴대품과 별송품(ㄱ), 우편물, 법령에 따라 세관장이 관세를 부과·징수하는 물품(ㄴ) 등이다(규칙 제9조).\n보세건설장에서 건설된 시설은 수입신고가 수리되기 전에 가동된 경우에 부과고지한다(법 제39조 제1항 제2호). ㄷ은 수리된 후 가동된 시설이라 해당하지 않는다. ㄱ, ㄴ이므로 3번이다.","c":"상","v":1},"관세사2025_42-19":{"w":"천재지변 등으로 인한 분할납부 신청서 기재사항은 납세의무자의 성명·주소·상호, 분할납부하려는 세액과 해당 물품의 신고일자·신고번호·품명·규격·수량·가격, 분할납부하려는 사유와 기간, 분할납부금액과 횟수이다(영 제125조 제1항).\n피해상황 및 그 산출기초는 기재사항에 없다. 1번이다.","c":"상","v":1},"관세사2026_43-02":{"w":"관세법 제22조 제1항: 관세 징수권의 소멸시효는 5억원 이상의 관세(내국세 포함)는 10년, 그 밖의 관세는 5년이다. 같은 조 제2항: 과오납금 등 관세 환급청구권은 행사할 수 있는 날부터 5년간 행사하지 않으면 소멸한다.\nㄱ 10, ㄴ 5, ㄷ 5. 정답 ①.","c":"상","v":1},"관세사2026_43-09":{"w":"세관장이 징수하지 않는 금액은 1만원 미만이다(관세법 시행령 제37조 제1항). 이때 수입신고수리일을 그 납부일로 본다(제2항). ㄱ 1만원, ㄴ 납부일이라 정답은 3번이다.","c":"상","v":1},"관세사2026_43-10":{"w":"수입신고수리 전 세액심사 대상은 감면받으려는 물품(ㄱ), 분할납부하려는 물품(ㄷ), 관세 체납자가 신고하는 물품, 불성실신고인이 신고하는 물품(ㄹ) 등이다(규칙 제8조 제1항). 체납자 신고 물품 가운데 체납액이 10만원 미만이거나 체납기간 7일 이내에 수입신고하는 경우는 제외되므로 ㄴ은 대상이 아니다.\nㄱ, ㄷ, ㄹ이므로 5번이다.","c":"상","v":1},"관세사2026_43-17":{"w":"체납액 5천만원 이상 체납자의 출국금지 해제 요청 사유: 납부 등으로 5천만원 미만이 된 경우, 압류·담보 제공 등으로 사유가 해소된 경우, 소멸시효 완성, 부과결정 취소로 5천만원 미만이 된 경우 등이다.\n국외 거주 직계존비속의 사망으로 출국하려는 경우는 해제 요청 사유가 아니다.","c":"중","v":1},"관세사2026_43-32":{"w":"세관장은 허가등을 받아 사업을 경영하는 자가 해당 사업과 관련된 관세·내국세등을 3회 이상 체납하고 체납액 합계가 500만원 이상이면 주무관청에 사업의 정지나 허가등의 취소를 요구할 수 있다. 재난, 질병, 사업의 현저한 손실, 그 밖에 대통령령으로 정하는 사유가 있으면 요구하지 않는다(법 제326조의2 제2항).\nㄱ 3, ㄴ 500, ㄷ 대통령령으로 4번이다.","c":"상","v":1},"관세사2019_36-20":{"w":"외국무역선이 개항에 입항하는 것은 허가 사항이 아니라 입항보고 사항이다.\n출항, 개항 바깥에서의 하역·환적, 선내 판매물품의 하역·환적, 국경출입차량의 통관역·통관장 출발은 모두 세관장의 허가가 필요하다.","c":"상","v":1},"관세사2019_36-23":{"w":"장치기간이 지나기 전이라도 공고 후 매각할 수 있는 물품은 살아 있는 동식물, 부패하거나 부패할 우려가 있는 것, 창고나 다른 외국물품에 해를 끼칠 우려가 있는 것, 기간이 지나면 사용할 수 없게 되거나 상품가치가 현저히 떨어질 우려가 있는 것 등이다.\n화주가 분명하지 않다는 사정은 이 사유에 들어 있지 않다.","c":"상","v":1},"관세사2020_37-25":{"w":"항공기 입항보고서에는 항공기의 종류·등록기호, 출항지, 입항일시, 적재물품의 적재지·개수·톤수 등을 적는다.\n총톤수와 순톤수는 선박 입항보고서의 기재사항이다.","c":"중","v":1},"관세사2020_37-27":{"w":"양양은 항구가 아니라 공항이므로 개항으로 지정된 것은 양양공항이다. 옥포항, 대산항, 고현항은 지정된 개항이고, 무안공항도 개항이다.","c":"중","v":1},"관세사2022_39-19":{"w":"ㄱ X: 국제무역선에 물품을 하역하려면 세관장에게 신고한다(법 제140조 제4항). 관세청장이 아니다.\nㄴ O: 세관장의 허가를 받으면 국제무역선에 내국물품을 적재할 수 있다(법 제140조 제6항).\nㄷ O: 국제항 바깥에서 하역·환적하려면 선장이 세관장의 허가를 받아야 한다(법 제142조 제1항).\nㄹ X: 세관장은 항외하역 허가 신청을 받은 날부터 10일 이내에 허가 여부를 통지해야 한다(법 제142조 제3항).\nㄴ, ㄷ이므로 3번이다.","c":"상","v":1},"관세사2022_39-20":{"w":"물품반입 정지 사유는 장치물품 관세를 낼 자금능력이 없는 경우, 운영인이나 사용인이 법 또는 명령을 위반한 경우(5번), 시설 미비 등으로 설치 목적을 달성하기 곤란한 경우이다(법 제178조 제1항). 영 제193조의2는 재고조사 결과 원자재소요량 관리가 적정하지 않은 경우(3번), 1년 동안 계속 반입·반출 실적이 없거나 6개월 이상 보세작업을 하지 않은 경우(1번), 운영인이 최근 1년 이내에 절차를 위반한 경우 등 관세청장이 정하는 사유(4번)를 더한다.\n2번은 보세작업 중단 기간이 3개월이라 6개월에 못 미치므로 정지 사유가 아니다.","c":"상","v":1},"관세사2022_39-24":{"w":"위탁판매로 매각할 수 있는 물품은 경매나 수의계약으로도 매각되지 않은 물품(5번)과 대통령령으로 정하는 물품이다(법 제210조 제4항). 대통령령으로 정하는 물품은 부패하거나 부패 우려가 있는 물품(1번), 기간경과로 사용할 수 없게 되거나 상품가치가 현저히 감소할 우려가 있는 물품(2번), 공매하면 매각 효율성이 떨어지거나 공매에 전문지식이 필요해 직접 공매하기 부적합한 물품(4번) 중 관세청장이 지정한 것이다(영 제222조 제5항).\n경쟁입찰은 2회 이상 부쳐도 매각되지 않으면 경매나 수의계약으로 넘어가므로(법 제210조 제3항) 3번은 위탁판매 대상이 아니다.","c":"상","v":1},"관세사2023_40-19":{"w":"승객예약자료 제출시한은 출항하는 선박·항공기는 출항 후 3시간 이내, 입항하는 선박·항공기는 입항 1시간 전까지이다. 운항예정시간이 3시간 이내이면 입항 30분 전까지 할 수 있다(규칙 제62조의3).\n4번은 운항예정시간이 5시간이므로 입항 1시간 전까지 내야 한다. 3번은 2시간이라 30분 전이 맞고 5번은 7시간이라 1시간 전이 맞다.","c":"상","v":1},"관세사2024_41-17":{"w":"보세판매장 특허 심사 평가기준에는 경영 능력(재무건전성), 관세법령 위반 여부, 관광 인프라 등 주변 환경, 중소·중견기업 제품 판매 실적 등 공헌도가 들어간다.\n상호출자제한기업집단 소속 기업의 주주·임원 구성은 평가요소에 없다.","c":"중","v":1},"관세사2024_41-19":{"w":"관세청장이 정하는 보세구역에 반입돼 수입신고가 수리된 물품은 수입신고 수리일부터 15일 이내에 반출해야 한다.\n자율관리보세구역은 화물관리인이나 운영인이 세관장에게 지정을 신청한다. ㄱ 관세청장, ㄴ 수입신고 수리일, ㄷ 세관장으로 3번이다.","c":"중","v":1},"관세사2024_41-30":{"w":"일반경쟁입찰로 매각할 때 공고할 사항은 물품의 품명·규격·수량, 포장의 종류와 개수, 매각의 일시·장소, 매각사유, 그 밖에 필요한 사항이다(영 제284조 제1항).\n화주의 주소와 성명은 매각 공고가 아니라 폐기 공고 사항이다(같은 조 제2항). 3번이다.","c":"상","v":1},"관세사2025_42-18":{"w":"외국에 운항하는 국제무역선 외의 선박(ㄷ)에는 국제무역선 규정을 준용한다(법 제146조 제1항 제1호). 다만 군함·군용기(ㄱ)와 국가원수 또는 정부를 대표하는 외교사절이 전용하는 선박·항공기(ㄴ)는 준용하지 않는다(같은 항 단서, 영 제168조).\nㄱ, ㄴ이므로 4번이다.","c":"상","v":1},"관세사2025_42-34":{"w":"반입정지 사유 중 반입·반출 실적 요건은 1년 동안 계속 실적이 없는 경우이다. 6개월은 기간이 맞지 않아 2번이 사유에 해당하지 않는다.\n1번 자금능력 부족, 3번 법령 위반, 4번 시설 미비, 5번 보세공장 재고조사 결과 부적정은 모두 열거된 사유이다.","c":"중","v":1},"관세사2026_43-20":{"w":"항외하역 허가 신청서에는 하역·환적하려는 장소와 일시, 선박의 종류·명칭·국적·총톤수·순톤수, 물품의 내외국물품 구분과 품명·수량·가격, 포장의 종류·기호·번호·개수, 신청사유를 적는다(영 제165조).\n허가수수료는 따로 납부하는 것이며(법 제142조 제2항) 신청서 기재사항이 아니다. 2번이다.","c":"상","v":1},"관세사2026_43-22":{"w":"보세판매장 특허수수료는 매출액 2천억원 이하는 매출액의 1만분의 5(㉠), 2천억원 초과 1조원 이하는 1억원 + 2천억원 초과분의 1만분의 25(㉢), 1조원 초과는 21억원(㉣) + 1조원 초과분의 1천분의 5이다(규칙 제68조의2 제1항).\n2천억원의 1만분의 5는 1억원이므로 ㉡ 2억원은 틀렸다. ㉤도 1천분의 1이 아니라 1천분의 5이다. ㉠, ㉢, ㉣이므로 3번이다.","c":"상","v":1},"관세사2017_34-03":{"w":"과세전통지 생략 사유 중 제척기간 만료 요건은 통지하려는 날부터 3개월 이내에 제척기간이 만료되는 경우이다. 2번은 4개월 이후이므로 생략할 수 없다.\n품목분류위원회 의결에 따른 세율·세번 변경, 잠정가격 신고 후 확정가격 신고, 수입신고 수리 전 세액심사 결과 부족세액 징수, 포탈죄 고발은 생략 사유이다.","c":"중","v":1},"관세사2019_36-21":{"w":"납세자권리헌장 문서를 내주어야 하는 경우는 관세범 조사, 관세조사(2번 결정·경정을 위한 방문·서면조사)(법 제110조 제2항), 징수권 확보를 위한 압류, 보세판매장 조사 등이다(영 제135조).\n납세담보 제공을 요구하는 경우는 열거돼 있지 않다. 5번이다.","c":"상","v":1},"관세사2019_36-28":{"w":"정기선정 사유는 관세청장이 신고 내용의 성실도를 분석한 결과 불성실 혐의가 있다고 인정하는 경우, 최근 4년 이상 조사를 받지 않은 납세자의 신고 적정성을 검증할 필요가 있는 경우, 무작위추출방식으로 표본조사를 하려는 경우이다(법 제110조의3 제1항). 5번이 정기선정이다.\n납세협력의무 불이행, 구체적인 탈세제보, 탈세·오류 혐의 자료, 금품 제공·알선은 정기선정 외에 조사할 수 있는 사유이다(같은 조 제2항).","c":"상","v":1},"관세사2020_37-26":{"w":"성실성 추정 배제 사유는 납세협력의무 불이행, 납세자에 대한 구체적인 탈세정보가 있는 경우, 신고내용에 탈루나 오류의 혐의를 인정할 만한 명백한 자료가 있는 경우, 신고내용이 관세청장이 정한 기준에 비추어 불성실한 경우이다(영 제138조 제1항).\n일반적인 탈세혐의가 제시된 것만으로는 배제 사유가 아니다. 4번이다.","c":"상","v":1},"관세사2020_37-30":{"w":"권리헌장 문서는 관세범 조사, 관세조사(세액 결정을 위한 방문조사 포함)를 할 때(법 제110조 제2항)와 압류, 보세판매장 조사를 할 때(영 제135조) 내준다.\n납세자를 긴급히 체포·압수·수색하거나 현행범인 납세자가 도주할 우려가 있는 등 조사목적을 달성할 수 없다고 인정되는 경우에는 내주지 않을 수 있다(법 제110조 제3항). 5번이다.","c":"상","v":1},"관세사2023_40-11":{"w":"본부세관 납세자보호위원회 위원에는 납세자보호담당관 1명과, 관세·법률·재정 분야 학식과 경험이 풍부한 사람 중 본부세관장(해당 세관장)이 성별을 고려해 위촉하는 사람이 들어간다(영 제144조의2 제2항 제1호). ㄱ 납세자보호담당관, ㄴ 해당 세관장으로 3번이다.\n위촉 위원 수는 출제 당시 17명 이내였고 현행은 32명 이내이며 일선세관장이 추천한 사람 중 본부세관장이 위촉하는 80명 이내 위원이 따로 있다.","c":"상","v":1},"관세사2025_42-17":{"w":"정기선정 외에 조사할 수 있는 경우는 납세협력의무 불이행, 수출입업자에 대한 구체적인 탈세제보, 탈세나 오류의 혐의를 인정할 만한 자료, 세관공무원에 대한 금품 제공·알선이다(법 제110조의3 제2항).\n과태료를 납부한 사실은 여기에 없다. 2번이다.","c":"상","v":1},"관세사2025_42-20":{"w":"과세전통지 생략 사유 중 제척기간 요건은 통지하려는 날부터 3개월 이내에 제척기간이 만료되는 경우이다(법 제118조 제1항 제1호). 2번은 3개월이 지난 후 만료되므로 생략할 수 없다.\n수입신고 수리 전 세액심사 결과 부족세액 징수(3번), 제97조 제3항에 따라 면제된 관세 징수(4번)는 법 제118조 제1항, 감사원 시정요구에 따른 징수(1번), 계산착오 등 명백한 오류로 부족한 세액 징수(5번)는 영 제142조에 열거된 생략 사유이다.","c":"상","v":1},"관세사2017_34-10":{"w":"신고서류 보관기간: 수입신고필증·수입거래 관련 계약서·수입물품 가격결정 자료는 5년, 수출신고필증·반송신고필증·반송물품 가격결정 자료는 3년, 보세운송 자료·보세화물 반출입 자료·적하목록 자료는 2년이다.\n가장 짧은 것은 2년인 보세운송에 관한 자료(5번)이다.","c":"상","v":1},"관세사2018_35-30":{"w":"수출입을 금지하는 지식재산권 등은 상표권, 저작권과 저작인접권, 「식물신품종 보호법」에 따른 품종보호권, 「농수산물 품질관리법」 등에 따른 지리적표시권 또는 지리적표시, 특허권, 디자인권이다(법 제235조 제1항, 현행은 방위산업기술도 포함). 실용신안권은 들어 있지 않다.\n품종보호권은 디자인보호법이 아니라 식물신품종 보호법에 따라 설정등록되므로 5번이 틀렸다.","c":"상","v":1},"관세사2019_36-04":{"w":"신고서류 보관기간은 수입물품 가격결정 자료 5년, 수출신고필증·반송신고필증 3년, 보세화물 반출입·적하목록 자료 2년이다.\n가장 긴 것은 5년인 수입물품 가격결정에 관한 자료(1번)이다.","c":"상","v":1},"관세사2019_36-32":{"w":"통관보류등을 요청하려는 자는 품명·수출입자 및 수출입국, 지식재산권등의 내용 및 범위, 요청사유, 침해사실을 입증하기 위하여 필요한 사항을 적은 신청서를 낸다(영 제238조).\n물품의 수량과 가격은 기재사항이 아니다. 1번이다.","c":"상","v":1},"관세사2020_37-29":{"w":"수출신고가 수리된 물품은 내국물품의 반입신고 방식에 따라 반입일시, 품명, 포장의 종류, 반입개수, 장치위치와 장치기간을 적는다(영 제176조 제1항 제2호).\n선하증권번호는 외국물품을 반입할 때 적는 사항이다(같은 항 제1호). 5번이다.","c":"상","v":1},"관세사2020_37-31":{"w":"지식재산권 보호대상은 특허권·디자인권·상표권·저작권과 저작인접권·품종보호권·지리적표시권 등이다.\n화폐·채권은 특허법상 권리가 아니므로 1번이 보호대상이 아니다.","c":"상","v":1},"관세사2020_37-32":{"w":"환급특례법 제23조 위반자 중 담보를 요구할 수 있는 사람은 징역형 실형의 집행이 끝나거나 면제된 후 2년 미경과자, 징역형 집행유예를 선고받고 유예기간 중에 있는 자, 벌금형·통고처분 이행 후 2년 미경과자이다.\n2번은 「유예기간이 종료된 후 2년」으로 적혀 있어 요건이 다르다. 4번 최근 2년간 조세 체납, 5번 최근 2년간 수입실적 없음은 담보 요구 대상이다.","c":"중","v":1},"관세사2020_37-33":{"w":"즉시반출신고를 한 날부터 10일 이내에 수입신고를 해야 하고, 기간 내 신고하지 않으면 관세의 100분의 20에 상당하는 금액을 가산세로 징수한다. 2번이다.","c":"상","v":1},"관세사2020_37-35":{"w":"신고를 생략하거나 간소한 방법으로 신고하게 할 수 있는 물품은 휴대품·탁송품·별송품, 우편물, 관세가 면제되는 물품, 입출항 보고·허가 대상 운송수단 등이다(법 제241조 제2항). 무세인 국제운송용 컨테이너는 신고 생략 물품이다(영 제246조 제4항).\n운송수단 가운데 우리나라에 수입할 목적으로 최초로 반입되는 것은 명시적으로 제외된다(법 제241조 제2항 제3호의2 가목). 3번이다.","c":"상","v":1},"관세사2022_39-25":{"w":"2개국 이상에 걸쳐 생산·가공된 물품의 원산지는 본질적 특성을 부여하기에 충분한 실질적 생산·제조·가공을 마친 나라이다.\n단순 조립, 가축 도축, 판매를 위한 포장개선, 보세구역 장치 중 보존작업은 실질적 변형으로 보지 않고, 혼합하여 본질적 특성을 부여한 5번만 인정된다.","c":"상","v":1},"관세사2022_39-26":{"w":"수입 신고기한 경과 시 가산세율은 20일 이내 1천분의 5, 50일 이내 1천분의 10, 80일 이내 1천분의 15, 80일 초과 1천분의 20이다.\n9일은 1천분의 5, 29일은 1천분의 10, 59일은 1천분의 15, 89일은 1천분의 20이다. 99일 1천분의 20(5번)만 맞다.","c":"상","v":1},"관세사2022_39-27":{"w":"신고수리 전 반출 때 담보 제공을 생략할 수 있는 물품은 국가·지방자치단체·공공기관·지방공사·지방공단이 수입하는 물품, 최근 2년간 법 위반 사실이 없는 수출입자 또는 신용평가기관으로부터 신용도가 높다고 평가받은 자로서 관세청장이 정하는 자가 수입하는 물품, 관세채권 확보에 지장이 없다고 관세청장이 인정하는 수출용원재료 등, 관세청장이 고시하는 기준에 해당하는 자의 이사물품이다(영 제256조 제3항).\n3번은 법 위반이 없는 기간을 1년으로 적어 틀렸다. 2년이 맞다.","c":"상","v":1},"관세사2023_40-03":{"w":"신고서류 보관기간은 수입신고필증 5년, 수입물품 가격결정 자료 5년, 수출신고필증·반송신고필증 3년, 보세운송 자료 2년이다.\n수입물품 가격결정에 관한 자료는 3년이 아니라 5년이므로 4번이 틀렸다.","c":"상","v":1},"관세사2023_40-21":{"w":"(2023 개정 전 기준) 수출입신고 대상 우편물은 수출입이 제한·금지되는 물품, 법 제226조에 따라 세관장 확인이 필요한 물품, 관세청장이 정한 기준에 해당하는 판매 목적 반입물품이나 대가를 지급하는 물품, 가공무역을 위해 무상으로 수출입하는 물품과 원·부자재 등이다(영 제261조). 출제 당시에는 대외무역법에 따른 수출입 승인을 받은 우편물도 신고 대상이어서 위탁판매수출용 무상 물품(1번)만 해당하지 않았다.\n현행 영 제261조에는 대외무역법 승인 우편물(3번)이 없으므로 지금 기준으로는 1번과 3번이 모두 신고 대상이 아니다.","c":"하","v":1,"old":1,"ow":"(2023 개정 전 기준) 수출입신고 대상 우편물은 수출입이 제한·금지되는 물품, 법 제226조에 따라 세관장 확인이 필요한 물품, 관세청장이 정한 기준에 해당하는 판매 목적 반입물품이나 대가를 지급하는 물품, 가공무역을 위해 무상으로 수출입하는 물품과 원·부자재 등이다(영 제261조). 출제 당시에는 대외무역법에 따른 수출입 승인을 받은 우편물도 신고 대상이어서 위탁판매수출용 무상 물품(1번)만 해당하지 않았다.\n현행 영 제261조에는 대외무역법 승인 우편물(3번)이 없으므로 지금 기준으로는 1번과 3번이 모두 신고 대상이 아니다."},"관세사2023_40-22":{"w":"6단위 품목번호 변경만으로 실질적 변형을 인정하기 곤란한 품목은 주요공정·부가가치 등을 고려해 품목별 원산지기준을 따로 정할 수 있다. 4번이다.","c":"중","v":1},"관세사2023_40-30":{"w":"안전관리기준 준수도 측정·평가 대상은 운영인, 관세 납세의무자, 화물관리인, 선박회사·항공사, 수출입·반송 신고인(화주 포함), 등록한 전자상거래업체등, 보세운송업자등, 자유무역지역 입주기업체이다(영 제259조의6 제1항).\n국가관세종합정보망 운영사업자는 대상에 없다. 5번이다.","c":"상","v":1},"관세사2024_41-10":{"w":"신고서류 보관기간은 수입거래 관련 계약서 5년, 수입물품 가격결정 자료 5년, 수출신고필증·반송신고필증 3년, 보세운송 자료 2년이다.\n수입거래 관련 계약서는 3년이 아니라 5년이므로 2번이 틀렸다.","c":"상","v":1},"관세사2024_41-22":{"w":"무역원활화 기본계획에는 정책의 기본 방향, 기반시설의 구축·운영, 환경조성, 국제협력에 관한 사항이 모두 들어간다. ㄱ~ㄹ 전부이므로 5번이다.","c":"중","v":1},"관세사2024_41-24":{"w":"(2025 개정 전 기준) 출제 당시 영 제258조 제1항은 관세청장이 전자상거래물품에 대해 따로 정할 수 있는 사항으로 특별통관 대상 거래물품 또는 업체, 수출입신고 방법·절차, 관세 등 납부방법, 물품검사방법 등을 열거했다. 물품검사장소는 없어서 1번이 정답이었다.\n2025.2.28 개정으로 특별통관 대상 거래물품·업체 항목이 삭제되고 지금은 수출입신고 방법·절차, 납부방법, 물품검사방법, 그 밖에 관세청장이 필요하다고 인정하는 사항만 남았다(영 제258조 제2항). 현행 기준으로는 4번과 5번도 명시돼 있지 않다.","c":"상","v":1,"old":1,"ow":"(2025 개정 전 기준) 출제 당시 영 제258조 제1항은 관세청장이 전자상거래물품에 대해 따로 정할 수 있는 사항으로 특별통관 대상 거래물품 또는 업체, 수출입신고 방법·절차, 관세 등 납부방법, 물품검사방법 등을 열거했다. 물품검사장소는 없어서 1번이 정답이었다.\n2025.2.28 개정으로 특별통관 대상 거래물품·업체 항목이 삭제되고 지금은 수출입신고 방법·절차, 납부방법, 물품검사방법, 그 밖에 관세청장이 필요하다고 인정하는 사항만 남았다(영 제258조 제2항). 현행 기준으로는 4번과 5번도 명시돼 있지 않다."},"관세사2024_41-25":{"w":"신고기한이 지난 날부터 20일 이내 신고하면 과세가격의 1천분의 5, 50일 이내 신고하면 1천분의 10이다(그 뒤 80일 이내 1천분의 15, 초과 시 1천분의 20).\nㄱ 20, ㄴ 10으로 1번이다.","c":"상","v":1},"관세사2025_42-23":{"w":"한국원산지정보원의 사업은 자유무역협정·원산지 관련 정보의 수집·분석·제공, 수출입물품의 원산지정보 관리를 위한 시스템의 구축·운영, 원산지인증수출자 인증·원산지검증 등의 지원, 교육·전문인력 양성, 위탁사업 등이다(법 제233조의2 제4항). 1번이다.\n관세범 조사·처분, 원산지증명서 발급, 예비 인증서 발급, 상대국 세관에 대한 진위 확인 요청은 정보원의 사업으로 열거돼 있지 않다. 인증 업무는 지원만 한다.","c":"상","v":1},"관세사2025_42-24":{"w":"준수도 측정·평가 결과는 통관 절차의 간소화, 검사 대상 수출입물품의 선별(영 제259조의6 제2항), 보세구역의 지정·특허, 보세구역 관리·감독, 보세운송업자등 관리·감독, 입주기업체 지원·관리, 과태료·과징금 산정, 행정제재 처분의 감경(규칙 제79조의3)에 활용할 수 있다.\n벌금의 감경은 열거돼 있지 않다. 5번이다.","c":"상","v":1},"관세사2025_42-25":{"w":"제240조의6에 따른 세관정보 교환 사유는 관세의 부과·징수, 과세 불복에 대한 심리, 수출입신고의 검증, 형사소추 등이다.\n자유무역협정의 체결은 열거된 사유가 아니다.","c":"중","v":1},"관세사2025_42-30":{"w":"수입신고 사항은 품명·규격·수량·가격(법 제241조 제1항), 포장, 목적지·원산지·선적지, 원산지표시 유무·방법·형태, 상표, 납세의무자 또는 화주의 상호·사업자등록번호·통관고유부호와 해외공급자부호, 물품의 장치장소(영 제246조 제1항), 통관이 일시적으로 제한·금지되는 물품인지 확인할 수 있는 공고 정보(규칙 제77조의6 제1항) 등이다.\n상호와 사업자등록번호는 납세의무자나 화주의 것을 적고 해외공급자는 해외공급자부호를 적는다. 3번이다.","c":"상","v":1},"관세사2026_43-25":{"w":"통관 보류·유치 요청 신청서에는 품명·수출입자 및 수출입국, 지식재산권의 내용 및 범위, 요청사유, 침해사실을 입증하기 위해 필요한 사항을 적는다.\n지식재산권을 사용할 수 있는 권리자는 기재사항이 아니다.","c":"중","v":1},"관세사2026_43-27":{"w":"관세법 시행령 제258조 제4항: 전자상거래물품 특별통관 등록증은 관세·국세 체납이 없을 것, 관세범으로 조사받거나 기소되어 있지 않을 것, 관세법 제175조 제4호·제5호·제7호에 해당하지 않을 것의 세 요건을 갖추면 발급한다.\n제175조 제4호는 징역형 실형 집행 후 2년이 지나지 않은 자, 제5호는 집행유예 기간 중인 자다. 파산선고를 받고 복권되지 않은 자는 제175조 제3호라 등록 요건에서 빠져 있어 등록증을 받을 수 있다.\n정답 ③.","c":"상","v":1},"관세사2026_43-29":{"w":"우편물의 신고 대상에는 의약품, 건강기능식품, 수출입 제한·금지 물품, 가공무역용 무상 수출입 물품과 원·부자재, 판매 목적 반입물품이 있다.\n판매 목적 반입물품은 관세청장이 정한 기준에 해당하는 것으로 한정하는데, 5번은 「한정하지 아니한다」로 적어 조문과 반대이다.","c":"중","v":1},"관세사2022_39-34":{"w":"적법하게 수입된 것으로 보아 관세를 따로 징수하지 않는 외국물품은 체신관서가 수취인에게 내준 우편물, 이 법에 따라 매각된 물품, 몰수된 물품(ㄱ), 제269조·제272조·제273조·제274조 제1항 제1호에 해당하여 통고처분으로 납부된 물품(ㅁ), 법령에 따라 국고에 귀속된 물품(ㄷ), 몰수를 갈음하여 추징된 물품이다(법 제240조 제1항).\n여행자가 운송수단에서 소비한 휴대품(ㄴ)은 열거돼 있지 않고 우편물은 체신관서가 수취인에게 내준 것만 해당하므로 보관 중인 우편물(ㄹ)도 아니다. 4번이다.","c":"상","v":1},"관세사2023_40-06":{"w":"공시송달은 세관공무원이 2회 이상 방문하되 처음 방문일과 마지막 방문일 사이가 3일(공휴일·토·일 제외) 이상이어야 하고, 수취인 부재로 납부기한까지 송달이 곤란한 경우에 할 수 있다. ㄱ 2, ㄴ 3으로 3번이다.","c":"상","v":1},"관세사2024_41-01":{"w":"수입물품에 세관장이 부과·징수하는 내국세는 부가가치세, 개별소비세, 주세, 교육세, 농어촌특별세, 교통·에너지·환경세 등이다. 소득세는 포함되지 않는다.","c":"상","v":1},"관세사2024_41-03":{"w":"보수작업으로 외국물품에 부가된 내국물품은 외국물품으로 본다.\n입항 전 수입신고가 수리된 물품, 수입신고 수리 전 반출승인을 받아 반출된 물품, 수입신고 전 즉시반출신고를 하고 반출된 물품, 우리나라 선박이 공해에서 포획한 수산물은 내국물품이다. 1번이다.","c":"상","v":1},"관세사2025_42-01":{"w":"관세법 시행령 제1조의3 제6항: 관세청장은 우리나라가 가입한 관세 조약의 해석에 의문이 있으면 재정경제부장관(시험 당시 명칭은 기획재정부장관)에게 의견을 첨부해 해석을 요청하고, 재정경제부장관은 필요하면 관련 국제기구에 질의할 수 있다.\nㄱ 관세청장, ㄴ 재정경제부장관, ㄷ 국제기구. 정답 ③.","c":"상","v":1},"관세사2026_43-04":{"w":"ㄱ O: 수입신고수리 전 반출승인을 받은 경우 그 승인일을 수입신고의 수리일로 본다(법 제8조 제1항).\nㄴ X: 기한이 공휴일·대체공휴일 등이면 그 다음 날을 기한으로 한다(같은 조 제3항).\nㄷ X: 국가관세종합정보시스템 장애로 신고할 수 없게 되면 장애가 복구된 날의 다음 날을 기한으로 한다(같은 조 제4항).\nㄹ O: 사업에 현저한 손실을 입은 경우는 천재지변 등에 준하는 사유로 1년을 넘지 않는 기간을 정해 기한을 연장할 수 있다(법 제10조, 영 제2조 제1항 제2호).\nㄱ, ㄹ이므로 2번이다.","c":"상","v":1},"관세사2026_43-05":{"w":"과세물건 확정시기: 우편 수입물품은 통관우체국에 도착한 때, 수입신고 전 즉시반출신고 물품은 즉시반출신고를 한 때, 도난·분실 물품은 도난·분실된 때, 보세운송기간 경과 물품은 보세운송 신고나 승인을 받은 때, 매각 물품은 매각된 때이다.\n2번만 맞다.","c":"상","v":1},"관세사2019_36-05":{"w":"가격신고를 생략할 수 있는 물품은 정부·지방자치단체 수입물품, 정부조달물품, 공공기관 수입물품, 관세·내국세등이 부과되지 않는 물품, 방위산업용 기계 등, 수출용 원재료, 특정연구기관 수입물품, 과세가격이 미화 1만불 이하인 물품 등이다(규칙 제2조 제1항).\n2번은 금액을 3만불로 적어 틀렸다.","c":"상","v":1},"관세사2019_36-35":{"w":"합리적 기준으로 과세가격을 정할 때 쓰면 안 되는 가격은 국내생산물품의 국내판매가격, 선택 가능한 가격 중 반드시 높은 가격을 택해야 한다는 기준으로 정한 가격, 수출국 국내판매가격, 제3국 수출가격, 최저과세기준가격, 자의적·가공적 가격이다.\n5번은 「반드시 낮은 가격」으로 적혀 있어 열거된 내용이 아니다.","c":"상","v":1},"관세사2020_37-06":{"w":"가격신고 생략 물품 중 금액 기준은 과세가격이 미화 1만불 이하인 물품이다(규칙 제2조 제1항 제8호). 1번 수출용 원재료, 2번 정부조달물품, 3번 관세·내국세등이 부과되지 않는 물품, 4번 특정연구기관 수입물품은 모두 열거돼 있다.\n5번은 2만불 미만·재정경제부장관이 정하는 물품으로 적어 조문과 다르다.","c":"상","v":1},"관세사2020_37-08":{"w":"잠정가격 신고 후 확정가격 신고는 2년의 범위에서 세관장이 지정한 기간 안에 해야 한다. 연장은 지정한 신고기간의 만료일부터 2년을 초과할 수 없다. 2번이다.","c":"상","v":1},"관세사2020_37-09":{"w":"우리나라에 수출하기 위하여 판매되는 물품에 포함되지 않는 물품은 무상 송부 물품, 수입 후 경매 등으로 판매가격이 정해지는 위탁판매물품, 수출자의 책임으로 국내에서 판매하기 위해 들여오는 물품, 독립된 법적 사업체가 아닌 지점 등과의 거래에 따른 물품, 임대차계약 물품, 무상 임차 물품, 수출자 부담으로 국내에서 폐기하는 산업쓰레기 등이다(영 제17조).\n열거된 것은 수출자의 책임으로 판매하는 물품이고 수입자의 책임으로 판매하는 물품(4번)은 없다.","c":"상","v":1},"관세사2022_39-06":{"w":"ㄱ 경매 등으로 판매가격이 정해지는 위탁판매물품, ㄴ 수출자 부담으로 국내에서 폐기하는 산업쓰레기, ㄷ 지점 등과의 거래에 따른 물품은 수출하기 위하여 판매되는 물품에서 제외된다(영 제17조).\nㄹ은 수입자의 책임으로 판매하는 물품이라 열거된 「수출자의 책임으로 국내에서 판매하기 위한 물품」과 다르다. ㄱ, ㄴ, ㄷ이므로 5번이다.","c":"상","v":1},"관세사2022_39-10":{"w":"잠정가격으로 신고한 자는 2년의 범위에서 세관장이 지정한 기간 안에 확정가격을 신고해야 하고, 신고기간이 끝나기 30일 전까지 확정가격 계산을 위한 가산율 산정을 요청할 수 있다. 2년, 30일로 5번이다.","c":"상","v":1},"관세사2025_42-05":{"w":"잠정가격 신고 사유는 거래관행상 가격이 나중에 정해지는 물품(1번), 법 제30조 제1항에 따른 조정금액이 나중에 정해질 수 있는 경우(3번), 과세가격 결정방법 사전심사를 신청한 경우, 특수관계자 거래가격이 정상가격으로 조정될 것으로 예상되는 경우 등이다(영 제16조 제1항). 이윤·일반경비 산출에 오랜 시간이 걸리는 경우(5번)와 설계·시공 일괄입찰 플랜트 등의 인도가 늦어지는 경우(4번)는 규칙 제3조의2 제3항에 있다.\n품목분류 사전심사 신청(2번)은 사유가 아니다. 사전심사 가운데 사유가 되는 것은 과세가격 결정방법 사전심사이다.","c":"상","v":1},"관세사2025_42-06":{"w":"권리사용료는 특정한 고안이나 창안이 구현된 수입물품을 이용해 우리나라에서 그것을 다른 물품에 재현하는 권리의 대가를 제외하고, 당해 물품에 관련되며 당해 물품의 거래조건으로 구매자가 직접 또는 간접으로 지급하는 금액이다. ㄱ 제외, ㄴ 관련, ㄷ 거래조건으로 4번이다.","c":"중","v":1},"관세사2025_42-07":{"w":"보세공장에서 내국물품과 외국물품을 혼용해 제조한 물품의 과세가격은 제품가격 × 외국물품가격 / (외국물품가격 + 내국물품가격)이다. 1번이다.","c":"상","v":1},"관세사2026_43-03":{"w":"특수관계 범위: 상호 임원·관리자, 법률상 동업자, 고용관계, 특정인이 양쪽의 의결권 있는 주식을 직접·간접으로 5퍼센트 이상 소유·관리하는 경우, 동일한 제3자의 지배를 받는 경우 등이다.\n주식 소유 기준은 3퍼센트가 아니라 5퍼센트이므로 2번이 해당하지 않는다.","c":"중","v":1},"관세사2026_43-08":{"w":"규칙 제2조 제2항은 가산 조정이 필요한 물품, 간접 지급액이 포함된 물품, 법 제31조부터 제35조까지에 따라 과세가격이 결정되는 물품, 법 제39조에 따라 세관장이 관세를 부과·징수하는 물품을 가격신고 생략물품에 해당하지 않는 것으로 정한다. 1번이다.\n수출용 원재료, 정부조달물품, 정부·지방자치단체 수입물품, 특정연구기관 수입물품은 같은 조 제1항의 생략 물품이다.","c":"상","v":1},"관세사2017_34-17":{"w":"화물이 국내에 도착한 후 최초로 보세구역에 반입된 날부터 30일이 지난 물품을 보세운송하려면 세관장의 승인이 필요하다. 5번이다.","c":"중","v":1},"관세사2019_36-22":{"w":"보세운송 승인 대상은 재보세운송 물품(ㄱ), 귀석·귀금속·한약재 등 부피가 작고 고가인 물품(ㄴ), 국내 도착 후 최초로 보세구역에 반입된 날부터 30일이 지난 물품, 화주나 화물에 대한 권리자가 직접 보세운송하는 물품(ㄹ), 불법 수출입 방지를 위해 세관장이 지정한 물품(ㅁ) 등이다(영 제226조 제3항).\nㄷ은 20일로 적어 해당하지 않는다. ㄱ, ㄴ, ㄹ, ㅁ이므로 4번이다.","c":"상","v":1},"관세사2020_37-22":{"w":"보세운송업자등의 등록은 폐업, 사망(법인은 해산), 등록 유효기간 만료, 등록 취소로 효력을 잃는다(법 제224조의2).\n휴업, 업무정지, 체납은 효력 상실 사유가 아니고 법인 대표자의 사망은 법인의 해산이 아니다. 3번이다.","c":"상","v":1},"관세사2022_39-23":{"w":"보세운송업자등이 관세법에 따른 명령을 위반하면 6개월의 범위에서 업무정지 등을 할 수 있고, 업무정지가 이용자에게 심한 불편을 주거나 공익을 해칠 우려가 있으면 해당 업무 유지에 따른 매출액의 100분의 3 이하 과징금을 부과할 수 있다. 1번이다.","c":"상","v":1},"관세사2023_40-24":{"w":"산정된 과징금은 4분의 1 범위에서 사업규모, 위반행위의 정도, 위반횟수 등을 고려해 가중·감경할 수 있고, 가중할 때 총액은 연간매출액의 100분의 3을 넘을 수 없다. ㄱ 4분의 1, ㄴ 연간매출액으로 3번이다.","c":"중","v":1},"관세사2023_40-26":{"w":"보세공장 업종에서 제외되는 것은 제73조에 따라 국내외 가격차에 상당하는 율로 양허한 농·임·축산물을 원재료로 하는 업종(ㄴ)과 국민보건·환경보전에 지장을 주거나 풍속을 해하는 물품을 제조·가공하는 업종으로 세관장이 인정하는 것(ㄹ)이다.\n외국원료만 쓰는 업종(ㄱ)과 원자재소요량 계산이 필요한 업종(ㄷ)은 제외 대상이 아니다. 2번이다.","c":"중","v":1},"관세사2023_40-28":{"w":"종합보세구역에서 수입통관 후 소비·사용해야 하는 물품은 제조·가공에 쓰는 시설기계류와 그 수리용 물품(ㄱ), 연료·윤활유·사무용품 등 제조·가공에 직접 쓰이지 않는 물품(ㄴ)이다.\n세관장 허가를 받고 내국물품만을 원료로 하는 경우의 원료·재료(ㄷ)는 수입통관 대상이 아니다. 3번이다.","c":"중","v":1},"관세사2024_41-13":{"w":"등록해야 하는 보세운송업자등은 보세운송업자, 화물운송주선업자, 국제무역선·기 등에 물품을 하역하는 자(1번), 선박용품·항공기용품·선내 판매물품 등을 공급하는 자(5번), 국제항 안 보세구역에서 물품이나 용역을 제공하는 자, 국제무역선 등을 이용해 상업서류·견본품을 송달하는 자(4번), 일정 규모 이상의 구매대행업자(2번) 등이다(법 제222조 제1항).\n국제항 안 보세구역에서 물품을 제조하는 업(3번)은 열거돼 있지 않다.","c":"상","v":1},"관세사2024_41-14":{"w":"등록은 폐업, 사망(법인은 해산), 유효기간 만료, 법 제224조 제1항에 따른 등록 취소로 효력을 잃는다(법 제224조의2).\nㄱ 법인 해산은 효력 상실 사유다. ㄴ 부정한 방법으로 한 등록과 ㄷ 집행유예 기간 중인 자(제175조 결격사유)의 등록은 반드시 취소해야 하고(법 제224조 제1항 제1호·제2호) 취소되면 효력을 잃는다. 5번이다.","c":"상","v":1},"관세사2026_43-23":{"w":"ㄱ O: 종합보세구역의 지정요건·지정절차 등은 대통령령으로 정한다(법 제197조 제3항).\nㄴ X: 종합보세구역은 관세청장이 지정하고(법 제197조 제1항) 직권으로 지정하려면 관세청장이 관계 중앙행정기관의 장 또는 지방자치단체의 장과 협의한다(영 제214조 제3항). 세관장이 아니다.\nㄷ O: 관세청장은 위치·규모 등을 고려해 판매하는 물품의 종류와 수량 등을 제한할 수 있다(영 제216조의3 제3항).\nㄹ O: 외국물품을 반입·반출하려면 세관장에게 신고한다(법 제199조 제1항).\nㄱ, ㄷ, ㄹ이므로 4번이다.","c":"상","v":1},"관세사2017_34-31":{"w":"분할납부 승인을 받은 뒤 관세 전액을 즉시 징수하는 사유는 용도 외 사용 또는 양도, 지정 기한까지 미납, 파산선고, 법인의 해산이다.\n법인이 분할한 경우는 즉시 징수 사유가 아니다.","c":"중","v":1},"관세사2017_34-37":{"w":"관세를 경감할 수 있는 해외임가공물품은 원재료·부분품을 수출해 제조·가공한 물품(ㄱ), 가공 목적으로 수출한 물품(ㄴ), 수리 목적으로 수출한 물품(ㅂ)이다.\nㄷ(재수출조건 매각 물품), ㄹ·ㅁ(환급받은 물품)은 경감 대상에서 제외된다. 2번이다.","c":"중","v":1},"관세사2017_34-40":{"w":"재수출면세기간은 증빙서류로 확인할 수 없는 기타 물품의 경우 당사자 간 합의가 아니라 세관장이 물품의 성질·용도·수입자·내용연수 등을 고려해 정하는 기간이다. 4번이 틀렸다.\n나머지 1(신변용품은 입국 후 처음 출국하는 날까지), 2(행사기간 종료일에 재수출 소요기일을 더한 기간), 3(가공·수리 소요기간), 5(압류기간은 불산입)는 맞다.","c":"중","v":1},"관세사2018_35-16":{"w":"관세 면제 소액물품은 기록문서(ㄱ), 우리나라 거주자에게 수여된 훈장·기장(ㄴ), 과세가격 미화 250달러 이하의 상용견품(ㄹ) 등이다.\n자가사용 소액물품(ㄷ)은 면제 한도가 미화 150달러 이하여서 200달러는 면제되지 않는다. 3번이다.","c":"중","v":1},"관세사2018_35-17":{"w":"수입신고가 수리된 개인 자가사용물품이 수입한 상태 그대로 수출되는 경우, 수입신고 수리일부터 6개월 이내에 세관장 확인을 받고 수출하면 납부한 관세를 환급한다. 4번이다.","c":"상","v":1},"관세사2018_35-18":{"w":"5년 이내 분할납부 승인 대상은 시설기계류 등, 정부·지방자치단체 수입물품(1번), 학교·직업훈련원 수입물품과 비영리법인이 공익사업을 위하여 수입하는 물품(3번 포함), 의료기관 등 사회복지기관·시설 수입물품(5번), 기업부설연구소 등 수입물품, 중소제조업체가 직접 사용하려고 수입하는 물품(4번)이다(법 제107조 제2항).\n공익사업용 물품은 비영리법인이 수입하는 경우만 해당하므로 영리법인으로 적은 2번이 열거돼 있지 않다.","c":"상","v":1},"관세사2018_35-19":{"w":"외교관용 물품 면세 대상은 대사·공사 등 외교관과 그 가족, 외국 영사관의 업무용품, 정부와 체결한 사업계약을 수행하는 외국계약자의 업무용품 등이다.\n명예총영사는 면세 대상에서 제외되어 3번이 해당하지 않는다.","c":"중","v":1},"관세사2018_35-20":{"w":"선박이 매매계약상 하자보수 보증기간 중 고장으로 외국의 매도인 부담으로 수리하는 부분은 면세되는 경우가 해외에서 발생한 고장일 때이다.\n4번은 국내에서 발생한 고장으로 적혀 있어 면세 대상이 아니다.","c":"중","v":1},"관세사2019_36-01":{"w":"관세환급금에 관한 권리를 양도하려는 자는 양도인의 주소와 성명, 양수인의 주소와 성명, 환급사유, 환급금액을 적은 문서를 세관장에게 낸다(영 제53조). ㄱ~ㄹ 모두 해당하여 5번이다.","c":"상","v":1},"관세사2019_36-11":{"w":"재수출면세물품 중 재정경제부령으로 정하는 물품이 기간 내 수출되지 않으면 500만원을 넘지 않는 범위에서 해당 물품에 부과될 관세의 100분의 20에 상당하는 금액을 가산세로 징수한다(법 제97조 제4항). 500만원, 가산세로 2번이다.","c":"상","v":1},"관세사2019_36-14":{"w":"특정물품 면세 대상에는 국립묘지 건설·유지·장식 자재와 안장자의 관·유골함·장례용 물품, 핵사고·방사능 긴급사태 복구지원·구호용 기증물품, 피상속인의 신변용품, 해외 사고 피해를 외국 보험회사나 가해자 부담으로 수리하는 부분 물품 등이 있다(법 제93조).\n동식물의 번식·양식·종자개량을 위한 물품은 재정경제부령으로 정하는 물품이 대상이다(법 제93조 제1호). 해양수산부장관이 정하는 물품으로 적은 3번은 조문과 다르다.","c":"상","v":1},"관세사2019_36-17":{"w":"제88조의 면세 대상은 외국 대사관·공사관·영사관 등의 업무용품, 대사·공사 등 사절과 그 가족의 물품, 국제기구나 외국 정부에서 파견된 고문관·기술단원의 물품이다.\n정부와 체결한 사업계약을 수행하는 외국계약자는 업무용품이 면세 대상이고, 외국계약자와 그 가족이 사용하는 물품까지 면세하는 규정은 없다. 4번이다.","c":"중","v":1},"관세사2020_37-11":{"w":"정부용품 면세 대상은 외국 주둔 국군·재외공관으로부터 반환된 공용품, 정부가 직접 수입하는 간행물·녹화 슬라이드, 지방자치단체가 수질측정 등을 위해 수입하는 물품, 국가정보원장이 인정한 안보 목적 물품이다.\n우리나라와 외국 간에 건설될 교량·해저통로 등의 건설 물품은 특정물품 면세 대상이어서 정부용품 목록에 없다. 4번이다.","c":"중","v":1},"관세사2020_37-12":{"w":"폐기물 처리용 기계는 학술연구용품 감면 조문이 아니라 환경오염방지물품 감면 조문(제95조)에 해당한다. 1번의 연결이 틀렸다.","c":"중","v":1},"관세사2020_37-14":{"w":"분할납부 승인 물품의 설치·사용장소를 바꾸려면 변경 전 관할지 세관장에게 변경신고서를 내고 제출일부터 1월 이내에 변경된 장소에 반입해야 한다. 긴급한 사유로 자기 소유의 국내 다른 장소로 바꿀 때는 관할지 세관장에게 신고하고 반입한 후 1월 이내에 신고서를 낸다. 1번이다.","c":"중","v":1},"관세사2020_37-15":{"w":"소액물품 등 면세 대상은 거주자에게 수여된 훈장, 기록문서와 서류, 상용견품·광고용품, 거주자가 받는 소액물품이다.\n박람회 참가자가 그 행사에 사용하려고 수입하는 물품은 이 목록에 없다. 2번이다.","c":"중","v":1},"관세사2022_39-09":{"w":"세관장은 환급 청구를 받으면 지체 없이 관세환급금으로 결정하고 30일 이내에 환급해야 한다. 3번이다.","c":"상","v":1},"관세사2022_39-14":{"w":"여행자의 별송품은 부득이한 사유가 없으면 여행자가 입국한 날부터 6개월 이내에 도착한 것이어야 면세된다. 2번이다.","c":"상","v":1},"관세사2022_39-15":{"w":"재수출면세 대상은 국제회의 등에서 쓰는 물품, 수출입물품의 검사·시험용 기계·기구, 수출입·반송·환적 물품 운송용 차량, 항공·해상화물운송용 파렛트 등이다.\n우리나라와 외국 간에 건설될 교량·통신시설 등의 건설에 필요한 물품은 특정물품 면세 대상이다. 5번이다.","c":"중","v":1},"관세사2023_40-16":{"w":"상품목록·가격표·교역안내서와 견본품으로 쓰일 물품(형상·성질·성능상 견본품, 천공 등으로 견본품 외 용도가 없는 물품)은 면세 대상이다. 상용견품은 과세가격 미화 250달러 이하여야 하므로 300달러인 2번은 면세 대상이 아니다.","c":"중","v":1},"관세사2023_40-20":{"w":"재수출감면 대상 물품은 법인세법 시행규칙상 내용연수가 5년(금형은 2년) 이상이고 개당 또는 세트당 관세액이 500만원 이상이어야 한다. 3번이다.","c":"중","v":1},"관세사2024_41-09":{"w":"(2025 개정 전 기준) 출제 당시 관세법 시행규칙 제9조의3의 환급가산금 이자율은 연 1천분의 29였다. 5번이다.\n그 뒤 개정돼 지금은 연 1천분의 31이어서 선지에 맞는 답이 없다.","c":"상","v":1,"old":1,"ow":"(2025 개정 전 기준) 출제 당시 관세법 시행규칙 제9조의3의 환급가산금 이자율은 연 1천분의 29였다. 5번이다.\n그 뒤 개정돼 지금은 연 1천분의 31이어서 선지에 맞는 답이 없다."},"관세사2024_41-11":{"w":"자가사용 소액물품의 면세 한도는 물품가격 미화 150달러 이하이므로 250달러인 4번은 면제 대상이 아니다.\n기록문서, 외국 정부 허가로 외국 영해에서 채집·포획한 수산물, 외국계약자의 업무용품, 6개월 이내 도착한 여행자 별송품은 면제 대상이다.","c":"중","v":1},"관세사2024_41-15":{"w":"재수출면세 물품이 기간 내에 수출되지 않으면 재정경제부령으로 정하는 물품에 대해 500만원을 넘지 않는 범위에서 관세의 100분의 20에 상당하는 금액을 가산세로 징수한다. ㄱ 재정경제부, ㄴ 500, ㄷ 20으로 4번이다.","c":"상","v":1},"관세사2025_42-15":{"w":"제88조 제1항 대상은 외국 공관의 업무용품, 대사와 그 가족의 물품, 국제기구나 외국 정부에서 파견된 고문관의 물품, 외국계약자가 계약조건에 따라 수입하는 업무용품이다.\n재외공관으로부터 반환된 공용품은 정부용품 등의 면세(제92조 제3호) 대상이다. 5번이다.","c":"상","v":1},"관세사2025_42-16":{"w":"관세법 시행령 제110조 제4호: 세율에 감면율을 곱한 율이 3퍼센트 이하이면 1년 이내, 3퍼센트 초과 7퍼센트 이하이면 2년 이내의 기간에서 관세청장이 고시하는 기간이 사후관리기간이다. ㄱ 3, ㄴ 1, ㄷ 7, ㄹ 2로 3번이다.","c":"상","v":1},"관세사2026_43-15":{"w":"관세법 제98조 제1항: 재수출기간이 6개월 이내면 관세액의 100분의 85, 6개월 초과 1년 이내면 100분의 70, 1년 초과 2년 이내면 100분의 55, 2년 초과 3년 이내면 100분의 40, 3년 초과 4년 이내면 100분의 30을 경감한다. 5번만 맞다.\n①은 85, ②는 70, ③은 55, ④는 40이어야 한다.","c":"상","v":1},"관세사2026_43-16":{"w":"관세법 시행령 제129조: 용도세율 적용, 관세 감면, 분할납부 승인을 받은 자는 그 물품을 수입신고 수리일부터 1개월 이내에 설치·사용 장소에 반입해야 한다(제1항). 설치장소 부족 등 부득이한 사유가 있으면 관세청장이 정하는 바에 따라 세관장에게 반입 기한 연장을 신청할 수 있고(제2항), 세관장은 수리일부터 3개월 범위에서 늘려 줄 수 있다(제3항).\nㄱ 수리일, ㄴ 1, ㄷ 관세청장. 정답 ①.","c":"상","v":1},"관세사2017_34-22":{"w":"FTA 관세특례법상 긴급관세 재심사 시 검토사항은 조치 변경이 필요한 상황의 발생 가능성(ㄱ), 조치 종료로 국내산업이 입을 피해 우려(ㄴ), 품목분류 변경 등 대상물품·적용 요건의 변동(ㄷ)이다.\n관세수입 증대 효과(ㄹ)는 검토사항이 아니다. 4번이다.","c":"중","v":1},"관세사2017_34-23":{"w":"원산지증빙서류 제출 요구를 할 수 있는 경우는 1천달러 이하 물품을 분할하는 등 부정한 방법으로 과세가격이 1천달러를 넘지 않게 하려는 때이다.\n1천달러 이하 물품, 원산지 변동이 없는 계속·반복 수입물품, 사전심사를 받은 물품, 원산지를 확인할 수 있는 물품은 제출 면제 대상이다. 2번이다.","c":"중","v":1},"관세사2017_34-25":{"w":"수입자가 보관하는 원산지증빙서류는 수입신고필증(ㄴ), 수입거래 관련 계약서(ㄷ), 지식재산권 거래 관련 계약서(ㄹ), 수입물품의 국제운송 관련 서류(ㅂ), 수입대금 지급 증빙 등이다.\n공정명세서(ㄱ), 원가계산서(ㅁ), 생산에 쓰인 원재료의 수입신고필증(ㅅ)은 수출자·생산자가 보관하는 서류이다. 2번이다.","c":"중","v":1},"관세사2017_34-26":{"w":"ㄱ X: 기재사항은 협정에서 달리 정하지 않으면 해당 물품의 수출자·품명·수량·원산지 등 재정경제부령으로 정하는 사항이다(시행령 제6조 제1항 제1호). 관세청장이 정하는 사항이 아니다.\nㄴ O: 영문으로 작성한다.\nㄷ O: 서명할 자가 지정돼 있고 그 사람이 서명해 발급한다.\nㄹ X: 유효기간은 협정에서 따로 정한 경우 말고는 발급일 또는 서명일부터 1년이다(시행령 제6조 제2항).\nㄴ, ㄷ이므로 3번이다.","c":"상","v":1},"관세사2018_35-37":{"w":"시행령 제6조 제2항: 미합중국과의 협정은 4년(현행 조문은 서명일부터 4년), 칠레와의 협정은 서명일부터 2년이다. 콜롬비아는 따로 정한 규정이 없어 원칙대로 1년이다. 긴 순서는 ㄴ-ㄱ-ㄷ로 3번이다.","c":"상","v":1},"관세사2018_35-38":{"w":"시행령 제28조 제3항: 잠정긴급관세조치 기간은 200일을 넘을 수 없고 칠레산은 120일, 페루산·인도네시아산은 180일이다. 칠레 120일인 4번이 맞다.\n튀르키예·캐나다·유럽연합당사자는 200일, 페루는 180일이다.","c":"상","v":1},"관세사2018_35-39":{"w":"FTA 관세특례법 시행령 제13조 제1항: 베트남은 조사 요청을 접수한 날의 다음 날부터 6개월이다. 조사 요청일부터 6개월이라고 한 1번이 틀렸다.\n튀르키예와 유럽연합당사자는 조사 요청일부터 10개월, 중국은 접수한 날부터 6개월, 페루는 접수한 날부터 150일이다.","c":"상","v":1},"관세사2018_35-40":{"w":"관세청장이 하는 중소기업 원산지증명 지원은 원산지결정기준·증빙서류 작성과 보관에 관한 상담과 교육, 원산지인증수출자 인증 취득 교육, 원산지증명 전산처리시스템 개발·보급 등이다.\n원산지증명서의 작성·발급 대행과 비용 지원은 열거돼 있지 않다.","c":"중","v":1},"관세사2019_36-16":{"w":"시행령 제6조 제2항: 캐나다 서명일부터 2년(ㄱ), 뉴질랜드 서명일부터 2년(ㅁ)은 맞다. 콜롬비아(ㄷ)는 따로 정한 규정이 없어 원칙대로 1년이므로 맞다.\n미합중국은 서명일부터 4년이어서 ㄴ은 틀렸고 칠레는 서명일부터 2년이어서 ㄹ도 틀렸다. ㄱ, ㄷ, ㅁ이므로 3번이다.","c":"상","v":1},"관세사2019_36-39":{"w":"시행령 제33조 제1항: 중국은 조사 시작 7일 전(ㄴ), 베트남은 15일 전(ㄷ), 호주는 조사 시작 전(ㅁ)이어서 맞다.\n인도는 조사 시작 10일 전(토요일·공휴일 제외)이어서 ㄱ이 틀렸고 튀르키예는 15일 전이어서 ㄹ이 틀렸다. 4번이다.","c":"상","v":1},"관세사2019_36-40":{"w":"베트남 협정의 완전생산 기준은 체약당사국에서 출생·사육된 살아있는 동물과 그로부터 얻은 물품, 재배·수확된 식물, 수렵·어로·양식으로 얻은 물품, 체약당사국에 등록되고 그 국기를 게양할 자격이 있는 선박이 영해 밖에서 잡은 어획물 등이다.\n편의치적선박이 잡은 어획물은 해당하지 않는다. 5번이다.","c":"중","v":1},"관세사2020_37-37":{"w":"시행령 제6조 제2항: 칠레·캐나다·뉴질랜드는 서명일부터 2년이고 콜롬비아는 원칙대로 1년이다.\n미합중국은 서명일부터 4년이므로 2년이라고 한 2번이 틀렸다.","c":"상","v":1},"관세사2020_37-39":{"w":"긴급관세조치 건의서에는 조사 신청과 결과보고에 관한 사항, 산업피해 유무의 판정내용과 이유, 건의내용과 이유가 들어간다. 긴급관세조치의 결정기한은 기재사항이 아니다.","c":"중","v":1},"관세사2020_37-40":{"w":"부가가치기준은 2개국 이상에 걸쳐 생산된 물품에 대해 협정에서 정한 일정 수준 이상의 부가가치를 창출한 국가를 원산지로 인정하는 기준이다. 「과반 수준」이라고 적은 2번이 옳지 않다.","c":"중","v":1},"관세사2022_39-35":{"w":"시행규칙 제8조: 미얀마 상무부(ㄴ), 일본 상공회의소(ㄷ, 역내포괄적경제동반자협정), 말레이시아 국제통상산업부(ㄹ), 필리핀 세관(ㅂ)이 맞다.\n브루나이산 물품은 브루나이 재정경제부(ㄱ), 인도산 물품은 인도수출검사위원회·섬유위원회·수산물수출개발원(ㅁ)이 발급한다. 4번이다.","c":"상","v":1},"관세사2022_39-36":{"w":"시행령 제13조 제1항: 영국은 조사 요청일부터 10개월이다. 2번이다.\n튀르키예는 조사 요청일부터 10개월(15개월은 유럽자유무역연합회원국), 인도는 접수한 날부터 3개월, 아세안회원국은 접수한 날부터 2개월, 콜롬비아는 조사 요청일부터 150일이다.","c":"상","v":1},"관세사2022_39-37":{"w":"시행령 제23조 제3항: 연장할 때 잠정긴급관세조치 기간을 포함한 총기간은 뉴질랜드산이 3년이다. 2번이다.\n중국·캐나다·영국·유럽연합당사자산은 4년이다.","c":"상","v":1},"관세사2022_39-38":{"w":"FTA 관세특례법 제38조의 비밀유지 의무를 위반하면 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. 3번이다.","c":"중","v":1},"관세사2022_39-39":{"w":"FTA 관세특례법 제30조 제1항 제1호와 같은 법 시행규칙 제30조 제1항: 중국과의 협정에 따라 일시수입 관세가 면제되는 물품은 제1호부터 제4호까지, 곧 일시 입국자의 영업·직업 수행에 필요한 전문장비, 전시·시연용 물품, 운동경기용 물품, 상용견품이다. 수리 또는 개조를 위한 물품(제6호)은 중국과의 협정 대상에 들어 있지 않다.\n정답 ①.","c":"상","v":1},"관세사2022_39-40":{"w":"업체별 원산지인증수출자 인증요건은 서면·현지조사 거부 사실 없음, 속임수 발급 사실 없음, 원산지 결정기준 충족을 증명할 능력, 원산지증명서 작성대장 비치와 원산지관리전담자 지정 등이다.\n수출입물품의 안전관리 운영시스템을 갖추는 것은 수출입안전관리우수업체 공인 요건이어서 4번이 해당하지 않는다.","c":"중","v":1},"관세사2023_40-35":{"w":"FTA 관세특례법 시행령 제23조 제2항: 긴급관세조치 적용기간(잠정긴급관세조치 기간 포함)의 상한은 캐나다·호주·인도·싱가포르가 2년이고, 아세안회원국은 3년이다.\n정답 ④.","c":"상","v":1},"관세사2023_40-36":{"w":"수입자가 보관하는 서류는 수입신고필증(ㄷ), 수입거래 관련 계약서, 지식재산권 거래 관련 계약서(ㄹ), 국제운송 관련 서류, 대금지급 증빙 등이다.\n원가계산서·원재료내역서·공정명세서(ㄱ)와 출납·재고관리 대장(ㄴ)은 수출자·생산자가 보관한다. 5번이다.","c":"중","v":1},"관세사2023_40-37":{"w":"다른 물품의 생산에 사용되는 원재료·구성물품·부분품·부속품을 「재료」라고 한다. 1번이다.","c":"상","v":1},"관세사2023_40-38":{"w":"시행령 제6조 제2항: 페루와의 협정은 서명일부터 1년이고 물품이 비당사국 관세당국 관할하에 일시 보관된 경우에는 2년이다. 이스라엘과의 협정은 발급일 또는 서명일부터 12개월이다.\n1, 2, 12로 3번이다.","c":"상","v":1},"관세사2023_40-39":{"w":"시행령 제13조 제1항: 콜롬비아는 조사 요청일부터 150일이다. 2번이다.\n유럽자유무역연합회원국은 조사 요청일부터 15개월, 중미 공화국들은 접수한 날의 다음 날부터 150일, 유럽연합당사자는 조사 요청일부터 10개월, 페루는 접수한 날부터 150일이다.","c":"상","v":1},"관세사2023_40-40":{"w":"캄보디아 협정과 역내포괄적경제동반협정(RCEP)에서 일시수입 면세 대상은 상용견품, 운동경기용 물품, 전시·시연용 물품, 일시 입국자의 전문장비 등이다.\n수리 또는 개조를 위한 물품은 면세 목록에서 제외돼 있다. 4번이다.","c":"중","v":1},"관세사2024_41-21":{"w":"생산자와 수출자에게 공통으로 제출을 요구할 수 있는 확인자료는 원가계산서·원재료내역서·공정명세서, 출납·재고관리대장, 원산지증명서 발급 신청서류, 생산 또는 구입 관련 증명 서류이다.\n수출신고필증은 수출자 쪽 서류여서 공통 자료가 아니다. 2번이다.","c":"중","v":1},"관세사2024_41-35":{"w":"관세청장이 체약상대국 관세당국과 협력하는 사항은 통관절차 간소화, 세관기술 지원, 원산지 조사 정보 교환, 전자무역환경 증진 등 통관절차 개선이다.\n원산지인증수출자와 물류종사자 교육·훈련은 열거돼 있지 않다. 4번이다.","c":"중","v":1},"관세사2024_41-36":{"w":"시행령 제13조 제1항: 중미 공화국들은 조사 요청을 접수한 날의 다음 날부터 150일이다. 5번이다.\n캄보디아와 역내경제협정당사국은 접수한 날부터 90일, 이스라엘은 조사 요청일부터 10개월, 인도네시아는 접수한 날부터 2개월이다.","c":"상","v":1},"관세사2024_41-37":{"w":"시행규칙 제8조: 호주산 물품의 발급기관에 Trade Window Origin Pty Limited가 들어 있다. 2번이다.\n스위스치즈는 스위스연방농업국이 인증한 기관, 베트남산은 베트남 산업무역부, 캄보디아산은 캄보디아 상무부, 이스라엘산은 재무부 이스라엘조세당국 관세국이 발급한다. International Export Certification Services는 호주산 물품 발급기관이다.","c":"상","v":1},"관세사2024_41-38":{"w":"시행령 제6조 제2항: 캄보디아와의 협정은 따로 정한 규정이 없어 원칙대로 발급일 또는 서명일부터 1년이다. 3번이다.\n뉴질랜드는 서명일부터 2년, 미합중국은 서명일부터 4년, 호주는 발급일 또는 서명일부터 2년, 역내경제협정당사국은 원칙대로 1년이다.","c":"상","v":1},"관세사2024_41-39":{"w":"보관자별 서류: 수입자는 수입신고필증·수입거래 관련 계약서·지식재산권 거래 관련 계약서·운송 서류 등을 보관하고, 수출자는 해당 물품의 구입 관련 증빙서류와 출납·재고관리대장을 보관한다.\n원가계산서·원재료내역서·공정명세서와 생산·구입 증빙서류는 생산자가 보관한다. 3번이다.","c":"중","v":1},"관세사2024_41-40":{"w":"FTA 관세특례법 제44조 제2항 제1호: 원산지증빙서류를 속임수 등 부정한 방법으로 신청해 발급받았거나 작성·발급한 자는 2천만원 이하의 벌금에 처한다. 2번이다.\n비밀유지의무 위반은 3년 이하 징역 또는 3천만원 이하 벌금(1번), 정당한 사유 없는 서류 미보관과 사전심사 자료 거짓 제출은 2천만원 이하 벌금(3번, 4번), 과실로 원산지증빙서류를 사실과 다르게 발급받거나 작성·발급한 자는 300만원 이하 벌금(5번)이다.","c":"상","v":1},"관세사2025_42-35":{"w":"FTA 관세특례법 제36조 제1항 제1호: 가산세는 부족세액의 100분의 10이고 원산지증명서 위조·변조 등 부정한 행위로 협정관세 적용을 신청해 부족세액이 생겼으면 100분의 60이다. ㄱ 10, ㄴ 60으로 3번이다.","c":"상","v":1},"관세사2025_42-36":{"w":"공장도거래가격은 물품을 생산공장에서 반출할 때 생산자에게 실제로 지급하였거나 지급하여야 하는 가격에서 수출될 때 환급되는 내국세를 공제한 가격이다. 3번이다.","c":"상","v":1},"관세사2025_42-39":{"w":"유럽자유무역연합(EFTA) 회원국은 아이슬란드, 리히텐슈타인, 노르웨이, 스위스이다. 선지 중 리히텐슈타인공국(5번)이 해당한다.","c":"상","v":1},"관세사2025_42-40":{"w":"사전심사를 신청할 수 있는 사항은 물품과 재료의 원산지, 품목분류·가격·원가결정, 관세의 환급·감면, 원산지 표시 등이다.\n세관장확인대상물품 여부는 신청 사항에 열거돼 있지 않다. 3번이다.","c":"중","v":1},"관세사2026_43-36":{"w":"시행령 제13조 제1항: 튀르키예는 조사 요청일부터 10개월이다. 1번이다.\n베트남은 접수한 날의 다음 날부터 6개월, 영국은 조사 요청일부터 10개월, 유럽자유무역연합회원국은 조사 요청일부터 15개월, 필리핀은 접수한 날부터 3개월이다.","c":"상","v":1},"관세사2026_43-37":{"w":"무역위원회가 긴급관세조치를 건의할 때 첨부하는 서류에는 조사의 신청, 조사 결과보고, 산업피해 유무의 판정내용과 이유, 건의내용과 이유가 모두 들어간다. 5번이다.","c":"중","v":1},"관세사2026_43-38":{"w":"시행령 제33조 제1항: 호주는 조사를 시작하기 전에 통보한다. 1번이다.\n튀르키예·필리핀·유럽연합당사자는 조사 시작 15일 전, 중국과 역내경제협정당사국은 7일 전이다.","c":"상","v":1},"관세사2026_43-39":{"w":"FTA 관세특례법 시행령 제23조 제2항: 긴급관세조치 적용기간(잠정긴급관세조치 기간 포함)의 상한은 유럽자유무역연합회원국 1년, 아세안회원국 3년, 인도 2년, 중국 2년, 베트남 2년이다.\n정답 ①.","c":"상","v":1},"관세사2026_43-40":{"w":"FTA 관세특례법 제32조 제1항: 사전심사서의 근거가 되는 사실관계나 상황이 바뀌는 등의 사유가 있으면 사전심사서 내용을 변경하는 주체는 관세청장이다. 세관장이라고 한 3번이 옳지 않다.\n1번은 제29조, 2번은 제30조 제1항 제3호, 4번은 제31조 제2항 단서, 5번은 제37조 제4항 그대로다.","c":"상","v":1},"관세사2017_34-28":{"w":"세관설비 사용료 중 토지는 분기마다 1제곱미터당 780원이다. 1번이다.","c":"중","v":1},"관세사2017_34-29":{"w":"과세자료 비밀유지의무를 위반해 과세자료를 제공·누설하거나 목적 외로 사용한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 3번이다.","c":"중","v":1},"관세사2018_35-32":{"w":"과세자료제출기관에는 지방자치단체와 그 업무를 위탁받은 기관, 지방자치단체조합, 지방공사·공단, 신용카드업자, 지방자치단체의 보조를 받는 단체 등이 모두 들어간다. ㄱ~ㅁ 전부이므로 5번이다.","c":"중","v":1},"관세사2018_35-34":{"w":"관세법 제272조: 밀수출입죄에 전용되는 선박은 소유자가 정황을 알고 범죄물품을 적재하거나 적재하려 한 경우, 정지명령을 받고도 정지하지 않거나 범죄물품을 해상에서 투기·파괴·훼손한 경우, 범죄물품을 해상에서 인수·취득하거나 하려 한 경우, 범죄물품을 운반한 경우에 몰수한다.\n범죄물품을 운반할 수 있는 선박을 매입하려는 경우는 몰수 사유가 아니다. 3번이다.","c":"상","v":1},"관세사2018_35-35":{"w":"(2020 개정 전 기준) 출제 당시 관세법 시행령 제270조의2는 벌금에 상당하는 금액을 해당 벌금 최고액의 100분의 20으로 하고 조사 방해·증거 은닉 등이 있으면 그 금액의 100분의 50 범위에서 늘릴 수 있게 했다. 그래서 정답은 2번이었다.\n2020. 2. 11. 개정으로 기준 금액이 벌금 최고액의 100분의 30이 돼 지금은 맞는 선지가 없다.","c":"상","v":1,"old":1,"ow":"(2020 개정 전 기준) 출제 당시 관세법 시행령 제270조의2는 벌금에 상당하는 금액을 해당 벌금 최고액의 100분의 20으로 하고 조사 방해·증거 은닉 등이 있으면 그 금액의 100분의 50 범위에서 늘릴 수 있게 했다. 그래서 정답은 2번이었다.\n2020. 2. 11. 개정으로 기준 금액이 벌금 최고액의 100분의 30이 돼 지금은 맞는 선지가 없다."},"관세사2019_36-25":{"w":"자료 비치 의무가 있는 상설영업장은 백화점, 최근 1년간 수입물품 매출액 5억원 이상인 수입물품 전문·할인판매 영업장, 통신판매자로서 최근 1년간 수입물품 매출액 10억원 이상인 영업장, 수입물품 매출이 전체의 30퍼센트를 초과하는 영업장, 최근 3년 이내 관세법 위반 처벌 전력이 있는 영업장이다.\n3번은 최근 2년간 5억원으로 적혀 있어 기준이 맞지 않는다.","c":"중","v":1},"관세사2019_36-27":{"w":"관세법 제275조: 제269조부터 제271조까지(밀수출입·관세포탈·가격조작·미수와 교사·방조) 및 제274조(밀수품 취득)의 죄는 징역과 벌금을 병과할 수 있다. 과세자료 비밀유지의무 위반도 제264조의9 제2항으로 병과할 수 있다.\n1번은 제269조 제1항, 2번은 제270조, 4번은 제270조의2, 5번은 제264조의9에 해당해 병과할 수 있다. 3번 강제징수(옛 체납처분) 면탈죄(제275조의2)는 병과 규정이 없다.","c":"상","v":1},"관세사2019_36-30":{"w":"관세법 시행령 별표 3: 외교부가 내는 여권법 제7조 제1항의 여권발급 자료는 실시간 제출 대상이다. 4번이다.\n출입국심사 자료, 자동차 등록 자료, 지방세법 제55조 반출신고 자료, 사업자등록 자료는 매일 제출한다.","c":"상","v":1},"관세사2020_37-21":{"w":"과세자료제출기관은 중앙관서와 그 업무를 위탁받은 기관, 지방자치단체조합, 지방공사·공단, 여신전문금융업협회 등이다.\n민법에 따라 설립되었더라도 국가 또는 지방자치단체의 지원을 받지 않는 단체는 해당하지 않는다. 4번이다.","c":"중","v":1},"관세사2020_37-24":{"w":"과세자료 비밀유지의무를 위반한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 과세자료제출기관의 장은 추가·보완 요구를 받으면 정당한 사유가 없는 한 요구받은 날부터 15일 이내에 따라야 한다. ㄱ 3, ㄴ 1, ㄷ 15로 4번이다.","c":"중","v":1},"관세사2020_37-28":{"w":"관세법 제275조는 제269조부터 제271조까지와 제274조의 죄에 징역과 벌금을 병과할 수 있게 한다. 미수범을 처벌하는 제271조 제2항은 제268조의2·제269조·제270조의 미수범만 정하고 가격조작죄(제270조의2)의 미수범은 정하지 않는다. 1번이다.\n밀수출입죄 미수범(2번), 밀수품 취득죄(3번), 밀수출입죄 교사(4번), 관세포탈죄 방조(5번)는 병과할 수 있다.","c":"상","v":1},"관세사2022_39-29":{"w":"자료 비치 의무 영업장: 매출액 기준은 수입물품 전문 영업장 1년 5억원 이상, 통신판매자 1년 10억원 이상, 백화점이며, 수입물품 매출이 전체 매출의 30퍼센트를 초과하는 영업장도 대상이다.\n4번은 20퍼센트이므로 대상이 아니다.","c":"중","v":1},"관세사2022_39-31":{"w":"관세법 시행령 별표 3: 핵사고 또는 방사능 긴급사태 복구지원·구호 기증물품의 관세 면제 신청 자료는 원자력안전위원회가 제출한다. 산업통상자원부라고 한 3번이 틀렸다.\n양허세율 적용 추천 자료는 농림축산식품부, 상수도 수질 측정 물품 면제 신청 자료는 환경부(현재 기후에너지환경부), 군수품무역대리업 등록업체 사업자등록번호는 방위사업청, 지방세법 제55조 반출신고 자료는 행정안전부가 낸다.","c":"상","v":1},"관세사2022_39-33":{"w":"개청시간 외 통관절차 등 수수료는 기본수수료 4천원(휴일 1만2천원)에 시간당 금액을 더한다. 오후 6시부터 10시까지는 시간당 4천8백원이다. 4번이다.","c":"중","v":1},"관세사2023_40-31":{"w":"가격조작죄는 2년 이하의 징역 또는 물품원가와 5천만원 중 높은 금액 이하의 벌금에 처한다. 5번이다.","c":"중","v":1},"관세사2023_40-34":{"w":"은닉재산 신고 포상금은 5억원 초과 20억원 이하 구간이 1억원 + 5억원 초과분의 100분의 15이고, 20억원 초과 30억원 이하 구간이 3억2천5백만원 + 20억원 초과분의 100분의 10이다.\n검산: 1억원 + 15억원 × 15% = 3억2천5백만원으로 구간이 이어진다. ㄱ 15, ㄴ 10으로 4번이다.","c":"상","v":1},"관세사2024_41-27":{"w":"신고를 하였으나 수입물품과 다른 물품으로 신고하여 수입한 자는 5년 이하의 징역 또는 관세액의 10배와 물품원가 중 높은 금액 이하 벌금에 처한다. 신고 없이 물품을 수출하거나 반송한 자는 3년 이하의 징역 또는 물품원가 이하 벌금이다. ㄱ 5, ㄴ 10, ㄷ 3으로 5번이다.","c":"중","v":1},"관세사2024_41-28":{"w":"관세법 시행령 제263조의3: 관세청장이 마약류등 관련 정보를 요구할 수 있는 기관의 장은 과학기술정보통신부장관, 외교부장관, 법무부장관, 검찰총장, 국방부장관, 식품의약품안전처장이다. 경찰청장은 없다. 2번이다.","c":"상","v":1},"관세사2024_41-29":{"w":"관세법 시행령 제269조: 검증·수색·압수조서에는 물품의 품명·수량, 포장의 종류·기호·번호·개수, 검증·수색·압수의 장소·일시, 소유자 또는 소지자의 주소 또는 거소와 성명, 보관장소를 적는다.\n조사를 한 사람과 참여자의 주소·성명은 기재사항이 아니다. 4번이다.","c":"상","v":1},"관세사2025_42-22":{"w":"관세법 제270조 제1항 제1호는 과세가격·관세율 등을 거짓으로 신고한 수입신고인에 구매대행업자를 포함한다고 정한다. 구매대행업자를 제외한다고 한 2번이 옳지 않다.\n1번은 제270조 제1항 제3호, 3번은 같은 조 제3항, 4번은 제4항, 5번은 제5항으로 처벌된다.","c":"상","v":1},"관세사2025_42-27":{"w":"ㄱ 전산처리설비의 전자문서 정보 변조(제268조의2 제1항): 1년 이상 10년 이하 징역 또는 1억원 이하 벌금.\nㄷ 관세율 거짓신고 수입(제270조 제1항 제1호): 3년 이하 징역 또는 포탈세액 5배와 물품원가 중 높은 금액 이하 벌금.\nㄹ 입항보고 거짓(제276조 제4항 제2호): 1천만원 이하 벌금.\nㄴ 과실로 세관장의 의무 이행 요구 불이행(제276조 제3항 제4호·단서): 300만원 이하 벌금.\nㄱ-ㄷ-ㄹ-ㄴ으로 3번이다.","c":"상","v":1},"관세사2025_42-28":{"w":"관세법 제330조: 한국원산지정보원 업무 종사자와 관세체납정리위원회·관세정보위원회·납세자보호위원회 등의 공무원 아닌 위원은 벌칙 적용에서 공무원으로 본다.\n관세포상심사위원회 위원은 열거돼 있지 않다. 5번이다.","c":"상","v":1},"관세사2026_43-30":{"w":"관세법 제271조: 교사·방조는 제269조(밀수출입죄)와 제270조(관세포탈죄 등)에 대해 정범에 준해 처벌한다. 미수와 예비는 제268조의2(전자문서 위조·변조죄), 제269조, 제270조에 대해 처벌한다.\n넷을 모두 처벌하는 것은 밀수출입죄와 관세포탈죄다. 2번이다.","c":"상","v":1},"관세사2026_43-31":{"w":"부정한 방법으로 적재화물목록을 작성하거나 제출한 자는 2천만원 이하 벌금 대상이다(제276조 제3항 제1호). 2번이다.\n세관공무원 질문에 대한 거짓 진술(1번), 세관장 명령에 대한 거짓 보고(3번), 물품 제시 요구 거부(5번)는 제277조 제3항의 5천만원 이하 과태료, 종합보세구역 반입 제한 조치를 과실로 위반한 경우(4번)는 같은 항 단서의 400만원 이하 과태료 대상이다.","c":"상","v":1},"관세사2026_43-33":{"w":"통고처분 벌금 상당액은 벌금 최고액의 100분의 30이고, 별표 4 범죄로서 물품원가가 벌금 최고액 이하이면 물품원가의 100분의 30이다. 부족세액 자진납부·심신미약·자수 등이 있으면 그 금액의 100분의 50 범위에서 줄일 수 있다. ㄱ 30, ㄴ 30, ㄷ 50으로 2번이다.","c":"중","v":1},"관세사2026_43-34":{"w":"관세법 제328조: 청문 대상은 지정보세구역 지정 취소, 종합보세기능 수행 중지, 보세운송업자등의 등록 취소·업무정지, 전자문서중계사업자 지정 취소와 사업·업무의 전부 또는 일부 정지 등이다. 수출입안전관리우수업체는 공인 취소만 청문 대상이다.\n혜택의 전부 정지는 청문 대상이 아니다. 5번이다.","c":"상","v":1},"관세사2017_34-33":{"w":"조정관세 부과 사유: 산업구조 변동 등으로 세율 불균형이 심한 경우(ㄱ), 공중도덕·국민보건·환경보전 등을 위해 필요한 경우(ㄴ), 국내 개발물품 보호(ㄹ), 농림축수산물 등 국제경쟁력 취약 물품의 수입증가로 국내시장이 교란될 우려(ㅂ)이다.\n수입 촉진(ㄷ)과 국내가격 안정(ㅁ)은 할당관세 사유이다. 3번이다.","c":"중","v":1},"관세사2017_34-38":{"w":"덤핑방지관세액은 정상가격과 덤핑가격의 차액(덤핑차액)을 초과할 수 없다. 280 − 180 = 100원이므로 최대 덤핑방지관세액은 100원이다. 4번이다.","c":"하","v":1},"관세사2018_35-11":{"w":"무역위원회는 예비조사 결과를 제출한 날의 다음날부터 본조사를 개시하고, 본조사 개시일부터 3월 이내에 본조사 결과를 제출한다. 5번이다.","c":"중","v":1},"관세사2018_35-12":{"w":"관세법 시행령 제91조 제1항: 조정관세 부과를 요청할 때 내는 자료에는 해당 연도와 그 전후 1년간의 수급실적 및 계획(ㄱ), 제조용 투입원료와 관련제품의 제조공정설명서 및 용도(ㄹ)가 들어 있다.\n수입가격·수입실적과 공장도가격·출고실적 자료는 최근 1년간의 월별 자료여서 최근 2년간 분기별이라고 한 ㄴ, ㄷ은 틀렸다. 2번이다.","c":"상","v":1},"관세사2018_35-14":{"w":"관세법 제81조 제1항 제1호: 여행자나 외국을 오가는 운송수단의 승무원이 휴대해 수입하는 물품은 간이세율을 적용할 수 있고 개별소비세가 과세되는 고급 시계도 시행령 별표 2에 세율이 정해져 있다. 5번이다.\n무세·감면 물품, 수출용원재료, 종량세 물품, 상업용 수량의 물품은 시행령 제96조 제2항에 따라 간이세율을 적용하지 않는다.","c":"상","v":1},"관세사2018_35-15":{"w":"관세법 시행령 제95조 제1항의 편익관세 적용 국가에 바티칸(유럽)이 들어 있다. 1번이다.\n아랍에미리트, 에콰도르, 코스타리카, 태국은 표에 없다.","c":"상","v":1},"관세사2019_36-10":{"w":"보복관세(제64조), 조정관세(제70조), 편익관세(제74조)는 대통령령으로 정한다. 긴급관세(제65조 제6항)와 계절관세(제72조)는 재정경제부령으로 정한다. ㄱ, ㄷ, ㄹ이므로 4번이다.","c":"상","v":1},"관세사2019_36-18":{"w":"조정관세 부과 대상은 세율 불균형 시정, 공중도덕·생명·건강·환경 등을 위한 경우, 국내 개발물품 보호, 농림축수산물 시장교란 방지이다.\n특정물품의 수입을 촉진할 필요가 있는 경우는 할당관세 사유이다. 5번이다.","c":"중","v":1},"관세사2020_37-17":{"w":"할당관세 부과 대상은 수입가격이 급등한 물품의 국내가격 안정, 원활한 물자수급, 산업 경쟁력 강화를 위한 수입 촉진, 유사물품 간 세율 불균형 시정이다.\n인간·동물·식물의 생명 및 건강 보호 등은 조정관세 사유이다. 2번이다.","c":"중","v":1},"관세사2020_37-18":{"w":"(2026 개정 전 기준) 출제 당시 시행령 제95조의 편익관세 적용 국가에는 코모로·나우루·바티칸·모나코가 있었고 라오스는 없었다. 그래서 정답은 3번이었다.\n현행 표에는 코모로가 빠져 있어 1번도 해당하지 않는다.","c":"상","v":1,"old":1,"ow":"(2026 개정 전 기준) 출제 당시 시행령 제95조의 편익관세 적용 국가에는 코모로·나우루·바티칸·모나코가 있었고 라오스는 없었다. 그래서 정답은 3번이었다.\n현행 표에는 코모로가 빠져 있어 1번도 해당하지 않는다."},"관세사2022_39-11":{"w":"간이세율 적용 제외 물품은 종량세 물품, 수입신고 대상 우편물, 관세 감면 물품, 고가품 등이다. 탁송품은 간이세율을 적용할 수 있다. 1번이다.","c":"중","v":1},"관세사2022_39-12":{"w":"(2024 개정 전 기준) 출제 당시 시행령 제107조는 관계법령 개정에 따른 품목분류 변경, 동일·유사 물품 간 서로 다른 품목분류, 신청인의 허위자료로 인한 중대한 착오, 관세협력이사회 권고 등을 변경 사유로 정했다. 불복·소송 진행으로 재심사 신청이 반려된 경우는 없어 4번이 정답이었다.\n2024. 2. 29. 개정으로 관계법령 개정 사유가 삭제돼 지금은 1번도 변경 사유가 아니다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 출제 당시 시행령 제107조는 관계법령 개정에 따른 품목분류 변경, 동일·유사 물품 간 서로 다른 품목분류, 신청인의 허위자료로 인한 중대한 착오, 관세협력이사회 권고 등을 변경 사유로 정했다. 불복·소송 진행으로 재심사 신청이 반려된 경우는 없어 4번이 정답이었다.\n2024. 2. 29. 개정으로 관계법령 개정 사유가 삭제돼 지금은 1번도 변경 사유가 아니다."},"관세사2022_39-13":{"w":"실질적 피해 판정 시 검토사항은 덤핑물품의 가격과 수입물량, 덤핑차액의 정도, 국내산업의 가동률·재고 등이다. 덤핑방지관세 부과에 따른 보상 수준은 검토사항이 아니다. 2번이다.","c":"중","v":1},"관세사2023_40-13":{"w":"관세법 시행령 별표 2: 기본관세율 10퍼센트 이상이고 개별소비세가 과세되지 않는 물품 중 모피의류는 19퍼센트, 신발류는 18퍼센트, 녹용은 21퍼센트다. ㄱ, ㄴ, ㄷ 모두 맞아 5번이다.","c":"상","v":1},"관세사2023_40-14":{"w":"관세법 시행령 제95조 제1항의 표에서 중동 지역 편익관세 국가는 이란·이라크·레바논·시리아다. 2번이다.\n아시아는 부탄, 대양주는 나우루, 아프리카는 에티오피아·소말리아, 유럽은 안도라·모나코·산마리노·바티칸·덴마크(그린란드·페로제도)만 있어 네팔·뉴질랜드·가나·리히텐슈타인은 해당하지 않는다.","c":"상","v":1},"관세사2023_40-18":{"w":"ㄱ O: 긴급관세 부과나 수입수량제한 조치 여부를 결정하면 잠정긴급관세 부과를 중단한다.\nㄴ X: 긴급관세는 부과조치 결정 시행일 이전에 수입된 물품에 소급해 적용하지 않는다.\nㄷ X: 재심사 결과로 부과내용을 바꾸더라도 최초 조치내용보다 강화할 수 없다.\nㄱ만 옳아 1번이다.","c":"중","v":1},"관세사2024_41-32":{"w":"관세품목분류위원회 위원의 해임·해촉 사유는 심신장애로 직무를 수행할 수 없는 경우, 직무 관련 비위, 직무태만·품위손상 등으로 부적합한 경우, 스스로 직무 수행이 곤란하다고 밝힌 경우이다.\n해당 안건 당사자의 대리인이어서 심의·의결에서 회피한 경우는 해임 사유가 아니다. 5번이다.","c":"중","v":1},"관세사2024_41-33":{"w":"관세법 시행령 제93조 제1항: 계절관세 부과를 요청할 때 내는 자료는 품명·규격·용도·대체물품, 최근 1년간 월별 수입가격과 주요 국제상품시장 가격동향, 최근 1년간 월별 주요 국내제조업체별 공장도가격, 생산자·소비자·수입물가지수, 적용 이유와 기간, 계절별 수급실적과 전망, 변경하려는 세율과 산출내역이다.\n동종·유사·대체물품별 국내외 가격동향은 열거돼 있지 않다. 4번이다.","c":"상","v":1},"관세사2024_41-34":{"w":"여행자 휴대품이라도 간이세율을 적용하지 않는 물품은 수출용원재료(ㄴ)와 관세율이 무세이거나 관세가 감면되는 물품(ㄷ)이다.\n고급 시계(ㄱ)와 기본관세율 10퍼센트 이상 신발(ㄹ)은 간이세율표에 세율이 정해져 있어 적용 대상이다. 3번이다.","c":"중","v":1},"관세사2025_42-12":{"w":"상계조치는 재정경제부령으로 적용시한을 따로 정하지 않으면 시행일부터 5년이 지나면 효력을 잃고, 재심사 결과 내용을 변경한 때도 변경된 내용의 시행일부터 5년이 지나면 효력을 잃는다. ㄱ 재정경제부령, ㄴ 5로 5번이다.","c":"중","v":1},"관세사2025_42-13":{"w":"관세법 시행령 제57조 제2항: 잠정세율 적용정지·인하 요청 자료는 관세율표 번호·품명·규격·용도·대체물품, 제조용 투입원료와 관련제품의 제조공정설명서·용도, 적용 정지 이유와 기간, 변경할 세율·이유·적용기간, 최근 1년간 월별 주요 수입국별 수입가격·수입실적, 최근 1년간 월별 주요 국내제조업체별 공장도가격·출고실적 등이다.\n최근 2년간 주별 수출국별 수출가격·수출실적은 열거돼 있지 않다. 4번이다.","c":"상","v":1},"관세사2025_42-14":{"w":"간이세율 적용 제외 물품은 무세·감면 물품, 수출용원재료, 종량세 물품 등이다.\n개별소비세가 과세되는 오락용 사행기구는 탁송품이어도 간이세율을 적용할 수 있다. 5번이다.","c":"중","v":1},"관세사2026_43-11":{"w":"ㄱ O: 국내외 가격차에 상당한 율로 양허한 농림축산물의 수입가격이 하락하면 양허한 세율을 초과해 관세를 부과할 수 있다.\nㄴ O: 특정국가와 협상할 때 기본 관세율의 100분의 50 범위를 초과해 양허할 수 없다.\nㄷ X: 수입가격이 급등한 물품의 국내가격 안정을 위한 할당관세는 100분의 40 범위의 율을 뺀 세율로 부과한다.\nㄱ, ㄴ이므로 2번이다.","c":"중","v":1},"관세사2026_43-12":{"w":"간이세율을 적용하지 않는 물품은 종량세 물품(ㄴ), 관세청장이 정하는 고가품(ㄹ), 관세가 감면되는 물품(ㅁ)이다.\n별송품(ㄱ), 개별소비세가 과세되지 않는 기본관세율 10퍼센트 이상 녹용(ㄷ), 개별소비세가 과세되는 상아(ㅂ)는 적용 대상이다. 4번이다.","c":"중","v":1},"관세사2026_43-14":{"w":"품목분류 사전심사·재심사 신청의 반려 사유: 신청인의 반려 요청, 이의신청·불복·소송 진행 중, 성분·조성의 일관성 확보가 곤란한 농산물 혼합물, 정해진 기간 안에 보정하지 않은 경우 등이다.\n이미 수출입신고한 물품이 동일한 물품일 때가 반려 사유이며 유사한 물품은 해당하지 않는다. 1번이다.","c":"중","v":1},"관세사2023_40-04":{"w":"관세법 시행령 제6조\nㄱ O 원칙: 수입신고한 날의 다음날\nㄴ X 의무불이행 등으로 감면된 관세를 징수하는 경우: 그 사유가 발생한 날의 다음날(제2호)\nㄷ O 과다환급·부정환급 등으로 징수하는 경우: 환급한 날의 다음날(제4호)\n옳은 것은 ㄱ, ㄷ이다.","c":"상","v":1},"관세사2019_36-26":{"w":"(2022 개정 전 기준) 출제 당시 관세법 시행령 제277조는 은닉재산 신고 포상금을 징수금액 2천만원 이상 2억원 이하는 100분의 15, 2억원 초과 5억원 이하는 3천만원에 2억원 초과분의 100분의 10을 더한 금액으로 정했다. 징수금액 5억원이면 3천만원 + 3억원 × 10% = 6천만원으로 2번이 정답이었다.\n2022. 2. 15. 개정으로 지금은 2천만원 이상 5억원 이하 구간이 100분의 20이어서 1억원이 되고 맞는 선지가 없다.","c":"상","v":1,"old":1,"ow":"2022.2.15 관세법 시행령 제277조 개정으로 은닉재산 신고 포상금 지급률이 바뀌어 지금 기준 답(1억원)이 선지에 없다. 출제에서 뺀다."},"관세사2017_34-12-4":{"w":"관세법 제3조 제1항이 관세를 납부할 물품에 대해 다른 조세·공과금·채권보다 관세를 먼저 징수하도록 정한다. 그 물품이 아닌 재산에 강제징수를 할 때만 국세와 같은 순위가 된다(같은 조 제2항).","c":"상","v":1},"관세사2018_35-06-2":{"w":"관세는 수입신고 때의 성질·수량으로 부과하는 것이 원칙이지만 수입신고전 즉시반출신고를 하고 반출한 물품은 그 신고를 한 때가 기준이다(관세법 제16조 제7호).","c":"상","v":1},"관세사2018_35-06-3":{"w":"관세법 제16조 제9호가 도난물품·분실물품은 해당 물품이 도난되거나 분실된 때의 성질과 수량으로 관세를 부과하도록 정한다.","c":"상","v":1},"관세사2018_35-06-4":{"w":"관세법 제16조 제8호는 우편물(제258조 제2항 우편물 제외)의 과세물건 확정 시기를 제256조에 따른 통관우체국에 도착한 때로 정한다.","c":"상","v":1},"관세사2018_35-06-5":{"w":"관세법 제16조 제6호에 따라 수입신고 수리 전에 소비·사용한 물품은 소비하거나 사용한 때가 기준이다. 제239조에 따라 수입으로 보지 않는 소비·사용은 빠진다.","c":"상","v":1},"관세사2018_35-07-1":{"w":"장치물품이 멸실·폐기되어 제160조 제2항으로 관세를 징수할 때 납세의무자는 운영인 또는 보관인이다(관세법 제19조 제1항 제4호).","c":"상","v":1},"관세사2018_35-07-2":{"w":"관세법 제19조 제1항 제9호가 우편으로 수입되는 물품의 납세의무자를 수취인으로 정한다.","c":"상","v":1},"관세사2018_35-07-3":{"w":"보세운송기간이 지나 제217조로 관세를 징수하는 물품은 보세운송을 신고했거나 승인받은 자가 납세의무자다(관세법 제19조 제1항 제6호).","c":"상","v":1},"관세사2018_35-07-5":{"w":"관세법 제19조 제1항 제3호는 보세구역 밖 보수작업 물품에서 관세를 징수하는 경우 그 보수작업을 승인받은 자를 납세의무자로 정한다. 조문 인용은 현행 제158조 제7항으로 옮겨졌다.","c":"상","v":1},"관세사2022_39-01-1":{"w":"관세법 제2조 제6호의 정의다. 국제무역선은 무역을 위해 우리나라와 외국 간을 운항하는 선박이고 국내에서만 운항하면 국내운항선(제8호)이다.","c":"상","v":1},"관세사2022_39-01-2":{"w":"관세법 제2조 제11호의 정의다. 선박용품에 준하는 물품 가운데 해당 항공기에서만 사용되는 것이 항공기용품이다.","c":"상","v":1},"관세사2022_39-01-3":{"w":"관세법 제2조 제14호의 정의다. 같은 세관 관할구역 안에서 옮겨 실으면 환적이고 다른 세관 관할구역으로 운송해 옮겨 실으면 복합환적(제15호)이다.","c":"상","v":1},"관세사2022_39-01-5":{"w":"관세법 제2조 제15호의 정의다. 다른 세관 관할구역으로 운송한 뒤 옮겨 싣는다는 점에서 같은 관할구역 안의 환적(제14호)과 나뉜다.","c":"상","v":1},"관세사2022_39-03-1":{"w":"수입신고전 즉시반출 후 기간 안에 수입신고를 하지 않아 제253조 제4항으로 관세를 징수하면 즉시 반출한 자가 납세의무자다(관세법 제19조 제1항 제8호).","c":"상","v":1},"관세사2022_39-03-2":{"w":"관세법 제19조 제1항 제9호가 우편물의 납세의무자를 수취인으로 정한다.","c":"상","v":1},"관세사2022_39-03-4":{"w":"화주가 불분명한 경우 수입신고 전에 양도된 물품은 양수인을 화주로 보아 납세의무자로 한다(관세법 제19조 제1항 제1호 다목).","c":"상","v":1},"관세사2022_39-03-5":{"w":"관세법 제19조 제1항 제4호가 장치물품 폐기·멸실로 제160조 제2항에 따라 관세를 징수하는 물품의 납세의무자를 운영인 또는 보관인으로 정한다.","c":"상","v":1},"관세사2023_40-02-2":{"w":"관세법 제19조 제1항 제9호가 우편물의 납세의무자를 수취인으로 정한다.","c":"상","v":1},"관세사2023_40-02-3":{"w":"도난·분실물품 가운데 보세운송물품은 보세운송을 신고하거나 승인받은 자가 납세의무자다(관세법 제19조 제1항 제10호 나목). 장치물품은 운영인·화물관리인, 그 밖의 물품은 보관인·취급인이다.","c":"상","v":1},"관세사2023_40-02-4":{"w":"관세법 제19조 제3항이 이 법 또는 다른 법령·조약·협약에 따라 관세 납부를 보증한 자는 보증액 범위에서 납세의무를 진다고 정한다.","c":"상","v":1},"관세사2023_40-02-5":{"w":"관세법 제19조 제6항 제3호가 법인이 채무자회생법 제215조에 따라 신회사를 설립하는 경우 국세기본법 제25조를 준용해 신회사에 관세·가산세·강제징수비의 연대납부의무를 지운다.","c":"상","v":1},"관세사2023_40-07-2":{"w":"관세법 제8조 제1항이 기간을 계산할 때 수입신고수리전 반출승인을 받으면 그 승인일을 수입신고 수리일로 본다고 정한다.","c":"상","v":1},"관세사2023_40-07-3":{"w":"관세법 제8조 제3항 제4호의 대통령령으로 정하는 날에 금융기관 또는 체신관서의 휴무 등으로 관세 납부가 곤란하다고 관세청장이 정하는 날이 들어가 그 다음 날이 기한이 된다(관세법 시행령 제1조의4 제1항).","c":"상","v":1},"관세사2023_40-07-4":{"w":"관세법 시행령 제1조의5 제1항이 월별납부를 하려는 자는 납세실적·수출입실적 서류 등 관세청장이 정하는 서류를 갖춰 세관장에게 승인을 신청하도록 정한다. 승인 유효기간은 승인일부터 2년이 되는 날이 속하는 달의 말일까지다(같은 조 제2항).","c":"상","v":1},"관세사2023_40-07-5":{"w":"관세법 제10조에 따라 세관장은 천재지변 등으로 신고·신청·납부 등을 기한까지 할 수 없다고 인정하면 1년을 넘지 않는 범위에서 기한을 연장할 수 있고 필요하면 담보를 제공하게 할 수 있다.","c":"상","v":1},"관세사2024_41-02-4":{"w":"관세법 제239조 제1호가 선박용품·항공기용품·차량용품을 운송수단 안에서 용도에 따라 소비·사용하는 경우를 수입으로 보지 않는다고 정한다. 그래서 제2조 제1호 수입의 정의에서도 빠진다.","c":"상","v":1},"관세사2026_43-01-1":{"w":"관세법 제2조 제3호의 반송 정의다. 수입통관을 거치지 않고 외국물품 상태로 다시 나가는 것이라 내국물품을 내보내는 수출(제2호)과 다르다.","c":"상","v":1},"관세사2026_43-01-2":{"w":"관세법 제2조 제6호의 정의다. 국내에서만 운항하는 선박은 국내운항선(제8호)이다.","c":"상","v":1},"관세사2026_43-01-3":{"w":"관세법 제2조 제13호가 통관을 이 법의 절차를 이행해 물품을 수출·수입 또는 반송하는 것으로 정한다.","c":"상","v":1},"관세사2026_43-01-5":{"w":"관세법 제2조 제14호의 정의다. 다른 세관 관할구역으로 운송해 옮겨 실으면 복합환적(제15호)이다.","c":"상","v":1},"관세사2026_43-06-1":{"w":"관세법 제19조 제3항이 이 법 또는 다른 법령·조약·협약 등에 따라 관세 납부를 보증한 자에게 보증액 범위의 납세의무를 지운다.","c":"상","v":1},"관세사2026_43-06-2":{"w":"관세법 제19조 제5항 제1호 가목은 수입신고물품이 공유물이거나 공동사업에 속하면 그 공유자 또는 공동사업자인 납세의무자가 관세·가산세·강제징수비를 연대해 납부하도록 정한다.","c":"상","v":1},"관세사2026_43-06-4":{"w":"관세법 제19조 제1항 제9호가 우편물의 납세의무자를 수취인으로 정한다.","c":"상","v":1},"관세사2026_43-06-5":{"w":"관세법 제19조 제1항 제10호 나목이 도난·분실된 보세운송물품의 납세의무자를 보세운송을 신고하거나 승인받은 자로 정한다.","c":"상","v":1},"관세사2017_34-16-4":{"w":"가격신고는 수입신고를 할 때 하는 것이 원칙이고 통관 능률을 높이기 위해 필요하면 수입신고 전에도 할 수 있다(관세법 제27조 제1항 단서).","c":"상","v":1},"관세사2020_37-04-1":{"w":"관세법 제36조가 납세의무자의 서면 요청이 있으면 세관장이 과세가격 결정방법·과세가격·산출근거를 서면으로 통보하도록 정한다.","c":"상","v":1},"관세사2020_37-04-2":{"w":"관세법 제37조 제1항 제3호가 특수관계자 간 거래물품의 과세가격 결정방법을 사전심사 신청 대상으로 정한다. 신청은 가격신고 전에 관세청장에게 한다.","c":"상","v":1},"관세사2020_37-04-4":{"w":"관세법 제37조의3에 따라 관세청장 또는 세관장은 과세가격 결정·조정과 관세 부과·징수에 필요하면 국세청장·지방국세청장·관할 세무서장에게 정보나 자료를 요청할 수 있고 요청받은 기관은 정당한 사유가 없으면 따라야 한다.","c":"상","v":1},"관세사2020_37-04-5":{"w":"관세법 제37조의4 제1항이 관세조사와 제38조 제2항의 세액심사 때 특수관계자에게 과세가격결정자료 제출을 요구할 수 있도록 정한다. 요구받은 자는 60일 안에 내야 하고 한 차례 60일까지 연장된다(같은 조 제3항).","c":"상","v":1},"관세사2023_40-09-4":{"w":"관세법 제28조 제1항의 위임에 따라 관세법 시행령 제16조 제1항 제2호의2가 제37조 제1항 제3호의 과세가격 결정방법 사전심사를 신청한 경우를 잠정가격 신고 사유로 정한다.","c":"상","v":1},"관세사2017_34-34-1":{"w":"관세법 제78조 제1항 제1호의 양허 철회·수정 조치다. 수입 증가로 국내 생산자에게 중대한 피해나 그 우려가 있을 때 정부가 할 수 있고 사유에는 조약상 의무의 이행도 들어간다.","c":"상","v":1},"관세사2017_34-34-2":{"w":"관세법 제79조 제1항 제1호의 대항조치다. 외국의 양허 철회·수정에 맞서 과세가격 상당액 범위에서 관세를 더 부과할 수 있고 대항에 필요한 범위로 한정된다(같은 조 제2항).","c":"상","v":1},"관세사2017_34-34-3":{"w":"관세법 제79조 제1항 제2호가 대항조치로 양허 적용을 정지하고 이 법에 따른 세율 범위에서 관세를 부과하는 것을 허용한다.","c":"상","v":1},"관세사2017_34-34-4":{"w":"관세법 제80조 제1항이 양허 철회 품목에 대해 조약상 철회 효력 발생일부터 이 법의 세율을 적용하도록 정한다. 보상으로 새로 양허한 품목은 양허 효력 발생일부터 이 법의 세율을 적용하지 않는다(같은 조 제2항).","c":"상","v":1},"관세사2017_34-36-3":{"w":"관세법 시행령 제100조 제8항이 관세청장에게 학계·연구기관·협회 등에서 활동하는 자를 기술자문위원으로 위촉할 수 있게 한다.","c":"상","v":1},"관세사2017_34-36-5":{"w":"관세법 제85조 제2항 제2호가 제86조에 따른 품목분류 사전심사와 재심사를 관세품목분류위원회의 심의사항으로 정한다.","c":"상","v":1},"관세사2017_34-39-1":{"w":"관세법 제81조 제3항이 간이세율을 수입물품의 관세·임시수입부가세·내국세 세율을 기초로 대통령령으로 정하도록 한다. 세율은 관세법 시행령 제96조 제1항과 별표 2에 있다.","c":"상","v":1},"관세사2017_34-39-3":{"w":"관세법 제81조 제4항이 여행자·승무원 휴대품으로서 총액이 대통령령으로 정하는 금액 이하인 물품에 단일 간이세율을 둘 수 있게 한다.","c":"상","v":1},"관세사2017_34-39-4":{"w":"관세법 시행령 제96조 제2항이 수출용원재료(제2호)와 종량세가 적용되는 물품(제4호)을 간이세율 적용 제외 물품으로 정한다.","c":"상","v":1},"관세사2018_35-13-1":{"w":"관세법 제72조 제1항의 계절관세다. 국내외 가격차 상당 율 범위에서 높이거나 100분의 40 범위의 율을 기본세율에서 빼서 부과하고 대상·세율·시한은 재정경제부령으로 정한다(같은 조 제2항).","c":"상","v":1},"관세사2018_35-13-2":{"w":"관세법 제67조에 따라 재정경제부장관은 긴급관세 부과결정을 재심사해 부과내용을 바꿀 수 있지만 변경된 내용이 최초 조치보다 강화되어서는 안 된다.","c":"상","v":1},"관세사2018_35-13-3":{"w":"관세법 제68조 제2항이 특별긴급관세의 대상 물품·세율·적용시한·수량 등을 재정경제부령으로 정하도록 한다.","c":"상","v":1},"관세사2018_35-13-5":{"w":"관세법 제73조 제2항 단서가 특정 국가와 협상할 때 기본 관세율의 100분의 50 범위를 넘어 양허할 수 없다고 정한다. 국제기구와 협상할 때는 이 제한이 없다.","c":"상","v":1},"관세사2019_36-12-1":{"w":"관세법 제76조 제1항이 대통령령으로 정하는 개발도상국(특혜대상국)을 원산지로 하는 특혜대상물품에 기본세율보다 낮은 일반특혜관세를 부과할 수 있게 한다.","c":"상","v":1},"관세사2019_36-12-3":{"w":"관세법 제76조 제3항이 유엔총회 결의에 따른 최빈개발도상국 중 대통령령으로 정하는 국가를 원산지로 하는 물품을 다른 특혜대상국보다 우대할 수 있게 한다. 최빈국에서 빠진 뒤 일정 기간이 지나지 않은 국가도 들어간다.","c":"상","v":1},"관세사2019_36-12-4":{"w":"관세법 제77조 제1항이 특혜대상물품 수입 증가로 국내산업에 중대한 피해나 그 우려가 있으면 재정경제부장관이 물품과 원산지국을 지정해 일반특혜관세 적용을 정지할 수 있게 한다.","c":"상","v":1},"관세사2019_36-12-5":{"w":"관세법 제76조 제4항이 특혜대상물품의 세율·적용기간 등을 대통령령으로 정하도록 위임한다.","c":"상","v":1},"관세사2019_36-15-3":{"w":"관세법 제65조 제4항이 긴급관세와 잠정긴급관세는 각각의 부과조치 결정 시행일 이후 수입되는 물품에만 적용한다고 정한다.","c":"상","v":1},"관세사2020_37-16-1":{"w":"관세법 시행령 제100조 제2항이 관세품목분류위원회 위원장을 관세청 3급 공무원 또는 고위공무원단 일반직공무원 중 관세청장이 지정하는 자로 정한다.","c":"상","v":1},"관세사2020_37-16-2":{"w":"관세법 시행령 제100조 제4항 제1호가 심신장애로 직무를 수행할 수 없게 된 위원을 관세청장이 해임·해촉할 수 있는 사유로 정한다.","c":"상","v":1},"관세사2020_37-16-3":{"w":"관세법 시행령 제100조 제6항이 위원장이 부득이한 사정으로 직무를 못 할 때 위원장이 지명하는 위원이 대행하도록 정한다.","c":"상","v":1},"관세사2020_37-16-5":{"w":"관세법 시행령 제101조의2 제1항 제3호가 위원이 안건 당사자의 대리인이거나 최근 5년 안에 대리인이었던 경우를 제척 사유로 정한다.","c":"상","v":1},"관세사2020_37-19-1":{"w":"관세법 제64조가 보복관세를 부과할 때 필요하면 재정경제부장관이 관련 국제기구 또는 당사국과 미리 협의할 수 있다고 정한다.","c":"상","v":1},"관세사2020_37-19-2":{"w":"관세법 제67조 전단이 재정경제부장관에게 긴급관세 부과결정의 재심사 권한을 준다. 재심사로 바꾼 내용은 최초 조치보다 강화할 수 없다.","c":"상","v":1},"관세사2020_37-19-3":{"w":"관세법 제67조의2 제4항이 특정국물품 긴급관세를 부과할 때 이해당사국과 해결책을 찾기 위한 사전 협의를 할 수 있게 한다.","c":"상","v":1},"관세사2020_37-19-4":{"w":"관세법 제76조 제2항이 일반특혜관세를 부과할 때 국내산업 영향을 고려해 세율에 차등을 두거나 수입수량을 한정할 수 있게 한다.","c":"상","v":1},"관세사2020_37-20-5":{"w":"관세법 시행령 제106조 제6항이 신청인이 관세율표의 호·소호까지만 심사를 요청하면 그 번호까지만 심사해 통지할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-16-1":{"w":"관세법 제50조 제4항이 잠정세율 물품의 전부나 일부에 대해 잠정세율 적용을 정지하거나 기본세율과의 차를 좁히도록 잠정세율을 올리거나 내릴 수 있게 한다.","c":"상","v":1},"관세사2022_39-16-2":{"w":"관세법 제50조 제1항이 기본세율과 잠정세율은 관세율표에 따르되 잠정세율을 기본세율보다 우선 적용하도록 정한다.","c":"상","v":1},"관세사2022_39-16-3":{"w":"관세법 시행령 제57조 제1항이 잠정세율 물품과 관련된 관계부처의 장이나 이해관계인이 적용정지·인상·인하를 재정경제부장관에게 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-16-4":{"w":"관세법 시행령 제57조 제3항이 잠정세율 적용정지 등의 조사에 필요하면 재정경제부장관이 관계기관·수출자·수입자 그 밖의 이해관계인에게 자료 제출과 협조를 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-31-1":{"w":"관세법 제52조 제2항이 덤핑방지관세를 부과할 때 관련 산업 경쟁력, 국내 시장구조, 물가안정, 통상협력 등을 조사해 반영할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-31-2":{"w":"관세법 제55조가 덤핑방지관세와 잠정조치를 각 조치일 이후 수입 물품에 적용하되 잠정조치 물품에 국제협약이 달리 정하는 경우 등에는 그 물품에도 부과할 수 있게 한다.","c":"상","v":1},"관세사2024_41-31-3":{"w":"관세법 제56조 제1항이 재정경제부장관이 덤핑방지관세 부과와 가격수정 약속(덤핑방지조치)을 재심사하고 결과에 따라 변경·환급 등을 할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-31-4":{"w":"관세법 제56조 제2항이 재심사에 필요한 덤핑방지조치 물품의 수입·징수실적 등을 재정경제부장관이 조사할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-11-5":{"w":"관세법 시행령 제100조 제6항이 위원장이 부득이한 사정으로 직무를 못 할 때 위원장이 지명하는 위원이 대행하도록 정한다.","c":"상","v":1},"관세사2026_43-13-2":{"w":"관세법 제65조 제4항이 긴급관세는 부과조치 결정 시행일 이후 수입되는 물품에만 적용한다고 정한다. 소급 부과는 없다.","c":"상","v":1},"관세사2017_34-18-4":{"w":"관세법 제46조 제4항이 관세환급금은 국가재정법 제17조에도 불구하고 한국은행의 해당 세관장 소관 세입금에서 지급하도록 정한다.","c":"상","v":1},"관세사2017_34-32-4":{"w":"관세법 제106조의2 제3항이 자가사용물품 등의 관세 환급에 제46조(관세환급금의 환급)·제47조(과다환급관세의 징수)와 제106조 제2항·제5항을 준용하도록 정한다.","c":"상","v":1},"관세사2019_36-03-1":{"w":"관세법 제46조 제1항 후단이 세관장이 확인한 관세환급금은 납세의무자가 청구하지 않아도 환급하도록 정한다.","c":"상","v":1},"관세사2019_36-13-1":{"w":"관세법 제107조 제8항이 분할납부를 승인받은 법인이 해산하면 청산인이 관세를 납부하도록 정한다. 해산 사유는 지체 없이 세관장에게 신고해야 한다(같은 조 제4항).","c":"상","v":1},"관세사2019_36-13-3":{"w":"관세법 제107조 제3항이 분할납부 승인 물품의 용도를 바꾸거나 양도하려면 미리 세관장 승인을 받도록 정한다.","c":"상","v":1},"관세사2019_36-13-4":{"w":"관세법 제107조 제7항이 분할납부를 승인받은 자가 파산선고를 받으면 파산관재인이 관세를 납부하도록 정한다.","c":"상","v":1},"관세사2019_36-13-5":{"w":"관세법 제107조 제9항 제4호가 법인 해산을 미납 관세 전액 즉시징수 사유로 정한다. 용도 외 사용·양도, 기한 내 미납, 파산선고도 같은 사유다.","c":"상","v":1},"관세사2020_37-01-1":{"w":"관세법 시행령 제51조 제4항이 세관장에게 관세환급금결정액계산서와 증빙서류를 감사원장이 정하는 바에 따라 감사원에 제출할 의무를 지운다.","c":"상","v":1},"관세사2020_37-13-3":{"w":"관세법 제107조 제8항이 분할납부를 승인받은 법인이 해산하면 청산인이 관세를 납부하도록 정한다.","c":"상","v":1},"관세사2022_39-17-1":{"w":"관세법 제106조의2 제1항 제1호가 수입신고 수리된 개인 자가사용물품을 수리일부터 6개월 안에 보세구역 등에 반입했다가 수입한 상태 그대로 다시 수출하면 납부한 관세를 환급하도록 정한다.","c":"상","v":1},"관세사2023_40-01-1":{"w":"관세법 제46조 제1항이 과오납금이나 환급세액의 환급 청구를 받으면 세관장이 지체 없이 관세환급금으로 결정하고 30일 안에 환급하도록 정한다.","c":"상","v":1},"관세사2023_40-01-2":{"w":"관세법 제46조 제1항 후단이 세관장이 확인한 관세환급금은 청구가 없어도 환급하도록 정한다.","c":"상","v":1},"관세사2023_40-01-3":{"w":"관세법 제46조 제3항이 관세환급금에 관한 권리를 대통령령으로 정하는 바에 따라 제3자에게 양도할 수 있다고 정한다. 절차는 관세법 시행령 제53조에 있다.","c":"상","v":1},"관세사2023_40-01-4":{"w":"관세법 시행령 제55조 제3항이 환급통지서 발행일부터 1년 안에 환급금을 받지 못한 자는 세관장에게 다시 환급절차를 밟도록 요구할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-07-1":{"w":"관세법 제46조 제1항 후단이 세관장이 확인한 관세환급금은 납세의무자가 청구하지 않아도 환급하도록 정한다.","c":"상","v":1},"관세사2024_41-07-2":{"w":"관세법 제47조 제2항이 과다환급액을 징수할 때 과다환급한 날의 다음 날부터 징수결정일까지 대통령령으로 정한 이율로 계산한 금액을 더하도록 정한다.","c":"상","v":1},"관세사2024_41-07-4":{"w":"관세법 시행령 제55조 제2항이 세관환급금지급미필이월계정에 이월한 금액 중 환급통지서 발행일부터 1년 안에 지급하지 못한 금액을 그 기간이 끝난 날이 속하는 회계연도 세입에 편입하도록 정한다.","c":"상","v":1},"관세사2024_41-07-5":{"w":"관세법 시행령 제55조 제3항이 환급통지서 발행일부터 1년 안에 환급금을 받지 못한 자의 재환급 요구와 세관장의 조사·확인 및 지급 조치를 정한다.","c":"상","v":1},"관세사2025_42-10-1":{"w":"관세법 제46조 제3항이 납세의무자의 관세환급금 권리를 대통령령으로 정하는 바에 따라 제3자에게 양도할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-10-2":{"w":"관세법 제46조 제2항이 환급받을 자가 세관에 낼 관세·그 밖의 세금·가산세·강제징수비가 있으면 환급금에서 충당할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-10-3":{"w":"관세법 시행령 제55조 제3항이 환급통지서 발행일부터 1년 안에 환급금을 받지 못하면 다시 환급절차를 요구할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-10-5":{"w":"관세법 시행령 제51조 제1항이 세관장이 관세환급 사유를 확인하면 권리자에게 금액과 이유 등을 통지하도록 정한다.","c":"상","v":1},"관세사2017_34-19-2":{"w":"관세법 제38조 제5항이 납부 전에 과부족을 안 납세의무자가 납세신고 세액을 정정할 수 있게 하고 이때 납부기한은 당초 납부기한 그대로다.","c":"상","v":1},"관세사2017_34-19-3":{"w":"관세법 제38조의2 제1항이 신고납부한 세액의 부족이나 과세가격·품목분류 오류를 안 때 신고납부한 날부터 6개월 이내(보정기간)에 세관장에게 보정을 신청할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-19-4":{"w":"관세법 제38조의3 제1항이 보정기간이 지난 뒤 제척기간 끝나기 전까지 수정신고를 할 수 있게 하고 수정신고한 날의 다음 날까지 관세를 납부하도록 정한다.","c":"상","v":1},"관세사2017_34-19-5":{"w":"관세법 제39조 제1항 제4호가 납세의무자가 과세가격·관세율 결정이 곤란해 부과고지를 요청하는 경우를 세관장이 부과·징수하는 사유로 정한다.","c":"상","v":1},"관세사2018_35-02-2":{"w":"관세법 제9조 제1항 제2호가 부과고지 때 납부기한을 고지를 받은 날부터 15일 이내로 정한다. 2020년 개정으로 용어가 납세고지에서 납부고지로 바뀌었다.","c":"상","v":1},"관세사2018_35-03-1":{"w":"관세법 제25조 제3항이 납세의무자가 아닌 자가 납부를 보증한 경우 담보를 관세에 충당하고 남은 금액을 보증인에게 직접 돌려주도록 정한다.","c":"상","v":1},"관세사2018_35-03-3":{"w":"관세법 제26조 제2항이 압류·보관·운반·공매 비용 상당액을 징수할 수 있게 한다. 2020년 개정으로 체납처분비는 강제징수비로 이름이 바뀌었다.","c":"상","v":1},"관세사2018_35-03-4":{"w":"관세법 제25조 제1항이 납부기한까지 관세를 내지 않으면 재정경제부령에 따라 담보를 관세에 충당할 수 있게 한다. 금전 담보를 기한 뒤 충당해도 가산세(제42조)는 붙지 않는다.","c":"상","v":1},"관세사2018_35-03-5":{"w":"관세법 제24조 제4항이 계속 담보를 제공할 사유가 있는 납세의무자(보증인 포함)에게 일정 기간 담보를 포괄해 미리 제공할 수 있게 한다. 신청 방법은 관세법 시행령 제11조에 있다.","c":"상","v":1},"관세사2018_35-05-1":{"w":"관세법 제23조 제2항이 환급청구권의 소멸시효는 환급청구권의 행사로 중단된다고 정한다.","c":"상","v":1},"관세사2018_35-05-2":{"w":"관세법 제23조 제3항이 분할납부기간, 징수유예기간, 압류·매각의 유예기간, 사해행위 취소소송기간에는 관세징수권 시효가 진행하지 않는다고 정한다. 체납처분유예는 2020년 개정으로 압류·매각의 유예로 이름이 바뀌었다.","c":"상","v":1},"관세사2018_35-05-3":{"w":"관세법 제23조 제1항 제1호가 고지를 관세징수권 소멸시효 중단 사유로 정한다. 지금 법문 용어는 납부고지다.","c":"상","v":1},"관세사2018_35-05-4":{"w":"관세법 제23조 제1항 제4호가 통고처분을 관세징수권 소멸시효 중단 사유로 정한다. 납부고지·경정처분·납부독촉·고발·공소제기·교부청구·압류도 중단 사유다.","c":"상","v":1},"관세사2018_35-08-2":{"w":"관세법 제38조 제6항이 납세신고·자율심사·세액 정정의 방법과 절차를 대통령령에 위임한다. 세액 정정 조항은 2024년 개정으로 제38조 제5항이 되었다.","c":"상","v":1},"관세사2018_35-08-3":{"w":"관세법 제38조 제4항이 납세실적·수입규모 등 관세청장이 정한 요건을 갖춘 자가 신청하면 세관장이 자율심사를 하게 할 수 있다고 정한다. 그 결과는 세관장에게 제출한다.","c":"상","v":1},"관세사2018_35-08-4":{"w":"관세법 제38조 제1항이 부과고지 물품을 뺀 물품을 수입하려는 자에게 수입신고 때 납세신고를 하도록 정한다.","c":"상","v":1},"관세사2018_35-09-1":{"w":"관세법 제38조의3 제1항이 수정신고 기간을 보정기간이 지난 날부터 제21조 제1항의 부과제척기간이 끝나기 전까지로 한정한다.","c":"상","v":1},"관세사2018_35-09-3":{"w":"관세법 제38조의3 제2항이 신고납부·보정·수정신고한 세액이 과다하면 최초 납세신고일부터 5년 안에 경정을 청구할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-09-4":{"w":"관세법 제38조의3 제5항이 경정청구 후 2개월 안에 통지를 받지 못하면 2개월이 되는 날의 다음 날부터 이의신청·심사청구·심판청구·감사원 심사청구를 할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-09-5":{"w":"관세법 제38조의3 제6항이 세관장이 신고납부·납세신고·경정청구 세액을 심사해 과부족을 알면 그 세액을 경정하도록 정한다.","c":"상","v":1},"관세사2019_36-02-1":{"w":"관세법 시행령 제42조 제3항이 관세체납정리위원회 위원장을 세관장으로 정한다.","c":"상","v":1},"관세사2019_36-02-2":{"w":"관세법 시행령 제42조 제2항이 관세체납정리위원회를 위원장 1인을 포함한 5인 이상 7인 이내로 구성하도록 정한다.","c":"상","v":1},"관세사2019_36-02-4":{"w":"관세법 제45조 제1항과 같은 법 시행령 제42조 제1항이 관세체납정리위원회를 세관에 두도록 정한다.","c":"상","v":1},"관세사2019_36-02-5":{"w":"관세법 시행령 제42조 제3항이 위원을 세관공무원, 변호사·관세사·공인회계사·세무사, 상공계 대표 등 가운데 세관장이 임명 또는 위촉하도록 정한다.","c":"상","v":1},"관세사2019_36-07-1":{"w":"관세법 제26조의2가 납세담보를 받은 관세 등이 납부되면 세관장이 지체 없이 담보해제 절차를 밟도록 정한다. 지금 법문은 관세 및 강제징수비로 적는다.","c":"상","v":1},"관세사2019_36-07-3":{"w":"관세법 제26조 제1항이 담보가 없거나 징수액이 부족한 관세의 징수는 관세법에 정한 것 외에는 국세기본법과 국세징수법의 예에 따르도록 정한다.","c":"상","v":1},"관세사2019_36-07-4":{"w":"관세법 시행령 제12조 제1항이 담보물 가격 감소로 세관장이 증가·변경을 통지하면 담보 제공자가 지체 없이 이행하도록 정한다.","c":"상","v":1},"관세사2019_36-07-5":{"w":"관세법 시행령 제10조 제1항이 담보의 종류·수량·금액·담보사유를 적은 담보제공서를 세관장에게 제출하도록 정한다.","c":"상","v":1},"관세사2020_37-05-2":{"w":"관세법 시행령 제10조 제3항이 국채·지방채를 담보로 낼 때 그 채권의 모든 권리를 행사할 수 있는 자의 위임장을 담보제공서에 첨부하도록 정한다.","c":"상","v":1},"관세사2020_37-05-3":{"w":"관세법 시행령 제10조 제8항 단서가 관세가 확정되지 않은 경우 담보 금액을 관세청장이 정하는 금액으로 한다고 정한다. 확정된 경우는 납부할 관세 상당액이다.","c":"상","v":1},"관세사2020_37-05-4":{"w":"관세법 시행령 제10조 제9항 제1호가 담보액 확정일부터 10일 안에 담보를 제공하지 않으면 세관장이 제39조에 따른 고지를 할 수 있다고 정한다. 지금 법문 용어는 납부고지다.","c":"상","v":1},"관세사2020_37-05-5":{"w":"관세법 시행령 제14조 제2항이 납세의무자가 매각예정일 1일 전까지 관세와 비용을 납부하면 담보물 매각을 중지하도록 정한다.","c":"상","v":1},"관세사2020_37-07-1":{"w":"관세법 제22조 제1항 제1호가 5억원 이상 관세(내국세 포함)의 징수권 소멸시효를 10년으로 정한다. 그 밖의 관세는 5년이다.","c":"상","v":1},"관세사2020_37-07-2":{"w":"관세법 제23조 제1항 제1호가 고지를 관세징수권 소멸시효 중단 사유로 정한다. 지금 법문 용어는 납부고지다.","c":"상","v":1},"관세사2020_37-07-4":{"w":"관세법 제23조 제2항이 환급청구권 소멸시효는 그 권리의 행사로 중단된다고 정한다.","c":"상","v":1},"관세사2020_37-07-5":{"w":"관세법 시행령 제7조 제2항 제5호가 적법하게 납부한 뒤 법률 개정으로 환급하는 경우 환급청구권을 행사할 수 있는 날을 그 법률의 시행일로 정한다.","c":"상","v":1},"관세사2020_37-10-2":{"w":"관세법 시행령 제37조가 징수하지 않는 금액을 1만원 미만으로 정하고 이때 수입신고수리일을 납부일로 본다고 정한다(제2항).","c":"상","v":1},"관세사2022_39-04-1":{"w":"관세법 시행령 제10조 제2항이 금전 담보는 국고금 관리법 시행령 제11조 제1항의 금융기관 중 관세청장이 지정한 곳에 납입하고 확인서를 담보제공서에 첨부하도록 정한다.","c":"상","v":1},"관세사2022_39-04-2":{"w":"관세법 시행령 제10조 제1항이 담보의 종류·수량·금액·담보사유를 적은 담보제공서를 세관장에게 내도록 정한다.","c":"상","v":1},"관세사2022_39-04-3":{"w":"관세법 시행령 제10조 제3항이 국채·지방채 담보에 모든 권리를 행사할 수 있는 자의 위임장 첨부를 요구한다.","c":"상","v":1},"관세사2022_39-04-4":{"w":"관세법 시행령 제10조 제8항 단서가 관세가 확정되지 않은 경우 담보 금액을 관세청장이 정하도록 한다.","c":"상","v":1},"관세사2022_39-05-2":{"w":"관세법 시행령 제14조 제2항이 매각예정일 1일 전까지 관세와 비용을 납부하면 담보물 매각을 중지하도록 정한다.","c":"상","v":1},"관세사2022_39-05-3":{"w":"관세법 시행령 제12조 제1항이 담보물 가격 감소로 세관장이 증가·변경을 통지하면 담보 제공자가 지체 없이 이행하도록 정한다.","c":"상","v":1},"관세사2022_39-05-4":{"w":"관세법 시행령 제14조 제1항이 담보물을 매각하려면 담보제공자 주소·성명, 담보물 종류·수량, 매각사유·장소·일시 등을 공고하도록 정한다.","c":"상","v":1},"관세사2022_39-05-5":{"w":"관세법 시행령 제12조 제2항이 담보물, 보증은행, 보증보험회사, 은행지급보증의 지급기일, 납세보증보험기간을 바꾸려면 세관장 승인을 얻도록 정한다.","c":"상","v":1},"관세사2022_39-07-2":{"w":"관세법 제38조 제6항이 납세신고·자율심사·세액 정정의 방법과 절차를 대통령령에 위임한다. 세액 정정 조항은 2024년 개정으로 제38조 제5항이 되었다.","c":"상","v":1},"관세사2022_39-07-3":{"w":"관세법 제38조 제5항이 납부 전에 과부족을 알면 납세신고 세액을 정정할 수 있게 하고 납부기한은 제9조의 당초 납부기한으로 정한다.","c":"상","v":1},"관세사2022_39-07-4":{"w":"관세법 제38조의3 제2항이 세액이 과다하면 최초 납세신고일부터 5년 안에 경정청구를 할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-07-5":{"w":"관세법 제38조의2 제1항이 과세가격·품목분류 등의 오류를 안 때 신고납부일부터 6개월 이내에 보정을 신청할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-08-1":{"w":"관세법 시행령 제42조 제4항이 민간위원 임기를 2년(한 번 연임)으로 하고 보궐위원 임기는 전임위원의 남은 기간으로 정한다.","c":"상","v":1},"관세사2022_39-08-3":{"w":"관세법 시행령 제48조가 위원장에게 위원회 의결사항을 관세청장에게 통보할 의무를 지운다.","c":"상","v":1},"관세사2022_39-08-4":{"w":"관세법 시행령 제43조 제7호가 관할 구역 안에 거주하지 않게 된 경우를 세관장의 위원 해임·해촉 사유로 정한다.","c":"상","v":1},"관세사2022_39-08-5":{"w":"관세법 시행령 제45조 제2항이 위원장을 포함한 재적위원 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결하도록 정한다.","c":"상","v":1},"관세사2023_40-05-1":{"w":"관세법 제21조 제2항 제1호 나목이 감사원법에 따른 심사청구 결정이 있으면 그 결정이 확정된 날부터 1년까지 결정에 따른 경정 등을 할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-05-2":{"w":"관세법 제21조 제1항 제2호가 부정한 방법으로 관세를 포탈하거나 환급·감면받은 경우 제척기간을 10년으로 정한다. 원칙은 5년, 무신고 수입은 7년이다.","c":"상","v":1},"관세사2023_40-05-3":{"w":"관세법 제21조 제2항 제1호 가목이 이의신청·심사청구·심판청구 결정이 있으면 확정된 날부터 1년까지 경정 등을 할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-05-4":{"w":"제척기간은 관세법 제21조가 정한 기간이 지나면 부과권이 소멸하는 제도라 중단·정지가 없다. 납부독촉은 관세징수권 소멸시효의 중단 사유일 뿐이다(관세법 제23조 제1항 제3호).","c":"상","v":1},"관세사2023_40-08-5":{"w":"관세법 시행령 제7조 제2항 제2호가 착오납부·이중납부로 인한 환급청구권 기산일을 그 납부일로 정한다.","c":"상","v":1},"관세사2023_40-10-2":{"w":"관세법 시행령 제10조 제1항이 담보제공서에 담보의 종류·수량·금액과 담보사유를 적도록 정한다.","c":"상","v":1},"관세사2023_40-15-1":{"w":"관세법 제116조의4 제1항이 법원은 검사의 청구에 따라 결정으로 30일 범위에서 체납 관세가 납부될 때까지 체납자를 감치할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-15-3":{"w":"관세법 제116조의4 제4항이 감치 결정에 즉시항고를 할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-15-4":{"w":"감치 요건은 3회 이상 체납, 체납발생일부터 각 1년 경과, 체납금액 합계 2억원 이상이다(관세법 제116조의4 제1항 제1호). 합계 1억원이면 금액 요건을 채우지 못한다.","c":"상","v":1},"관세사2023_40-15-5":{"w":"관세법 제116조의4 제3항이 관세청장이 감치 신청 전에 체납자에게 소명자료 제출이나 의견 진술 기회를 주도록 정한다.","c":"상","v":1},"관세사2024_41-04-1":{"w":"관세법 시행령 제10조 제6항이 토지·건물 등을 담보로 제공할 때 저당권 설정에 필요한 서류를 첨부하게 하고 세관장이 등기·등록 절차를 밟도록 정한다.","c":"상","v":1},"관세사2024_41-04-3":{"w":"관세법 시행령 제10조 제9항 제1호가 담보액 확정일부터 10일 안에 담보를 제공하지 않으면 세관장이 납부고지를 할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-04-4":{"w":"관세법 제25조 제3항이 제3자 보증인의 담보로 충당하고 남은 금액을 보증인에게 직접 돌려주도록 정한다.","c":"상","v":1},"관세사2024_41-04-5":{"w":"관세법 시행령 제10조 제5항 후단이 보증·보험 기간을 담보가 필요한 기간으로 하고 납부기한이 확정되지 않으면 관세청장이 정하는 기간으로 한다고 정한다.","c":"상","v":1},"관세사2024_41-05-5":{"w":"관세법 제23조 제3항이 분할납부기간에는 관세징수권 소멸시효가 진행하지 않는다고 정한다.","c":"상","v":1},"관세사2024_41-08-2":{"w":"관세법 시행령 제32조의2 제2항이 세관장에게 자율심사업체에 수출입업무 처리방법·체계 등 관세청장이 정한 자료를 제공하도록 정한다.","c":"상","v":1},"관세사2024_41-08-3":{"w":"관세법 시행령 제32조의5 제3항이 관세납부대행기관이 신용카드등 납부대행의 대가로 재정경제부령에 따라 수수료를 받을 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-08-4":{"w":"관세법 제38조의3 제1항 후단이 수정신고한 날의 다음 날까지 관세를 납부하도록 정한다.","c":"상","v":1},"관세사2024_41-08-5":{"w":"관세법 제38조 제5항이 납부 전 과부족을 알면 세액을 정정할 수 있게 하고 납부기한은 당초 납부기한으로 정한다.","c":"상","v":1},"관세사2025_42-03-1":{"w":"관세법 시행령 제7조 제2항 제1호가 제38조의3 제6항 경정으로 인한 환급의 기산일을 경정결정일로 정한다.","c":"상","v":1},"관세사2025_42-03-2":{"w":"관세법 시행령 제7조 제2항 제2호가 착오납부·이중납부 환급의 기산일을 그 납부일로 정한다.","c":"상","v":1},"관세사2025_42-03-3":{"w":"관세법 시행령 제7조 제2항 제3호의4가 국제무역선·국제무역기·보세판매장에서 산 뒤 환불한 물품의 환급 기산일을 환불된 날로 정한다.","c":"상","v":1},"관세사2025_42-03-4":{"w":"관세법 시행령 제7조 제2항 제4호가 관세 납부 후 제250조에 따라 신고가 취하·각하된 경우의 기산일을 취하일 또는 각하일로 정한다.","c":"상","v":1},"관세사2025_42-09-1":{"w":"관세법 시행령 제45조의2 제1항 제3호가 위원이 안건 당사자의 대리인이거나 최근 5년 안에 대리인이었던 경우를 제척 사유로 정한다.","c":"상","v":1},"관세사2025_42-09-3":{"w":"관세법 시행령 제45조의2 제1항 제4호가 당사자의 대리인이거나 최근 5년 안에 대리인이었던 법인·단체에 현재 속하거나 속했던 경우를 제척 사유로 정한다.","c":"상","v":1},"관세사2025_42-09-4":{"w":"관세법 시행령 제46조가 위원회가 필요하면 체납자나 이해관계인 등의 의견을 들을 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-09-5":{"w":"관세법 시행령 제47조가 위원장이 회의를 열면 회의록을 작성해 비치하도록 정한다.","c":"상","v":1},"관세사2026_43-07-1":{"w":"관세법 제24조 제2항이 납세보증보험증권과 납세보증서는 세관장이 요청하면 일정 기일 이후 언제든지 지급한다는 내용이어야 한다고 정한다.","c":"상","v":1},"관세사2018_35-21-1":{"w":"관세법 제110조의2가 특정 분야만 조사할 필요가 있는 경우 등을 빼고 신고납부세액과 수출입 관련 의무 이행 사항을 통합해 조사하는 것을 원칙으로 정한다.","c":"상","v":1},"관세사2018_35-21-2":{"w":"관세법 제110조 제3항이 긴급 체포·압수·수색이나 현행범 도주 우려 등 조사목적을 달성할 수 없는 경우 납세자권리헌장을 내주지 않을 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-21-4":{"w":"관세법 제111조 제1항이 적정·공평한 과세와 통관 적법성 보장에 필요한 최소 범위에서 관세조사를 하고 조사권을 남용하지 말라고 정한다.","c":"상","v":1},"관세사2018_35-21-5":{"w":"관세법 제113조 제1항이 신고의무 불이행이나 구체적 포탈 혐의 등 대통령령으로 정한 경우를 빼고 납세자의 성실성과 신고서의 진실성을 추정하도록 정한다.","c":"상","v":1},"관세사2018_35-22-1":{"w":"관세법 제122조 제1항이 심사청구서를 처분을 했거나 했어야 할 세관장을 거쳐 관세청장에게 내도록 정한다. 세관장은 받은 날부터 7일 안에 의견서를 붙여 보낸다(같은 조 제3항).","c":"상","v":1},"관세사2019_36-19-1":{"w":"관세법 제119조 제10항이 같은 처분에 심사청구와 심판청구를 중복해 제기할 수 없다고 정한다.","c":"상","v":1},"관세사2019_36-31-4":{"w":"관세법 제126조 제4항이 대리인은 청구에 관한 모든 행위를 할 수 있지만 청구 취하는 특별한 위임이 있어야 한다고 정한다.","c":"상","v":1},"관세사2022_39-18-1":{"w":"불복 청구는 원칙적으로 처분 집행에 영향이 없지만 관세법 제125조 제1항 단서가 중대한 손해 예방을 위한 긴급한 필요가 있으면 재결청이 집행·절차 속행의 전부나 일부를 정지할 수 있게 한다.","c":"상","v":1},"관세사2022_39-18-3":{"w":"관세법 제127조 제3항이 관세심사위원회 회의를 비공개로 하되 위원장이 필요하다고 인정하면 공개할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-18-4":{"w":"관세법 제127조 제1항 단서와 같은 법 시행령 제150조 제2호가 심사청구 대상 처분이 존재하지 않는 경우를 관세심사위원회 의결 없이 결정할 수 있는 사유로 정한다.","c":"상","v":1},"관세사2022_39-18-5":{"w":"관세법 제127조 제2항이 관세심사위원회 의결이 법령에 명백히 위반된다고 판단하면 관세청장이 구체적 사유를 서면으로 적어 한 차례만 재심의를 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-12-1":{"w":"관세법 제126조 제1항이 이의신청인·심사청구인·심판청구인은 변호사나 관세사를 대리인으로 선임할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-12-3":{"w":"관세법 제126조 제4항이 대리인의 모든 행위 권한을 인정하면서 청구 취하만은 특별한 위임을 요구한다.","c":"상","v":1},"관세사2023_40-12-4":{"w":"관세법 제126조 제5항이 대리인을 해임하면 그 뜻을 서면으로 재결청에 신고하도록 정한다.","c":"상","v":1},"관세사2023_40-12-5":{"w":"관세법 제126조 제3항이 대리인의 권한은 서면으로 증명하도록 정한다.","c":"상","v":1},"관세사2024_41-12-2":{"w":"관세법 제114조의2 제3항이 장부등을 세관관서에 일시 보관하려면 납세자에게서 일시 보관 동의서를 받고 일시 보관증을 내주도록 정한다.","c":"상","v":1},"관세사2024_41-12-3":{"w":"관세법 제111조 제2항 제5호의 위임을 받은 관세법 시행령 제136조 제1호가 밀수출입, 부정·불공정무역 등 경제질서 교란을 통한 탈세혐의자에 대한 일제조사를 중복조사 금지의 예외로 정한다.","c":"상","v":1},"관세사2024_41-12-4":{"w":"관세법 제112조가 관세조사 등을 받는 납세자에게 변호사·관세사를 조사에 참여시키거나 의견을 진술하게 할 권리를 준다.","c":"상","v":1},"관세사2024_41-12-5":{"w":"관세법 제116조의5 제3항 제4호의 위임에 따라 관세법 시행령 제141조의12 제1호가 부과결정 취소 등으로 체납 관세가 5천만원 미만이 된 경우를 출국금지 해제 요청 사유로 정한다. 관세청장은 즉시 해제를 요청해야 한다.","c":"상","v":1},"관세사2024_41-16-1":{"w":"관세법 제122조 제3항이 심사청구서를 받은 세관장은 받은 날부터 7일 안에 의견서를 붙여 관세청장에게 보내도록 정한다.","c":"상","v":1},"관세사2026_43-18-5":{"w":"관세법 제126조 제5항이 대리인을 해임하면 그 뜻을 서면으로 재결청에 신고하도록 정한다.","c":"상","v":1},"관세사2026_43-19-1":{"w":"관세법 제112조가 관세조사를 받는 납세자에게 변호사·관세사의 조사 참여와 의견 진술을 허용한다.","c":"상","v":1},"관세사2026_43-19-2":{"w":"관세법 제110조 제3항이 납세자를 긴급히 체포·압수·수색하는 경우 납세자권리헌장을 내주지 않을 수 있다고 정한다.","c":"상","v":1},"관세사2026_43-19-4":{"w":"관세법 제110조의3 제1항 제3호가 무작위추출방식 표본조사를 세관장의 정기선정 사유로 정한다.","c":"상","v":1},"관세사2026_43-19-5":{"w":"관세법 제121조 제1항이 심사청구는 처분을 안 날(통지를 받은 경우 받은 날)부터 90일 안에 제기하도록 정한다.","c":"상","v":1},"관세사2017_34-02-1":{"w":"관세법 제208조 제1항 단서 제1호·제2호가 살아 있는 동식물과 부패하거나 부패할 우려가 있는 물품은 장치기간 경과 전에도 공고 후 매각할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-02-2":{"w":"관세법 제208조 제2항이 제1항 각 호 물품(창고·다른 외국물품에 해를 끼칠 우려가 있는 것 포함)으로서 급박해 공고할 여유가 없으면 먼저 매각하고 나중에 공고할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-02-4":{"w":"관세법 제208조 제4항 제1호가 사이버몰 등에서 전자문서로 신속히 매각하려는 경우 매각대행기관에 대행시킬 수 있다고 정한다. 이때 매각대행기관의 장을 세관장으로 본다(같은 조 제5항).","c":"상","v":1},"관세사2017_34-02-5":{"w":"관세법 제209조 제1항이 매각 전에 화주등에게 통고일부터 1개월 안에 수출·수입·반송하라고 통고하도록 정한다. 화주등이 불분명하면 공고로 갈음한다(같은 조 제2항).","c":"상","v":1},"관세사2017_34-04-5":{"w":"관세법 제178조 제4항이 반입정지 갈음 과징금을 기한까지 내지 않으면 그 징수에 제26조를 준용하도록 정한다. 과징금은 매출액의 100분의 3 이하다(같은 조 제3항).","c":"상","v":1},"관세사2017_34-05-2":{"w":"관세법 제143조 제7항이 하역·환적 허가 대상 물품의 종류·수량, 사용·판매내역 관리, 하역·환적 절차를 관세청장이 고시하도록 정한다. 2020년 개정으로 기용품은 항공기용품, 외국무역기는 국제무역기로 이름이 바뀌었다.","c":"상","v":1},"관세사2017_34-05-3":{"w":"관세법 제143조 제3항이 하역 물품의 종류·수량은 항공기 종류·무게·운행일수·여객과 승무원 수 등을 고려해 세관장이 타당하다고 인정하는 범위여야 한다고 정한다. 지금 법문 용어는 항공기용품·국제무역기다.","c":"상","v":1},"관세사2017_34-05-4":{"w":"관세법 제143조 제2항이 외국에서 도착한 외국물품인 선박용품은 보세구역에서 국제무역선에 적재하는 경우에만 외국물품 상태로 적재할 수 있다고 정한다. 선용품·외국무역선은 2020년 개정으로 선박용품·국제무역선이 되었다.","c":"상","v":1},"관세사2017_34-05-5":{"w":"허가 내용대로 적재되지 않은 외국물품은 허가받은 자에게서 즉시 관세를 징수하지만 세관장이 지정한 기간 안에 다시 보세구역에 반입되면 징수하지 않는다(관세법 제143조 제6항 제1호). 지금 용어는 항공기용품이다.","c":"상","v":1},"관세사2018_35-23-1":{"w":"관세법 제136조 제1항이 출항 전에 세관장의 출항허가를 받도록 정한다. 2020년 개정으로 외국무역선·외국무역기는 국제무역선·국제무역기, 개항은 국제항으로 이름이 바뀌었다.","c":"상","v":1},"관세사2018_35-23-2":{"w":"관세법 제133조 제1항이 대통령령으로 지정하도록 정한다. 2020년 개정으로 개항의 이름이 국제항으로 바뀌었다.","c":"상","v":1},"관세사2018_35-23-3":{"w":"관세법 제133조 제2항이 시설기준 등을 대통령령으로 정하도록 한다. 지정요건은 관세법 시행령 제155조의2에 있고 2020년 개정으로 개항은 국제항으로 이름이 바뀌었다.","c":"상","v":1},"관세사2018_35-23-4":{"w":"관세법 제134조 제1항이 국제무역선·국제무역기는 국제항에서만 운항하고 출입허가를 받으면 그 밖의 지역에도 출입할 수 있다고 정한다. 2020년 개정 전 용어가 외국무역선·외국무역기·개항이다.","c":"상","v":1},"관세사2018_35-24-1":{"w":"관세법 제148조 제1항이 국경출입차량은 관세통로를 경유하도록 정한다.","c":"상","v":1},"관세사2018_35-24-2":{"w":"관세법 제148조 제1항 후단이 국경출입차량은 통관역이나 통관장에 정차하도록 정한다.","c":"상","v":1},"관세사2018_35-24-3":{"w":"관세법 제148조 제3항이 통관역은 국외와 연결되고 국경에 근접한 철도역 중에서 관세청장이 지정하도록 정한다. 관세통로와 통관장은 세관장이 지정한다.","c":"상","v":1},"관세사2018_35-24-4":{"w":"관세법 제148조 제4항이 통관장은 관세통로에 접속한 장소 중에서 세관장이 지정하도록 정한다.","c":"상","v":1},"관세사2018_35-25-2":{"w":"관세법 제154조가 보세구역을 지정보세구역·특허보세구역·종합보세구역으로 나눈다.","c":"상","v":1},"관세사2018_35-25-3":{"w":"관세법 제154조가 지정보세구역을 지정장치장과 세관검사장으로 나눈다.","c":"상","v":1},"관세사2018_35-25-4":{"w":"관세법 제157조 제1항이 보세구역에 물품을 반입·반출하려는 자는 세관장에게 신고하도록 정한다.","c":"상","v":1},"관세사2018_35-25-5":{"w":"관세법 제154조가 특허보세구역을 보세창고·보세공장·보세전시장·보세건설장·보세판매장의 다섯으로 나눈다.","c":"상","v":1},"관세사2018_35-26-2":{"w":"관세법 제158조 제1항 후단이 보세구역 안 보수작업이 곤란하다고 세관장이 인정하면 기간과 장소를 지정받아 밖에서 할 수 있다고 정한다. 보수작업은 세관장 승인 사항이다(같은 조 제2항).","c":"상","v":1},"관세사2023_40-17-2":{"w":"관세법 시행령 제156조 제1항 단서가 국제무역선·국제무역기 항행의 편의 등 특별한 사정이 있으면 관할 세관장이 아닌 세관장에게 신청서를 낼 수 있게 한다. 허가한 세관장은 관할 세관장에게 지체 없이 통보한다(같은 조 제2항).","c":"상","v":1},"관세사2023_40-17-3":{"w":"관세법 제134조 제3항이 출입허가 신청을 받은 날부터 10일 안에 허가 여부를 통지하도록 정한다. 기간 안에 통지하지 않으면 허가한 것으로 본다(같은 조 제4항).","c":"상","v":1},"관세사2023_40-17-4":{"w":"관세법 시행규칙 제62조 제1항이 출입허가수수료를 표에 따라 계산하되 1만원 미만은 1만원으로 하고 총액은 50만원을 넘지 못하게 한다.","c":"상","v":1},"관세사2023_40-17-5":{"w":"관세법 시행규칙 제62조 제2항 제4호가 국제항 협소 등 입항여건을 고려해 관세청장이 정한 장소에 입항하는 경우를 수수료 면제 사유로 정한다.","c":"상","v":1},"관세사2023_40-29-1":{"w":"관세법 제172조 제2항 단서가 세관장이 관리하는 시설이 아니면 시설의 소유자나 관리자와 협의해 화물관리인을 지정하도록 정한다.","c":"상","v":1},"관세사2023_40-29-2":{"w":"관세법 제172조 제5항이 불가피한 사유로 화물관리인을 지정할 수 없으면 세관장이 직접 화물관리를 하고 비용을 화주에게서 징수할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-29-3":{"w":"관세법 시행령 제187조 제1항 제2호가 관세행정·보세화물 관리와 관련 있는 비영리법인을 화물관리인 지정 대상으로 정한다.","c":"상","v":1},"관세사2023_40-29-4":{"w":"관세법 시행령 제187조 제2항 제1호가 직접 물품관리를 하는 국가기관의 장은 세관장이 요청하고 그가 승낙하면 화물관리인으로 지정한다고 정한다.","c":"상","v":1},"관세사2024_41-18-5":{"w":"관세법 제210조 제1항이 매각 방법을 일반경쟁입찰·지명경쟁입찰·수의계약·경매·위탁판매로 정한다.","c":"상","v":1},"관세사2024_41-20-1":{"w":"관세법 시행규칙 제62조 제1항 후단이 국제항이 아닌 지역 출입허가수수료 총액은 50만원을 넘지 못한다고 정한다.","c":"상","v":1},"관세사2025_42-31-1":{"w":"관세법 제133조 제1항이 국제항을 대통령령으로 지정하도록 정한다.","c":"상","v":1},"관세사2025_42-31-2":{"w":"관세법 시행령 제155조의2 제1항 제3호 나목이 항구의 국제항 지정요건을 국제무역선인 5천톤급 이상 선박이 연간 50회 이상 입항하거나 입항할 것으로 예상되는 것으로 정한다.","c":"상","v":1},"관세사2025_42-31-3":{"w":"관세법 제133조 제2항이 국제항의 시설기준 등을 대통령령으로 정하도록 위임한다.","c":"상","v":1},"관세사2025_42-31-5":{"w":"관세법 시행규칙 제62조 제2항 제3호가 유조선 청소 등을 위해 법령이나 행정관청이 정한 장소에 입항하는 경우 출입허가수수료를 징수하지 않도록 정한다.","c":"상","v":1},"관세사2025_42-32-3":{"w":"관세법 시행규칙 제68조 제7항이 우리나라에 있는 외국공관이 직접 운영하는 보세전시장의 특허수수료를 면제한다.","c":"상","v":1},"관세사2025_42-33-2":{"w":"관세법 제173조 제2항이 세관장은 관세청장이 정하는 바에 따라 검사할 물품의 전부나 일부를 세관검사장에 반입해 검사할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-33-3":{"w":"관세법 제173조 제3항 본문이 세관검사장 반입 물품의 채취·운반 등 검사비용을 화주가 부담하도록 정한다. 중소·중견기업 컨테이너 화물 등은 국가가 지원할 수 있다(같은 항 단서).","c":"상","v":1},"관세사2025_42-33-4":{"w":"관세법 제173조 제3항 단서와 같은 법 시행령 제187조의4 제1항 제3호·제2항이 검사 결과 관세법·대외무역법 등 수출입 관련 법령 위반으로 통고처분이나 고발을 받지 않을 것을 지원 요건으로 정한다.","c":"상","v":1},"관세사2025_42-33-5":{"w":"관세법 시행령 제187조의4 제1항 제4호가 검사 결과 제출한 신고자료(적재화물목록 제외)가 실제 물품과 일치할 것을 검사비용 지원 요건으로 정한다.","c":"상","v":1},"관세사2026_43-21-1":{"w":"관세법 제176조 제1항이 특허기간을 10년 이내로 하고 보세전시장·보세건설장은 박람회·공사 기간을 고려해 세관장이 정하도록 한다(같은 조 제2항).","c":"상","v":1},"관세사2026_43-21-2":{"w":"관세법 시행규칙 제68조 제1항이 특허신청 수수료를 4만5천원으로 정한다.","c":"상","v":1},"관세사2026_43-21-3":{"w":"관세법 시행규칙 제68조 제7항이 외국공관이 직접 운영하는 보세전시장의 특허수수료를 면제한다.","c":"상","v":1},"관세사2026_43-21-5":{"w":"관세법 제180조 제3항이 세관장은 특허보세구역 운영에 필요한 시설·기계·기구의 설치를 명할 수 있다고 정한다. 운영인 감독과 보고 명령도 같은 조에 있다.","c":"상","v":1},"관세사2018_35-27-1":{"w":"관세법 제225조 제1항이 보세화물을 취급하는 선박회사·항공사(대행자 포함)에게 세관장 신고 의무를 지우고 주소 등 중요 사항이 바뀌면 그때도 신고하게 한다.","c":"상","v":1},"관세사2018_35-27-2":{"w":"관세법 제223조의2가 보세운송업자등의 성명·상호 대여와 등록증 대여를 금지한다.","c":"상","v":1},"관세사2018_35-27-3":{"w":"관세법 제216조 제1항이 감시·단속에 필요하면 세관장이 관세청장이 정하는 바에 따라 보세운송 통로를 제한할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-27-5":{"w":"관세법 제221조 제1항이 내국물품을 국제무역선·국제무역기로 운송하려면 세관장에게 내국운송 신고를 하도록 정한다. 2020년 개정으로 외국무역선·외국무역기의 이름이 국제무역선·국제무역기로 바뀌었다.","c":"상","v":1},"관세사2019_36-29-3":{"w":"관세법 제201조 제3항이 종합보세구역 운영인이 반입물품을 안에서 이동·사용·처분할 때 장부나 전산처리장치로 기록을 유지하도록 정한다.","c":"상","v":1},"관세사2022_39-21-4":{"w":"관세법 시행령 제190조 제1항이 장치물품 종류, 특허작업 종류나 작업 원재료를 바꾸려는 특허보세구역 운영인에게 사유를 적은 신청서를 내 세관장 승인을 얻도록 정한다.","c":"상","v":1},"관세사2022_39-22-1":{"w":"관세법 제198조 제1항이 종합보세기능을 수행하려는 자는 그 기능을 정해 세관장에게 종합보세사업장 설치·운영 신고를 하도록 정한다. 특허가 아니라 신고다.","c":"상","v":1},"관세사2022_39-22-2":{"w":"관세법 제198조 제3항이 종합보세사업장 운영인이 종합보세기능을 바꾸려면 세관장에게 신고하도록 정한다.","c":"상","v":1},"관세사2022_39-22-3":{"w":"관세법 제199조 제2항이 종합보세구역 반입·반출 물품이 내국물품이면 재정경제부령에 따라 신고를 생략하거나 간소하게 할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-22-4":{"w":"관세법 제202조 제2항이 종합보세구역 장치물품의 보수작업과 구역 밖 보세작업을 세관장 신고 사항으로 정한다. 특허보세구역의 보수작업이 승인 사항인 것과 다르다.","c":"상","v":1},"관세사2026_43-24-4":{"w":"관세법 제221조 제1항이 내국물품을 국제무역선·국제무역기로 운송하려면 세관장에게 내국운송 신고를 하도록 정한다.","c":"상","v":1},"관세사2017_34-06-2":{"w":"관세법 제233조 제2항 제1호가 외국세관등이 재정경제부령으로 정한 기간 안에 회신하지 않으면 일반특혜·국제협력·편익관세를 적용하지 않을 수 있다고 정한다. 조약·협정이 달리 정하면 그에 따른다.","c":"상","v":1},"관세사2017_34-06-3":{"w":"관세법 제233조 제3항 제2호가 외국 권한기관의 확인 요청을 받은 경우 등에 원산지증명서를 발급한 자를 서면조사나 현지조사의 대상으로 정한다.","c":"상","v":1},"관세사2017_34-06-4":{"w":"관세법 제233조 제2항 제2호와 후단이 신고 원산지가 실제와 다르면 협정관세 등을 배제하고 제38조의3 제6항·제39조 제2항에 따라 세액이나 차액을 부과·징수하도록 정한다.","c":"상","v":1},"관세사2017_34-06-5":{"w":"관세법 제233조 제2항 제3호가 외국세관등의 회신에 원산지증명서·확인자료를 확인하는 데 필요한 정보가 없으면 일반특혜·국제협력·편익관세를 적용하지 않을 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-07-1":{"w":"관세법 제229조 제1항 제2호가 2개국 이상에 걸쳐 생산된 물품은 본질적 특성을 부여할 만한 실질적 생산·가공·제조 과정을 최종적으로 수행한 나라를 원산지로 정한다.","c":"상","v":1},"관세사2017_34-07-2":{"w":"관세법 시행규칙 제74조 제2항이 2개국 이상에서 생산된 물품은 사용된 물품과 다른 6단위 품목번호의 물품을 최종적으로 생산한 국가를 원산지로 정한다. 단순 포장·선별·조립 등은 인정하지 않는다(같은 조 제4항).","c":"상","v":1},"관세사2017_34-07-3":{"w":"관세법 제230조 제2호가 원산지 표시가 부정한 방법으로 사실과 다르게 된 물품의 통관을 허용하지 않도록 정한다. 위반이 경미하면 보완·정정 후 통관할 수 있다(같은 조 단서).","c":"상","v":1},"관세사2017_34-07-4":{"w":"관세법 제230조의2가 품질등을 오인할 수 있게 표시하거나 그런 표지를 붙인 물품으로서 부정경쟁방지법·식품위생법·산업표준화법 등을 위반한 물품의 통관을 허용하지 않도록 정한다.","c":"상","v":1},"관세사2017_34-08-1":{"w":"관세법 시행규칙 제74조 제1항 제4호가 당해 국가의 선박이 채집·포획한 어획물 등을 그 국가를 원산지로 하는 완전생산물로 정한다.","c":"상","v":1},"관세사2017_34-08-2":{"w":"관세법 시행규칙 제75조 제1항 제1호가 촬영된 영화용 필름의 원산지를 제작자가 속하는 국가로 정한다.","c":"상","v":1},"관세사2017_34-08-3":{"w":"관세법 시행규칙 제75조 제1항 제2호가 기계·기구·장치·차량과 함께 수입되어 동시에 판매되는 통상적인 부속품·예비부분품·공구는 그 기계 등의 원산지를 따르도록 정한다.","c":"상","v":1},"관세사2017_34-08-5":{"w":"관세법 시행규칙 제76조의 직접운송원칙이다. 단순 경유하면서 관세당국 통제 아래 보세구역에 장치되고 추가 작업이 없었던 물품이나 전시 후 수출된 물품은 직접 반입한 것으로 본다.","c":"상","v":1},"관세사2017_34-09-1":{"w":"관세법 제232조 제2항이 원산지증명서를 내지 않으면 일반특혜·국제협력·편익관세를 배제하는 등 관세 편익을 적용하지 않을 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-09-2":{"w":"관세법 제232조 제4항이 원산지증명서확인자료 제출자가 정당한 사유를 들어 비공개를 요청하면 명시적 동의 없이 공개하지 못하도록 정한다.","c":"상","v":1},"관세사2017_34-09-4":{"w":"관세법 시행령 제236조 제4항이 원산지증명서는 제출일부터 소급해 1년 이내에 발행된 것이어야 한다고 정한다. 도착 후 신고 지연이나 천재지변 기간은 빼고 센다.","c":"상","v":1},"관세사2017_34-09-5":{"w":"관세법 시행령 제236조 제4항이 원산지증명서에 품명·수량·생산지·수출자 등 관세청장이 정하는 사항이 적혀 있어야 한다고 정한다.","c":"상","v":1},"관세사2017_34-11-1":{"w":"관세법 제253조 제1항이 수입신고 전에 운송수단·관세통로·하역통로·장치 장소에서 즉시 반출하려면 즉시반출신고를 하도록 정한다.","c":"상","v":1},"관세사2017_34-11-2":{"w":"관세법 제253조 제1항 후단이 세관장은 즉시반출신고자에게 관세 상당 담보를 제공하게 할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-11-3":{"w":"관세법 제253조 제3항이 즉시반출신고일부터 10일 안에 수입신고를 하도록 정한다. 기간 안에 하지 않으면 관세를 부과·징수하고 100분의 20 가산세를 물린다(같은 조 제4항).","c":"상","v":1},"관세사2017_34-11-5":{"w":"관세법 시행령 제257조 제1항이 즉시반출신고서에 품명·규격·수량·가격을 적도록 정한다.","c":"상","v":1},"관세사2018_35-28-1":{"w":"관세법 제240조의6 제2항이 세계관세기구가 정한 수출입 신고항목과 화물식별번호 정보를 상호 조건에 따라 다른 국가와 교환할 수 있게 한다.","c":"상","v":1},"관세사2018_35-28-2":{"w":"관세법 제240조의6 제3항이 관세 부과·징수, 불복 심리, 형사소추 등을 위해 협정·국제협약에 따라 수출입신고자료 등을 다른 국가와 교환할 수 있게 한다. 지금은 수출입신고의 검증도 목적에 들어간다.","c":"상","v":1},"관세사2018_35-28-4":{"w":"관세법 제240조의6 제1항이 신속한 통관과 위반물품 반입 방지를 위해 관세청장이 세계관세기구의 신고항목·화물식별번호를 발급하거나 사용하게 할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-28-5":{"w":"관세법 제240조의6 제4항이 관세청장이 상호주의 원칙에 따라 상대국에 대한 수출입신고자료 제공을 제한할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-29-1":{"w":"관세법 제246조 제2항이 관세청장에게 검사대상·범위·방법 등의 기준을 정할 권한을 준다. 지금은 검사 장비·시설과 인력 양성도 포함된다.","c":"상","v":1},"관세사2018_35-29-2":{"w":"관세법 제246조 제3항이 화주는 수입신고 전에 관세청장이 정하는 바에 따라 물품을 확인할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-29-3":{"w":"관세법 제246조의3 제7항이 안전성 검사 정보교류 등을 협의하기 위해 관세청에 수출입물품안전관리기관협의회를 두도록 정한다.","c":"상","v":1},"관세사2018_35-29-5":{"w":"관세법 제246조의3에 따라 세관장은 제226조 확인 대상 물품 등의 성분·품질 안전성 검사를 한다. 지금 조문은 관세청장이 중앙행정기관의 장의 요청을 받아 세관장에게 검사를 하게 하고 세관장은 지정 물품을 중앙행정기관의 장과 협력해 검사하는 구조다(제1항·제5항).","c":"중","v":1},"관세사2018_35-31-2":{"w":"관세법 제244조 제1항이 신속한 통관이 필요하면 선박·항공기 입항 전에 수입신고를 할 수 있게 하고 이 물품은 우리나라에 도착한 것으로 본다.","c":"상","v":1},"관세사2018_35-31-3":{"w":"관세법 제244조 제2항이 입항전수입신고 물품을 검사하기로 하면 신고인에게 통보하도록 정한다.","c":"상","v":1},"관세사2018_35-31-4":{"w":"관세법 제244조 제3항이 검사대상 물품은 신고 세관 관할 보세구역(보세구역 외 장치 장소 포함)에 반입하되 적재상태 검사가 가능하면 선박·항공기에서 검사할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-31-5":{"w":"관세법 제244조 제6항이 입항전수입신고 물품의 통관절차 등을 관세청장이 정하도록 한다.","c":"상","v":1},"관세사2019_36-33-1":{"w":"관세법 제231조 제1항이 일시 양륙되거나 환적·복합환적되는 외국물품 중 원산지를 우리나라로 허위 표시한 물품을 세관장이 유치할 수 있다고 정한다.","c":"상","v":1},"관세사2019_36-33-2":{"w":"관세법 제230조 제1호가 원산지 표시가 법령의 기준·방법에 맞지 않으면 통관을 허용하지 않도록 정한다. 경미하면 보완 후 통관할 수 있다.","c":"상","v":1},"관세사2019_36-33-3":{"w":"관세법 제230조의2가 품질·내용·제조방법·용도·수량을 사실과 다르게 또는 오인하게 표시한 물품으로서 품질표시 관련 법령을 위반한 물품의 통관을 허용하지 않도록 정한다.","c":"상","v":1},"관세사2019_36-33-5":{"w":"관세법 제231조 제3항이 외국물품을 유치하면 화주나 위임받은 자에게 통지하도록 정한다. 이때 이행기간을 정해 원산지 표시 수정 등을 명할 수 있다(같은 조 제4항).","c":"상","v":1},"관세사2019_36-34-1":{"w":"관세법 제240조의5가 우리나라에 통관 편익을 제공하는 국가에서 수입되는 물품에 상호 조건에 따라 간이한 통관절차를 적용할 수 있게 한다.","c":"상","v":1},"관세사2019_36-34-3":{"w":"관세법 시행령 제245조의2 제2항이 무역원활화위원회를 위원장 1명 포함 20명 이내로 구성하도록 정한다. 위원장은 재정경제부차관이다(같은 조 제3항).","c":"상","v":1},"관세사2019_36-34-4":{"w":"관세법 제240조의6 제1항이 관세청장이 세계관세기구의 수출입 신고항목과 화물식별번호를 발급하거나 사용하게 할 수 있다고 정한다.","c":"상","v":1},"관세사2019_36-34-5":{"w":"관세법 제240조의4 제2항이 재정경제부장관은 무역원활화 기본계획 시행을 위해 관련 업무를 하는 기관·단체에 필요한 지원을 할 수 있다고 정한다.","c":"상","v":1},"관세사2019_36-36-3":{"w":"관세법 시행령 제257조 제1항이 즉시반출신고서에 품명·규격·수량·가격을 적도록 정한다.","c":"상","v":1},"관세사2022_39-02-2":{"w":"관세법 시행령 제3조 제1항 제1호 라목이 수입물품 가격결정 자료의 보관기간을 신고 수리일부터 5년으로 정한다.","c":"상","v":1},"관세사2022_39-02-3":{"w":"관세법 시행령 제3조 제1항 제1호 나목이 수입거래 계약서나 이를 갈음하는 서류를 수리일부터 5년 보관하도록 정한다.","c":"상","v":1},"관세사2022_39-02-4":{"w":"관세법 시행령 제3조 제1항 제2호 다목이 수출물품·반송물품 가격결정 자료를 수리일부터 3년 보관하도록 정한다.","c":"상","v":1},"관세사2022_39-02-5":{"w":"관세법 시행령 제3조 제1항 제3호 나목이 적재화물목록 자료를 수리일부터 2년 보관하도록 정한다. 보세화물 반출입·보세운송 자료도 2년이다.","c":"상","v":1},"관세사2022_39-28-1":{"w":"관세법 제256조 제1항이 통관우체국 경유 대상인 우편물에서 서신을 뺀다. 그래서 서신은 반송할 때도 통관우체국을 거칠 필요가 없다.","c":"상","v":1},"관세사2022_39-28-2":{"w":"관세법 제256조 제2항이 통관우체국은 체신관서 중에서 관세청장이 지정한다고 정한다.","c":"상","v":1},"관세사2022_39-28-3":{"w":"관세법 제258조 제2항의 위임에 따라 관세법 시행령 제261조 제1호가 법령상 수출입이 제한되거나 금지되는 물품을 수출입신고 대상 우편물로 정한다.","c":"상","v":1},"관세사2022_39-28-4":{"w":"관세법 제260조 제2항이 관세를 징수해야 하는 우편물은 관세를 징수하기 전에 수취인에게 내주지 못하도록 정한다.","c":"상","v":1},"관세사2023_40-23-2":{"w":"관세법 제246조 제2항이 관세청장에게 검사대상·범위·방법 등의 기준을 정할 권한을 준다.","c":"상","v":1},"관세사2023_40-23-3":{"w":"관세법 제246조 제3항이 화주는 수입신고 전에 관세청장이 정하는 바에 따라 물품을 확인할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-23-4":{"w":"관세법 제246조 제1항이 세관공무원은 수출·수입·반송하려는 물품을 검사할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-23-5":{"w":"관세법 시행령 제251조의2 제2항 제1호 가목이 검사 대상 물품을 수리할 수 없으면 제30조부터 제35조까지에 따른 과세가격 상당액을 보상하도록 정한다. 수리할 수 있으면 수리비 상당액이다(같은 항 제2호).","c":"상","v":1},"관세사2023_40-25-2":{"w":"관세법 제250조 제3항이 수출·수입·반송 신고나 입항전수입신고가 요건을 갖추지 못했거나 부정한 방법으로 된 경우 세관장이 각하할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-25-3":{"w":"관세법 제250조 제1항 단서가 수입·반송 신고는 운송수단·관세통로·하역통로·장치 장소에서 물품을 반출한 뒤에는 취하할 수 없다고 정한다.","c":"상","v":1},"관세사2023_40-25-4":{"w":"관세법 제250조 제2항이 신고 수리 후 취하를 승인하면 신고수리의 효력이 없어진다고 정한다.","c":"상","v":1},"관세사2023_40-25-5":{"w":"관세법 제250조 제4항이 취하 승인 신청을 받은 날부터 10일 안에 승인 여부를 통지하도록 정한다. 통지가 없으면 기간이 끝난 다음 날 승인한 것으로 본다(같은 조 제5항).","c":"상","v":1},"관세사2023_40-27-2":{"w":"관세법 제255조의5 제3호가 제255조의2 제1항의 안전관리 기준을 충족하지 못하는 경우를 공인 취소 사유로 정한다. 거짓·부정한 방법으로 공인받은 경우만 반드시 취소한다.","c":"상","v":1},"관세사2024_41-23-1":{"w":"관세법 시행령 제236조의9 제2항이 원산지표시위반단속기관협의회를 위원장 1명 포함 25명 이내로 구성하도록 정한다.","c":"상","v":1},"관세사2024_41-23-2":{"w":"관세법 시행령 제236조의9 제3항이 위원장을 원산지표시 위반 단속업무를 관장하는 관세청 고위공무원단 공무원 중 관세청장이 지정하는 사람으로 정한다.","c":"상","v":1},"관세사2024_41-23-3":{"w":"관세법 시행령 제236조의9 제3항 제4호가 특별시·광역시·특별자치시·도·특별자치도의 장이 지정하는 과장급 공무원 각 1명을 위원으로 정한다.","c":"상","v":1},"관세사2024_41-23-5":{"w":"관세법 시행령 제236조의9 제1항 제1호가 원산지표시 위반 단속업무에 필요한 정보교류를 협의사항으로 정한다. 인력교류도 들어간다(제2호).","c":"상","v":1},"관세사2025_42-29-1":{"w":"관세법 제256조의2 제4항이 법에 정한 것 외의 사전전자정보 제출 절차와 반송 등 세부사항을 대통령령으로 정하도록 한다. 관세법 시행령 제259조의8에 있다.","c":"상","v":1},"관세사2025_42-29-3":{"w":"관세법 시행령 제259조의8 제2항이 통관우체국의 장이 사전전자정보를 정보통신망으로 세관장에게 제출하도록 정한다.","c":"상","v":1},"관세사2025_42-29-4":{"w":"관세법 시행령 제259조의8 제3항이 사전전자정보 미제출 우편물을 반송하게 하기로 결정하면 세관장이 그 결정을 통관우체국의 장에게 통지하도록 정한다.","c":"상","v":1},"관세사2025_42-29-5":{"w":"관세법 시행령 제259조의8 제4항이 통지를 받은 통관우체국의 장이 수취인이나 발송인에게 결정사항을 알리고 반송하도록 정한다.","c":"상","v":1},"관세사2026_43-26-4":{"w":"관세법 시행령 제249조 제3항 제1호가 세율이 오르거나 새 수입요건을 요구하는 법령이 적용되거나 적용될 예정인 물품은 선박 등이 도착한 뒤에 수입신고하도록 정한다.","c":"상","v":1},"관세사2026_43-28-1":{"w":"관세법 제256조 제1항이 서신을 뺀 수출·수입·반송 우편물은 통관우체국을 경유하도록 정한다.","c":"상","v":1},"관세사2026_43-28-2":{"w":"관세법 제256조 제2항이 통관우체국을 체신관서 중에서 관세청장이 지정하도록 정한다.","c":"상","v":1},"관세사2026_43-28-4":{"w":"관세법 제260조 제2항이 관세를 징수해야 할 우편물은 징수 전에 수취인에게 내주지 못하도록 정한다.","c":"상","v":1},"관세사2026_43-28-5":{"w":"관세법 제261조가 우편물에 대한 관세 납세의무는 그 우편물이 반송되면 소멸한다고 정한다.","c":"상","v":1},"관세사2017_34-27-1":{"w":"관세법 제262조가 관세청장이나 세관장은 이 법이나 명령(조약·국제법규상 의무 포함)을 집행하는 데 필요하면 운송수단의 출발을 중지시키거나 진행을 정지시킬 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-27-2":{"w":"관세법 제263조가 관세청장이나 세관장이 물품·운송수단·장치 장소에 관한 서류 제출·보고를 명하거나 세관공무원에게 수출입자·판매자 등의 관계 자료를 조사하게 할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-27-4":{"w":"관세법 제265조 제1항이 위반행위 방지를 위해 필요하면 세관공무원이 물품·운송수단·장치 장소·장부·서류를 검사하거나 봉쇄할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-27-5":{"w":"관세법 제266조 제1항이 세관공무원은 직무 집행에 필요하면 수출입업자·판매업자 등에게 질문하고 장부·서류·물품을 조사하거나 제시·제출을 요구할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-30-1":{"w":"관세법 제283조 제2항이 관세범에 관한 조사·처분은 세관공무원이 한다고 정한다.","c":"상","v":1},"관세사2017_34-30-3":{"w":"관세법 시행령 제267조가 사법경찰관리 직무를 하는 세관공무원이 피의자를 구속하면 세관관서·국가경찰관서·교도관서에 유치하도록 정한다.","c":"상","v":1},"관세사2017_34-30-4":{"w":"관세법 제300조가 관세범 조사에 필요하면 세관공무원이 선박·차량·항공기·창고 등을 검증하거나 수색할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-30-5":{"w":"관세법 제301조 제1항이 피의자가 증거물품을 신변에 숨겼다고 인정되면 내보이도록 요구하고 따르지 않으면 신변을 수색할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-33-1":{"w":"관세법 제264조의5 제1항이 과세자료 제출을 요청받은 기관의 장은 다른 법령상 특별한 제한 등 정당한 사유가 없으면 협조하도록 정한다.","c":"상","v":1},"관세사2018_35-33-3":{"w":"관세법 제262조가 관세청장이나 세관장에게 명령 집행에 필요한 경우 운송수단의 출발 중지·진행 정지 권한을 준다.","c":"상","v":1},"관세사2018_35-33-4":{"w":"관세법 제264조의7 제1항이 과세자료제출기관의 장이 소속 공무원·임직원의 제출 의무 이행을 수시로 점검하도록 정한다.","c":"상","v":1},"관세사2018_35-33-5":{"w":"관세법 제264조의6 제1항이 관세청장에게 과세자료의 효율적 관리·활용을 위한 전산관리 체계 구축 등 필요한 조치를 마련하도록 정한다.","c":"상","v":1},"관세사2019_36-24-2":{"w":"관세법 제307조가 피의자·증인·참고인에 대한 조사·검증·수색·압수 중에는 누구든 그 장소 출입을 금할 수 있다고 정한다.","c":"상","v":1},"관세사2020_37-23-5":{"w":"관세법 제303조 제2항이 압수물품을 편의에 따라 소지자나 시·군·읍·면사무소에 보관시킬 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-30-1":{"w":"징역과 벌금을 병과할 수 있는 죄는 관세법 제269조부터 제271조까지와 제274조의 죄다(관세법 제275조). 제268조의2 전자문서 위조·변조죄는 여기에 없다.","c":"상","v":1},"관세사2022_39-30-2":{"w":"관세법 제271조 제1항이 정황을 알면서 제269조·제270조의 행위를 교사하거나 방조한 자를 정범에 준해 처벌한다고 정한다.","c":"상","v":1},"관세사2022_39-30-4":{"w":"관세법 제271조 제2항이 제268조의2·제269조·제270조의 미수범을 본죄에 준해 처벌한다고 정한다.","c":"상","v":1},"관세사2022_39-30-5":{"w":"관세법 제275조의2 제1항이 강제징수를 면탈할 목적으로 재산을 은닉·탈루하거나 거짓 계약을 하면 3년 이하 징역 또는 3천만원 이하 벌금에 처한다고 정한다.","c":"상","v":1},"관세사2022_39-32-1":{"w":"관세법 제292조 제2항이 조서를 진술자에게 읽어 주거나 열람하게 해 기재 사실에 다른 점이 있는지 묻도록 정한다.","c":"상","v":1},"관세사2022_39-32-3":{"w":"관세법 제296조 제2항이 소유자·점유자·보관자가 임의로 제출하거나 남겨 둔 물품은 영장 없이 압수할 수 있다고 정한다.","c":"상","v":1},"관세사2022_39-32-4":{"w":"관세법 제298조 제1항이 관세범 현행범인이 그 장소에 있으면 누구든지 체포할 수 있다고 정한다. 체포한 자는 지체 없이 세관공무원에게 인도한다(같은 조 제2항).","c":"상","v":1},"관세사2022_39-32-5":{"w":"관세법 제303조 제2항이 압수물품을 소지자나 시·군·읍·면사무소에 보관시킬 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-32-1":{"w":"관세법 시행령 제266조의5 제2항이 위원장 포함 재적위원 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결하도록 정한다.","c":"상","v":1},"관세사2023_40-32-2":{"w":"관세법 시행령 제266조의5 제3항이 간사 1명을 두고 위원장이 관세청 소속 공무원 중에서 지명하도록 정한다.","c":"상","v":1},"관세사2023_40-32-3":{"w":"관세법 시행령 제266조의5 제6항이 회의와 회의록을 비공개로 하고 위원장이 필요하다고 인정하면 공개할 수 있게 한다.","c":"상","v":1},"관세사2023_40-32-5":{"w":"관세법 시행령 제266조의5 제7항이 위원회가 필요하면 공무원 등 관계자 출석을 요청해 의견을 듣고 관련 기관에 자료를 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2023_40-33-3":{"w":"관세법 제277조의2 제1항이 직무 관련 금품을 수수한 세관공무원에 대해 금품 수수액의 5배 내 징계부가금 부과 의결을 징계위원회에 요구하도록 정한다.","c":"상","v":1},"관세사2024_41-26-1":{"w":"관세법 제264조가 관세청장이 국가기관·지방자치단체 등에 관세 부과·징수와 통관에 관계되는 자료나 통계를 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2024_41-26-2":{"w":"관세법 제264조의2 제5호가 여신전문금융업법에 따른 신용카드업자와 여신전문금융업협회를 과세자료제출기관으로 정한다.","c":"상","v":1},"관세사2024_41-26-3":{"w":"관세법 제264조의4 제2항이 과세자료를 제출할 때 그 기관이 접수하거나 작성한 자료의 목록을 함께 내도록 정한다. 제출은 분기만료일이 속하는 달의 다음 달 말일까지다(같은 조 제1항).","c":"상","v":1},"관세사2024_41-26-5":{"w":"관세법 제264조의10 제1항 제1호가 반출입 물품의 안전관리를 위해 관세청장이 중앙행정기관의 장에게 구비조건·성분·표시·품질 등을 위반한 물품 정보를 요청할 수 있다고 정한다.","c":"상","v":1},"관세사2025_42-21-4":{"w":"관세법 제301조 제2항이 여성의 신변을 수색할 때 성년의 여성을 참여시키도록 정한다.","c":"상","v":1},"관세사2025_42-26-1":{"w":"관세법 제266조의2 제1항이 제241조 제1항·제2항을 위반해 수입하는 마약류등의 위치정보를 수집할 수 있게 한다. 지금 조문은 관세청장과 세관장 모두에게 이 권한을 준다.","c":"상","v":1},"관세사2017_34-24-2":{"w":"FTA관세특례법 제14조 제1항이 수출자·생산자가 원산지 오류를 알면 세관장과 체약상대국 수입자에게 통보하도록 하고 그 기간을 같은 법 시행규칙 제19조 제1항이 오류를 안 날부터 30일로 정한다.","c":"상","v":1},"관세사2017_34-24-3":{"w":"FTA관세특례법 제16조 제1항 제1호가 원산지 확인과 협정관세 적용 심사에 필요하면 관세청장이나 세관장이 수입자에게 원산지증빙서류 등의 제출을 요구할 수 있다고 정한다. 제출기간은 20일 이상이다(같은 조 제2항).","c":"상","v":1},"관세사2017_34-24-4":{"w":"FTA관세특례법 시행령 제20조 제4항이 무역위원회의 긴급관세조치 건의를 받은 날부터 30일 안에 결정하고 필요하면 20일 범위에서 연장할 수 있다고 정한다.","c":"상","v":1},"관세사2017_34-24-5":{"w":"FTA관세특례법 제30조 제1항 제1호가 수입신고 수리일부터 2년 범위에서 대통령령으로 정한 기간 안에 다시 수출할 목적으로 일시 수입하는 물품을 원산지와 관계없이 면세할 수 있는 대상으로 정한다.","c":"상","v":1},"관세사2018_35-36-1":{"w":"FTA관세특례법 제7조 제1항 제1호가 물품 전부를 생산·가공·제조한 국가를 원산지로 정한다.","c":"상","v":1},"관세사2018_35-36-3":{"w":"FTA관세특례법 제7조 제1항 제2호 나목이 둘 이상의 국가에 걸쳐 생산된 물품에 일정 수준 이상의 부가가치를 창출한 국가를 원산지로 정한다. 세번변경(가목)과 주요공정(다목) 기준도 같은 호에 있다.","c":"상","v":1},"관세사2018_35-36-4":{"w":"FTA관세특례법 제7조 제2항이 원산지가 아닌 국가를 경유하거나 거기서 선적되면 원산지로 인정하지 않되 그 국가 보세구역에서 운송 목적의 환적·일시보관만 있었으면 예외로 한다. 협정이 다르게 정하면 협정을 따른다(같은 조 제3항).","c":"상","v":1},"관세사2018_35-36-5":{"w":"FTA관세특례법 제7조 제1항 제2호 가목이 품목번호가 재료·구성물품의 품목번호와 일정 단위 이상 다르면 최종적으로 생산·가공·제조한 국가를 원산지로 정한다.","c":"상","v":1},"관세사2019_36-37-1":{"w":"FTA관세특례법 제2조 제1항 제3호의 정의다.","c":"상","v":1},"관세사2019_36-37-3":{"w":"FTA관세특례법 제2조 제1항 제4호의 정의다. 원산지는 협정에서 정한 기준에 따라 생산 등이 이루어진 것으로 보는 국가다.","c":"상","v":1},"관세사2019_36-37-4":{"w":"FTA관세특례법 제2조 제1항 제6호의 정의다. 연도별 세율·적용기간·수량은 대통령령으로 정한다(같은 법 제4조 제1항).","c":"상","v":1},"관세사2019_36-37-5":{"w":"FTA관세특례법 제2조 제1항 제5호의 정의다. 원산지를 증명하는 서류를 원산지증명서라 하고 그 밖의 확인 서류·정보까지 합쳐 원산지증빙서류라 한다.","c":"상","v":1},"관세사2019_36-38-3":{"w":"FTA관세특례법 시행령 제7조 제1호 다목과 제2호 나목이 원산지증명서 작성대장 비치·관리와 원산지관리전담자 지정·운영을 업체별·품목별 원산지인증수출자의 공통 요건으로 정한다.","c":"상","v":1},"관세사2020_37-36-2":{"w":"FTA관세특례법 제2조 제1항 제2호의 정의다. 국가연합·경제공동체·독립된 관세영역도 체약상대국에 들어간다.","c":"상","v":1},"관세사2020_37-36-3":{"w":"FTA관세특례법 제2조 제1항 제4호의 정의다.","c":"상","v":1},"관세사2020_37-36-4":{"w":"FTA관세특례법 제3조 제1항이 이 법을 관세법보다 우선 적용하되 이 법에 없는 사항은 관세법에 따르도록 정한다.","c":"상","v":1},"관세사2020_37-36-5":{"w":"FTA관세특례법 제3조 제2항이 이 법이나 관세법이 협정과 상충하면 협정을 우선 적용한다고 정한다.","c":"상","v":1},"관세사2020_37-38-1":{"w":"FTA관세특례법 제8조 제1항이 협정관세를 적용받으려면 수입신고 수리 전까지 세관장에게 적용을 신청하도록 정한다. 놓치면 수리일부터 1년 안에 사후적용을 신청할 수 있다(같은 법 제9조 제1항).","c":"상","v":1},"관세사2020_37-38-2":{"w":"협정관세 적용신청은 수입신고 수리 후 심사가 원칙이지만 FTA관세특례법 제8조 제4항 단서가 관세채권 확보가 곤란하거나 수리 후 심사가 부적당한 재정경제부령 물품은 수리 전에 심사하도록 정한다.","c":"상","v":1},"관세사2020_37-38-4":{"w":"FTA관세특례법 제8조 제2항이 협정관세 적용을 신청할 때 수입자가 원산지증빙서류를 갖추고 있어야 하고 세관장이 요구하면 제출하도록 정한다.","c":"상","v":1},"관세사2020_37-38-5":{"w":"FTA관세특례법 시행령 제4조 제1항 제4호가 협정관세 적용신청서 기재사항에 품명·모델·규격·품목번호를 넣는다.","c":"상","v":1},"관세사2025_42-37-2":{"w":"FTA관세특례법 제5조 제1항 본문이 협정관세 세율이 관세법 제50조의 적용세율과 같거나 높으면 관세법 제50조의 세율을 우선 적용하도록 정한다.","c":"상","v":1},"관세사2025_42-37-3":{"w":"FTA관세특례법 제5조 제1항 단서가 두 세율이 같을 때 수입자가 협정관세 적용을 신청하면 협정관세 세율을 적용하도록 정한다.","c":"상","v":1},"관세사2025_42-37-4":{"w":"FTA관세특례법 제5조 제2항이 관세법 제57조 상계관세 세율을 협정관세 세율보다 우선 적용하도록 정한다. 덤핑방지·보복·긴급관세 등도 같다.","c":"상","v":1},"관세사2025_42-37-5":{"w":"FTA관세특례법 제5조 제2항이 관세법 제63조 보복관세 세율을 협정관세 세율보다 우선 적용하도록 정한다.","c":"상","v":1},"관세사2025_42-38-1":{"w":"FTA관세특례법 제8조 제1항이 협정관세 적용을 수입신고 수리 전까지 세관장에게 신청하도록 정한다.","c":"상","v":1},"관세사2025_42-38-2":{"w":"FTA관세특례법 시행령 제4조 제5항 제1호가 유효기간이 지나기 전에 물품이 수입항에 도착한 경우 도착일 다음 날부터 협정관세 적용 신청일까지를 유효기간 계산에서 빼도록 정한다.","c":"상","v":1},"관세사2025_42-38-3":{"w":"FTA관세특례법 시행령 제4조 제5항 제2호가 천재지변 등 불가항력으로 운송이 지연되면 사유 발생일 다음 날부터 소멸일까지를 유효기간 계산에서 빼도록 정한다.","c":"상","v":1},"관세사2025_42-38-4":{"w":"FTA관세특례법 제9조 제1항이 수리 전까지 적용신청을 못 한 수입자는 수입신고 수리일부터 1년 안에 협정관세 사후적용을 신청할 수 있다고 정한다.","c":"상","v":1},"관세사2026_43-35-1":{"w":"FTA관세특례법 제2조 제1항 제4호의 정의다.","c":"상","v":1},"관세사2026_43-35-2":{"w":"FTA관세특례법 제2조 제1항 제3호의 정의다.","c":"상","v":1},"관세사2026_43-35-3":{"w":"FTA관세특례법 제4조 제1항이 협정관세의 연도별 세율·적용기간·적용수량을 협정의 철폐비율·인하비율·수량기준에 따라 대통령령으로 정하도록 한다.","c":"상","v":1},"관세사2026_43-35-4":{"w":"FTA관세특례법 제12조 제1항이 원산지증명능력 등 대통령령으로 정한 요건을 갖춘 수출자를 관세청장이나 세관장이 원산지인증수출자로 인증할 수 있다고 정한다.","c":"상","v":1},"관세사2018_35-10-5":{"old":1,"ow":"출제 당시 정답 O. 2019.12.31 개정(2020.1.1 시행)으로 가산금·중가산금이 납부지연가산세로 바뀌었다. 지금은 매달 1천분의 12를 더하는 중가산금이 없고, 미납세액에 하루 단위 이자율을 곱한 가산세를 납부고지서상 납부기한 다음 날부터 5년 한도로 매기므로 틀린 문장이다(관세법 제42조 제1항 제2호 가목, 제4항)."},"관세사2018_35-10-1":{"old":1,"ow":"출제 당시 정답 O. 2019.12.31 개정(2020.1.1 시행)으로 가산금 제도가 없어지고 납부지연가산세로 합쳐졌다. 100분의 3은 지금 가산세로 매기며, 납부고지서에 따른 납부기한까지 완납하지 않은 세액에 붙는다. 가산금을 징수한다는 문장은 현행법으로는 틀린다(관세법 제42조 제1항 제2호 나목)."},"관세사2020_37-34-1":{"old":1,"ow":"출제 당시 정답 O. 원산지확인위원회를 정한 관세법 시행령 제236조의4가 2022.2.15 개정으로 삭제되어, 지금은 이 위원회의 구성·위원 규정이 없으므로 맞는 문장으로 볼 수 없다."},"관세사2020_37-34-2":{"old":1,"ow":"출제 당시 정답 O. 원산지확인위원회를 정한 관세법 시행령 제236조의4가 2022.2.15 개정으로 삭제되어, 지금은 이 위원회의 구성·위원 규정이 없으므로 맞는 문장으로 볼 수 없다."},"관세사2020_37-34-4":{"old":1,"ow":"출제 당시 정답 O. 원산지확인위원회를 정한 관세법 시행령 제236조의4가 2022.2.15 개정으로 삭제되어, 지금은 이 위원회의 구성·위원 규정이 없으므로 맞는 문장으로 볼 수 없다."},"관세사2020_37-34-5":{"old":1,"ow":"출제 당시 정답 O. 원산지확인위원회를 정한 관세법 시행령 제236조의4가 2022.2.15 개정으로 삭제되어, 지금은 이 위원회의 구성·위원 규정이 없으므로 맞는 문장으로 볼 수 없다."},"관세사2018_35-01-1":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 관세법 개정으로 용어가 「국제무역기」로 바뀌었다. 지금은 무역을 위해 우리나라와 외국 간을 운항하는 항공기를 국제무역기라 하고 「외국무역기」라는 정의는 없다(관세법 제2조 제7호)."},"관세사2018_35-01-2":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 관세법 개정으로 「선용품」이 「선박용품」으로 바뀌어 지금 정의는 선박용품에 준하는 물품으로서 해당 차량에서만 사용되는 것이다(관세법 제2조 제12호)."},"관세사2018_35-01-4":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 관세법 개정으로 「내항기」가 「국내운항기」로 바뀌었다. 지금은 국내에서만 운항하는 항공기를 국내운항기라 한다(관세법 제2조 제9호)."},"관세사2018_35-01-5":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 관세법 개정으로 「선용품」이 「선박용품」으로 바뀌었다. 정의 내용은 그대로이고 용어만 선박용품이다(관세법 제2조 제10호)."},"관세사2017_34-36-1":{"old":1,"ow":"출제 당시 정답 O. 2019.2.12 관세법 시행령 개정으로 관세품목분류위원회 정원이 위원장 1명과 30명 이상 40명 이하의 위원으로 늘어 20명 이상 30명 이하는 지금 기준과 다르다(관세법 시행령 제100조 제1항)."},"관세사2017_34-36-4":{"old":1,"ow":"출제 당시 정답 O. 2019.2.12 관세법 시행령 개정으로 회의는 위원장과 위원장이 매 회의마다 지정하는 14명 이상 16명 이하의 위원으로 구성하고 관계중앙행정기관 공무원 위원 2명 이상과 민간위원 8명 이상을 넣어야 한다. 14인으로 고정한 규정은 없다(관세법 시행령 제101조 제2항)."},"관세사2017_34-39-5":{"old":1,"ow":"출제 당시 정답 O. 2018.12.31 관세법 개정으로 외국에서 선박·항공기 일부를 수리·개체하는 데 쓴 물품을 간이세율 대상으로 한 제81조 제1항 제3호와 그 과세가격을 외화가격으로 정한 제2항이 삭제되었다. 지금은 이런 규정이 없다."},"관세사2017_34-35-3":{"old":1,"ow":"출제 당시 정답 O. 2023년 관세법 시행규칙 개정으로 향수의 별도면세범위가 60밀리리터에서 100밀리리터로 늘었다. 지금은 60밀리리터를 넘어도 100밀리리터 이하면 면제되고 100밀리리터를 넘을 때 그 가격을 과세가격으로 한다(관세법 시행규칙 제48조 제3항)."},"관세사2018_35-08-5":{"old":1,"ow":"출제 당시 정답 O. 국세기본법 제46조의2가 국세징수법으로 옮겨지면서 2020.12.22 관세법 개정으로 준용 조문이 바뀌었다. 지금 관세의 신용카드 등 납부는 국세징수법 제12조 제1항 제3호·제2항·제3항을 준용한다(관세법 제38조 제7항)."},"관세사2018_35-10-2":{"old":1,"ow":"출제 당시 정답 O. 2019.12.31 관세법 개정(2020.1.1 시행)으로 가산금이 없어져 납부지연가산세로 합쳐졌다. 지금 국가에 기증되는 물품은 제42조 제1항 제1호·제2호의 가산세를 감면하는 대상이다(관세법 제42조의2 제1항 제6호, 같은 법 시행령 제39조 제2항·제32조의4 제5항)."},"관세사2018_35-10-3":{"old":1,"ow":"출제 당시 정답 O. 2019.12.31 관세법 개정(2020.1.1 시행)으로 가산금이 없어졌다. 지금 지방자치단체조합이 직접 수입하는 물품은 가산세 감면 대상이다(관세법 제42조의2 제1항 제6호, 같은 법 시행령 제39조 제2항·제32조의4 제5항 제1호)."}};
